INSERT INTO `cevopu_wp_posts` VALUES (99,1,'2026-01-18 15:07:05','2026-01-18 15:07:05','<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>ЦЕНТАР ЗА КУЛТУРА&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>ГОЛЕМА САЛА<br>капацитет 676 седишта</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":340,\"width\":\"825px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"margin\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<figure class=\"wp-block-image size-full is-resized is-style-default\" id=\"is-style-default-\" style=\"margin-right:0;margin-left:0\"><img src=\"https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/01/05-768x448-1.jpg\" alt=\"\" class=\"wp-image-340\" style=\"width:825px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>МАЛА САЛА</strong><br><strong>капацитет 100 седишта</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":342,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/01/DSCN0396-768x576-1-1.jpg\" alt=\"\" class=\"wp-image-342\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>ИЗЛОЖБЕН САЛОН</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":343,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/01/01-foaje-768x325-1.jpg\" alt=\"\" class=\"wp-image-343\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Ресурси','','publish','closed','closed','','%d1%80%d0%b5%d1%81%d1%83