INSERT INTO `cevopu_wp_posts` VALUES (309,1,'2026-01-22 20:39:58','2026-01-22 20:39:58','/* Event cards */\n.blog-layout-1 .ast-article-post {\n    background: #ffffff;\n    border-radius: 12px;\n    overflow: hidden;\n    box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n    transition: transform 0.25s ease, box-shadow 0.25s ease;\n}\n\n.blog-layout-1 .ast-article-post:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 14px 35px rgba(0,0,0,0.12);\n}\n\n/* Image */\n.blog-layout-1 .post-thumb img {\n    border-radius: 12px 12px 0 0;\n}\n\n/* Title */\n.blog-layout-1 .entry-title a {\n    color: #111;\n    text-decoration: none;\n}\n\n.blog-layout-1 .entry-title a:hover {\n    color: #b40000; /* можеш да ја смениш во боја од логото */\n}\n\n\n/* Pagination */\n.ast-pagination a,\n.ast-pagination span {\n    padding: 10px 14px;\n    margin: 0 4px;\n    border-radius: 8px;\n    background: #f2f2f2;\n    color: #111;\n}\n\n.ast-pagination .current {\n    background: #b40000;\n    color: #fff;\n}\n','astra','','publish','closed','closed','','astra','','','2026-01-22 20:39:58','2026-01-22 20:39:58','',0,'http://kulturendomtrajkoprokopiev.local/astra/',0,'custom_css','',0);
