INSERT INTO `wp_posts` VALUES (166,1,'2026-01-18 16:24:12','2026-01-18 16:24:12','<!-- wp:query {\"queryId\":6,\"query\":{\"perPage\":10,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"exclude\",\"inherit\":false,\"taxQuery\":{\"category\":[91]}},\"metadata\":{\"categories\":[\"posts\"],\"patternName\":\"core/query-grid-posts\",\"name\":\"Grid\"},\"className\":\"cards-equal\"} -->\n<div class=\"wp-block-query cards-equal\"><!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":2,\"minimumColumnWidth\":null}} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|30\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|black\"}}},\"border\":{\"width\":\"10px\"}},\"textColor\":\"black\",\"borderColor\":\"cyan-bluish-gray\",\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group has-border-color has-cyan-bluish-gray-border-color has-black-color has-text-color has-link-color\" style=\"border-width:10px;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"1\"} /-->\n\n<!-- wp:post-title {\"isLink\":true,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|black\"}}}},\"fontSize\":\"medium\"} /-->\n\n<!-- wp:post-excerpt {\"excerptLength\":10,\"fontSize\":\"small\"} /-->\n\n<!-- wp:post-date {\"metadata\":{\"bindings\":{\"datetime\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"date\"}}}}} /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:query-pagination {\"layout\":{\"ty