INSERT INTO `wp_posts` VALUES (644,1,'2026-02-08 15:20:35','2026-02-08 15:20:35','<!-- wp:image {\"id\":645,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/FILMAY-2020-cover-photo-1024x458.jpg\" alt=\"\" class=\"wp-image-645\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Фото-кино клуб “Козјак” – Куманово известува дека Вториот меѓународен фестивал на кратoк филм “ФИЛМАЈ 2020” ќе се одржи во вторник (29 септември 2020) во Големата сала на Н.У. Центар за култура “Трајко Прокопиев” – Куманово, со почеток во 19 часот.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>На овогодишниот конкурс пристигнаа 2.017 пријавени филма од 111 држави, кои беа прегледани од трочлено жири: Ана Јакимска (филмски режисер и сценарист), Златко Ѓелески (писател и културен критичар), и Глигор Максимовски (фотограф и член на фото-кино клуб `Козјак` – Куманово).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Жирито одлучи за следниве награди:<br>– награда “Лазар Ѓорѓевиќ” за најдобра режија оди кај Joey Paras за режирање на `Fetch` (Филипини)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>– награда “Радислав Ристевски” за најдобра фотографија/кинематографија е за Tim Kuhn за кинематографскиот труд во `Jupiter` (Германија).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>– награда “Козјак”за најдобра приказна/сценарио им се дава на Guy Nattiv и Sharon Maymon за aвторство на `Skin` (САД)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>– Посебна награда од жири за македонски филм е доделена на Георги М. Унковски за `Налепница`<br>Во фестивалската вечер ќе биде прикажана компактна листа од наградени и одбрани кратки филмови, во траење од 100 минути.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Согласно состојбата и протоколите, влез во салата ќе биде овозможен за публика од 110 лица кои претходно ќе имаат добиено билети. При влегувањето на секој посетител ќе му биде мерена температура и ќе се врши дезинфекција на раце, а носењето на маска на лице ќе е задолжителна при влез и за цело време на престојување внатре. Движењето ќе биде со дистанца од најмалку 2 метра, а сместувањето на публиката ќе е во секој втор ред и со растојание од 2 празни седишта помеѓу соседни посетители.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дополнителни детали може да се најдат на следниве адреси:&nbsp;<a href=\"http://www.fb.com/filmaykozjak\">ФБ страна на фестивалот ФИЛМАЈ</a>&nbsp;, како и на&nbsp;<a href=\"https://www.facebook.com/events/223721501965194/\">ФБ-страна на настанот за ФИЛМАЈ 2020</a>&nbsp;.</p>\n<!-- /wp:paragraph -->','Втор Меѓународен Фестивал на кратoк филм “ФИЛМАЈ 2020” ќе се одржи во вторник (29 септември 2020)','','publish','open','open','','%d0%b2%d1%82%d0%be%d1%80-%d0%bc%d0%b5%d1%93%d1%83%d0%bd%d0%b0%d1%80%d0%be%d0%b4%d0%b5%d0%bd-%d1%84%d0%b5%d1%81%d1%82%d0%b8%d0%b2%d0%b0%d0%bb-%d0%bd%d0%b0-%d0%ba%d1%80%d0%b0%d1%82o%d0%ba-%d1%84%d0%b8','','','2026-02-08 15:23:24','2026-02-08 15:23:24','',0,'https://user17.delovna.finki.ukim.mk/?p=644',0,'post','',0);
INSERT INTO `wp_posts` VALUES (645,1,'2026-02-08 15:20:05','2026-02-08 15:20:05','','FILMAY-2020-cover-photo','','inherit','open','closed','','filmay-2020-cover-photo','','','2026-02-08 15:20:05','2026-02-08 15:20:05','',644,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/FILMAY-2020-cover-photo.jpg',0,'attachment','image/jpeg',0);
