INSERT INTO `wp_posts` VALUES (657,1,'2026-02-08 15:28:40','2026-02-08 15:28:40','<!-- wp:query {\"queryId\":6,\"query\":{\"perPage\":10,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"exclude\",\"inherit\":false,\"taxQuery\":{\"category\":[123]}},\"metadata\":{\"categories\":[\"posts\"],\"patternName\":\"core/query-grid-posts\",\"name\":\"Grid\"}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"30px\",\"right\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\"}}},\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group\" style=\"padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:post-featured-image /-->\n\n<!-- wp:post-title {\"isLink\":true} /-->\n\n<!-- wp:post-excerpt /-->\n\n<!-- wp:post-date {\"metadata\":{\"bindings\":{\"datetime\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"date\"}}}}} /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template --></div>\n<!-- /wp:query -->','Film Program','','inherit','closed','closed','','198-revision-v1','','','2026-02-08 15:28:40','2026-02-08 15:28:40','',198,'https://user17.delovna.finki.ukim.mk/?p=657',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (658,1,'2026-02-08 15:30:06','2026-02-08 15:30:06','<!-- wp:image {\"id\":659,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/VRBA-PLAKAT-1024x681.jpg\" alt=\"\" class=\"wp-image-659\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>БИЛЕТИТЕ СЕ ВО ПРОДАЖБА ОД 28.01.2020 (ВТОРНИК) – БИЛЕТАРА ТЕАТАР</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„Врба“ е македонско-унгарско-белгиска копродукција во која учествува и Албанија. Се снимаше лани два месеца (октомври и ноември) во Мариово, Преспа, Трескавец и во Скопје. Филм за лојалност, љубов, доверба и мајчинство, кој спојува приказни за три млади мајки – едната се случува во 17 век, а другите две се современи. Приказните се надополнуваат, а во исто време се и контраст една на друга.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“Јас ова веќе доволно долго го правам за да знам кога нешто што ќе направам е стварно добро и кога не е. Ова е од тие што се стварно добри. Сѐ во процесот убаво се налепи и самиот процес беше прекрасен, првпат во моето искуство по многу години, рече Манчевски на средбата со новинарите пред премиерата.“ – Милчо Манчевски</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во актерската екипа се: Петар Мирчевски, Сара Климоска, Наталија Теодосиева, Никола Ристески Ненад Нацев, Камка Тоциновски, Благој Чоревски, Ратка Радмановиќ, Ана Костовска, Лазе Манасковски, Катина Иванова, Кире Ѓоревски, Адем Карага, Јелена Јованова-Периќ… Директор на фотографија е Унгарецот Тамаш Добош, дизајнер на продукција е долгогодишниот соработник на Манчевски, Британецот Дејвид Манс.</p>\n<!-- /wp:paragraph -->','ПРОЕКЦИЈА НА ФИЛМ “ВРБА“ НА МИЛЧО МАНЧЕВСКИ 03.02.2020 (ПОНЕДЕЛНИК) – САЛА ТЕАТАР – Почеток 18ч.','','publish','open','open','','%d0%bf%d1%80%d0%be%d0%b5%d0%ba%d1%86%d0%b8%d1%98%d0%b0-%d0%bd%d0%b0-%d1%84%d0%b8%d0%bb%d0%bc-%d0%b2%d1%80%d0%b1%d0%b0-%d0%bd%d0%b0-%d0%bc%d0%b8%d0%bb%d1%87%d0%be-%d0%bc%d0%b0%d0%bd','','','2026-02-08 15:30:06','2026-02-08 15:30:06','',0,'https://user17.delovna.finki.ukim.mk/?p=658',0,'post','',0);
