INSERT INTO `wp_posts` VALUES (673,1,'2026-02-08 15:52:47','2026-02-08 15:52:47','<!-- wp:image {\"id\":670,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/CheckeredNinja_still_22-952x536px-1.jpg\" alt=\"\" class=\"wp-image-670\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Children’s hit animated adventure<br>“CHECKERED NINJA”<br>TICKET PRICE: 50 denars.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":671,\"width\":\"750px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/Checkered.Ninja_picture-628x353px-1.jpg\" alt=\"\" class=\"wp-image-671\" style=\"width:750px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":672,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/CheckeredNinja_still_25-952x536px-768x432-2.jpg\" alt=\"\" class=\"wp-image-672\"/></figure>\n<!-- /wp:image -->','30.05.2019 (Thursday) Children’s hit animated adventure “CHECKERED NINJA” — GRAND HALL — 11:30','','inherit','closed','closed','','669-revision-v1','','','2026-02-08 15:52:47','2026-02-08 15:52:47','',669,'https://user17.delovna.finki.ukim.mk/?p=673',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (674,1,'2026-02-08 15:56:08','2026-02-08 15:56:08','<!-- wp:paragraph -->\n<p>„<a href=\"https://www.facebook.com/%D0%93%D0%BE%D1%81%D0%BF%D0%BE%D0%B4-%D0%BF%D0%BE%D1%81%D1%82%D0%BE%D0%B8-%D0%B8%D0%BC%D0%B5%D1%82%D0%BE-%D1%9D-%D0%B5-%D0%9F%D0%B5%D1%82%D1%80%D1%83%D0%BD%D0%B8%D1%98%D0%B0God-exists-her-name-is-Petrunya-468350937029761/\" target=\"_blank\" rel=\"noreferrer noopener\">Господ постои, името ѝ е Петрунија</a>” е прв македонски филм кој е избран во главна конкуренција на Берлинале, а пак прв пат по 25 години, односно по „Пред дождот“ во Венеција 1994 г., воопшто да биде во главна селекција на филмски фестивал од А категорија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„Навистина сме возбудени пред големата премиера во Берлин, дотолку повеќе што целата комисија на фестивалот беше видно импресионирана од нашето дело. Верувам дека и на публиката еднакво ќе ѝ се допадне приказната на Петрунија, особено што преку неа допираме до многу позначајна тема, а тоа е улогата на жената во општество полно со стереотипи, нејзиното место во религијата, но и тоа каков свет ќе ѝ оставиме на жената во иднина“, вели Теона Стругар Митевска.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Филмот инаку е инспириран од вистински настани кои се одиграа во Македонија кога жена за прв пат го фати крстот за Водици. Приказната во „Господ постои, името ѝ е Петрунија” се одвива во Штип, во текот на 24 часа по Водици, кога токму Петрунија успева да го фати крстот, но нејзиниот успех е дочекан со револт од страна на локалното население и впрочем целото општество, црквата, системот…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Преку оваа приказна, како што вели Митевска, допираме до многу посуштински проблем со кој се соочува една жена во претежно „машки“ систем, а проблемот е кренат дотаму што дури се истакнува идејата за полот на Бога и важноста на факторот на полот како еден од главните чинители во нашето општество.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":675,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/петрунија-филм-705x1024.jpg\" alt=\"\" class=\"wp-image-675\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":676,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/54729749_502311210300400_9144180678231851008_o-768x512-1.jpg\" alt=\"\" class=\"wp-image-676\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":677,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/50679320_469863386878516_9221287667751190528_n-768x292-1.jpg\" alt=\"\" class=\"wp-image-677\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":678,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://trajko-prokopiev.local/wp-content/uploads/2026/02/God-exists-Petrunija-photo-1-768x432-1.jpg\" alt=\"\" class=\"wp-image-678\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>„<a href=\"https://www.facebook.com/%D0%93%D0%BE%D1%81%D0%BF%D0%BE%D0%B4-%D0%BF%D0%BE%D1%81%D1%82%D0%BE%D0%B8-%D0%B8%D0%BC%D0%B5%D1%82%D0%BE-%D1%9D-%D0%B5-%D0%9F%D0%B5%D1%82%D1%80%D1%83%D0%BD%D0%B8%D1%98%D0%B0God-exists-her-name-is-Petrunya-468350937029761/\" target=\"_blank\" rel=\"noreferrer noopener\">Господ постои, името ѝ е Петрунија</a>” е прв македонски филм кој е избран во главна конкуренција на Берлинале, а пак прв пат по 25 години, односно по „Пред дождот“ во Венеција 1994 г., воопшто да биде во главна селекција на филмски фестивал од А категорија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„Навистина сме возбудени пред големата премиера во Берлин, дотолку повеќе што целата комисија на фестивалот беше видно импресионирана од нашето дело. Верувам дека и на публиката еднакво ќе ѝ се допадне приказната на Петрунија, особено што преку неа допираме до многу позначајна тема, а тоа е улогата на жената во општество полно со стереотипи, нејзиното место во религијата, но и тоа каков свет ќе ѝ оставиме на жената во иднина“, вели Теона Стругар Митевска.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Филмот инаку е инспириран од вистински настани кои се одиграа во Македонија кога жена за прв пат го фати крстот за Водици. Приказната во „Господ постои, името ѝ е Петрунија” се одвива во Штип, во текот на 24 часа по Водици, кога токму Петрунија успева да го фати крстот, но нејзиниот успех е дочекан со револт од страна на локалното население и впрочем целото општество, црквата, системот…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Преку оваа приказна, како што вели Митевска, допираме до многу посуштински проблем со кој се соочува една жена во претежно „машки“ систем, а проблемот е кренат дотаму што дури се истакнува идејата за полот на Бога и важноста на факторот на полот како еден од главните чинители во нашето општество.</p>\n<!-- /wp:paragraph -->','10.05.2019 (петок) – ГОЛЕМА САЛА 20ч. ФИЛМ – “ГОСПОД ПОСТОИ, ИМЕТО И Е ПЕТРУНИЈА“','','publish','open','open','','10-05-2019-%d0%bf%d0%b5%d1%82%d0%be%d0%ba-%d0%b3%d0%be%d0%bb%d0%b5%d0%bc%d0%b0-%d1%81%d0%b0%d0%bb%d0%b0-20%d1%87-%d1%84%d0%b8%d0%bb%d0%bc-%d0%b3%d0%be%d1%81%d0%bf%d0%be','','','2026-02-08 15:57:14','2026-02-08 15:57:14','',0,'https://user17.delovna.finki.ukim.mk/?p=674',0,'post','',0);
