INSERT INTO `wp_posts` VALUES (695,1,'2026-02-08 16:01:52','2026-02-08 16:01:52','<!-- wp:paragraph -->\n<p>30/05/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BMGJlZTIxYjItZmVhZi00ZTNkLWEzZDMtOTBhMTk0NGViODQ2XkEyXkFqcGdeQXVyMTMxODk2OTU@._V1_.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>ЦЕНА НА ВЛЕЗЕН БИЛЕТ 100 ден.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:embed {\"url\":\"https://www.youtube.com/embed/y9d8XjRBddo?feature=oembed\",\"type\":\"rich\",\"providerNameSlug\":\"embed-handler\",\"responsive\":true} -->\n<figure class=\"wp-block-embed is-type-rich is-provider-embed-handler wp-block-embed-embed-handler\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/embed/y9d8XjRBddo?feature=oembed\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:paragraph -->\n<p><strong><em>Кратка содржина</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><em>Девојка која се бори со астма е однесена во клиника во Јужен Тирол за да се излечи. По некое време таа одлучува да излезе од овој пекол (така се чувствува за тоа) и наскоро ќе запознае нов пријател. Заедно се обидуваат да го искачат врвот на една планина каде, според стар обичај, таа може да се излечи.&nbsp;</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Година –&nbsp;</strong>2017</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Режија –&nbsp;</strong>Тобајас Виман</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Времетраење –&nbsp;</strong>97 минути</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Земја –&nbsp;</strong>Германија</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Жанр –&nbsp;</strong>Драма/Авантура</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>Дистрибутер:&nbsp;</em><strong>Узенгија</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":2587} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BMDc4ZmQ3ZmMtMDI5MC00NjRkLThhMDktOTQ1OTBjNTAxYjhlXkEyXkFqcGdeQXVyMjc3NTQzNjQ@._V1_-1024x435.jpg\" alt=\"\" class=\"wp-image-2587\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2588} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BN2FmMjc3NDktNzU4Zi00OTI3LThhNjUtMzgzZWZkZTczNTczXkEyXkFqcGdeQXVyMjc3NTQzNjQ@._V1_.jpg\" alt=\"\" class=\"wp-image-2588\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2589} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BZmFjNGM0YTMtY2U1MS00NGFkLTk4ZTItMDA2NTYzMTgxM2E2L2ltYWdlXkEyXkFqcGdeQXVyMjQ3NzUxOTM@._V1_SY1000_CR007061000_AL_.jpg\" alt=\"\" class=\"wp-image-2589\"/></figure>\n<!-- /wp:image -->','ИГРАН ФИЛМ – ПЛАНИНСКО ЧУДО: НЕОЧЕКУВАНО ПРИЈАТЕЛСТВО 08.06.2018 ПЕТОК 20ч.','','publish','open','open','','%d0%b8%d0%b3%d1%80%d0%b0%d0%bd-%d1%84%d0%b8%d0%bb%d0%bc-%d0%bf%d0%bb%d0%b0%d0%bd%d0%b8%d0%bd%d1%81%d0%ba%d0%be-%d1%87%d1%83%d0%b4%d0%be-%d0%bd%d0%b5%d0%be%d1%87%d0%b5%d0%ba%d1%83%d0%b2','','','2026-02-08 16:01:53','2026-02-08 16:01:53','',0,'https://user17.delovna.finki.ukim.mk/?p=695',0,'post','',0);
