INSERT INTO `wp_posts` VALUES (700,1,'2026-02-08 16:02:26','2026-02-08 16:02:26','<!-- wp:paragraph -->\n<p>0/05/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BMGJlZTIxYjItZmVhZi00ZTNkLWEzZDMtOTBhMTk0NGViODQ2XkEyXkFqcGdeQXVyMTMxODk2OTU@._V1_.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>TICKET PRICE: 100 denars</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Short synopsis<br>A girl who struggles with asthma is taken to a clinic in South Tyrol to be treated. After some time, she decides to escape from what feels like hell to her, and soon meets a new friend. Together they try to climb a mountain peak where, according to an old tradition, she can be healed.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Year — 2017<br>Director — Tobias Wiemann<br>Duration — 97 minutes<br>Country — Germany<br>Genre — Drama / Adventure</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Distributor: Uzengija</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>FEATURE FILM — MOUNTAIN MIRACLE: AN UNEXPECTED FRIENDSHIP — 08.06.2018 (Friday) — 20:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":2587} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BMDc4ZmQ3ZmMtMDI5MC00NjRkLThhMDktOTQ1OTBjNTAxYjhlXkEyXkFqcGdeQXVyMjc3NTQzNjQ@._V1_-1024x435.jpg\" alt=\"\" class=\"wp-image-2587\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2588} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BN2FmMjc3NDktNzU4Zi00OTI3LThhNjUtMzgzZWZkZTczNTczXkEyXkFqcGdeQXVyMjc3NTQzNjQ@._V1_.jpg\" alt=\"\" class=\"wp-image-2588\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2589} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/05/MV5BZmFjNGM0YTMtY2U1MS00NGFkLTk4ZTItMDA2NTYzMTgxM2E2L2ltYWdlXkEyXkFqcGdeQXVyMjQ3NzUxOTM@._V1_SY1000_CR007061000_AL_.jpg\" alt=\"\" class=\"wp-image-2589\"/></figure>\n<!-- /wp:image -->','FEATURE FILM — MOUNTAIN MIRACLE: AN UNEXPECTED FRIENDSHIP — 08.06.2018 (Friday) — 20:00','','inherit','closed','closed','','699-revision-v1','','','2026-02-08 16:02:26','2026-02-08 16:02:26','',699,'https://user17.delovna.finki.ukim.mk/?p=700',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (701,1,'2026-02-08 16:03:52','2026-02-08 16:03:52','<!-- wp:paragraph -->\n<p>05/05/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/KRUSA.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:embed {\"url\":\"https://www.youtube.com/embed/lwiqvC62Mqc?feature=oembed\",\"type\":\"rich\",\"providerNameSlug\":\"embed-handler\",\"responsive\":true} -->\n<figure class=\"wp-block-embed is-type-rich is-provider-embed-handler wp-block-embed-embed-handler\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/embed/lwiqvC62Mqc?feature=oembed\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:paragraph -->\n<p>Ве покануваме да бидете дел од филмската магија на данскиот филм „Неверојатната приказна за џиновската круша“, базиран на истоимената популарна книга за деца од Јакоб Мартин Стрид. Тоа е приказна за две другарчиња – слонот Себастијан и мачката Мичо кои се впуштаат во морска авантура за да го спасат исчезнатиот градоначалник Џи Би, кому еден ден мистериозно му се губи трагата. Тие го совладуваат морето со нивната џиновска круша и во текот на нивната авантура ќе налетаат на пирати, змејови и чудни духови. Животот во Санитаун е убав и мирен се додека еден ден Мичо и Себастијан не најдат порака во шише на пристаништето. Шишето е од исчезнатиот градоначалник на Санитаун со порака дека е на мистериозен остров и направил големо откритие. Сега тие мора да тргнат на опасно патување за да го спасат градоначалникот и да го доведат дома, а во тој процес откриваат нешто што ќе му донесе големо задоволство на градот Санитаун – џиновска круша.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„Неверојатната приказна за џиновската круша“ во режија на Филип Ајнстин Липски, Јурген Лердам и Амелие Несби Фик беше селектиран во детската програма КПлус во рамките на Берлинскиот филмски фестивал 2018.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":2416} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/poster_2000-mk-706x1024.jpg\" alt=\"\" class=\"wp-image-2416\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2414} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/poster_2000-al-706x1024.jpg\" alt=\"\" class=\"wp-image-2414\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2417} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/still-photo-3.jpg\" alt=\"\" class=\"wp-image-2417\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2418} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/still-photo-5.jpg\" alt=\"\" class=\"wp-image-2418\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2419} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/still-photo-8.jpg\" alt=\"\" class=\"wp-image-2419\"/></figure>\n<!-- /wp:image -->','“ЏИНОВСКАТА КРУША“ ДАНСКИ АНИМИРАН ФИЛМ 11.05.2018 ПЕТОК 12ч. ЦЕНА НА БИЛЕТ 50 ден.','','publish','open','open','','%d1%9f%d0%b8%d0%bd%d0%be%d0%b2%d1%81%d0%ba%d0%b0%d1%82%d0%b0-%d0%ba%d1%80%d1%83%d1%88%d0%b0-%d0%b4%d0%b0%d0%bd%d1%81%d0%ba%d0%b8-%d0%b0%d0%bd%d0%b8%d0%bc%d0%b8%d1%80%d0%b0%d0%bd','','','2026-02-08 16:03:53','2026-02-08 16:03:53','',0,'https://user17.delovna.finki.ukim.mk/?p=701',0,'post','',0);
