INSERT INTO `wp_posts` VALUES (711,1,'2026-02-08 16:06:57','2026-02-08 16:06:57','<!-- wp:paragraph -->\n<p>19/04/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/28685141_2367050580006373_4745534511998396531_n.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Director: Milcho Manchevski</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cast: Condola Rashad, Sarah Goldberg, Will Janowitz, Sathya Sridharan, Mykal-Michelle Harris</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>27.4.2018 (Friday) — Grand Hall at the Center for Culture<br>Duration: 102′<br>Country: USA<br>Genre: Drama, Documentary</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>In this modern urban fairy tale set within the broken ideal of the family, a charismatic homeless woman attracts the attention of a film crew shooting a documentary, who are ready to exploit her story in order to gain fame in the world of independent filmmaking.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>TICKET PRICE: 100 denars</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":2338,\"align\":\"left\"} -->\n<figure class=\"wp-block-image alignleft\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/30726943_2408693375842093_3207190210366406656_n.jpg\" alt=\"\" class=\"wp-image-2338\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2337} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/29792251_2400374506673980_1713072818683379712_o-1024x585.jpg\" alt=\"\" class=\"wp-image-2337\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2336} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/29694687_2389759534402144_7430184470031496_n.jpg\" alt=\"\" class=\"wp-image-2336\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2335} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/29694529_2399394003438697_5471749358275788800_n.jpg\" alt=\"\" class=\"wp-image-2335\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2334} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/29683427_2397432660301498_2668705908570965936_n.jpg\" alt=\"\" class=\"wp-image-2334\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2333} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/29594942_2395006567210774_2294334217092306785_n.jpg\" alt=\"\" class=\"wp-image-2333\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2332} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/04/29354976_2393155920729172_5773501462937184704_o-1024x576.jpg\" alt=\"\" class=\"wp-image-2332\"/></figure>\n<!-- /wp:image -->','DRAMA, DOCUMENTARY FILM — “BIKINI MOON” — 27.04.2018 (Friday) — Grand Hall — 20:00','','publish','open','open','','drama-documentary-film-bikini-moon-27-04-2018-friday-grand-hall-2000','','','2026-02-08 16:06:57','2026-02-08 16:06:57','',0,'https://user17.delovna.finki.ukim.mk/?p=711',0,'post','',0);
