INSERT INTO `wp_posts` VALUES (729,1,'2026-02-08 16:17:21','2026-02-08 16:17:21','<!-- wp:paragraph -->\n<p>02/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/Sluzben-vesnik-8-12-converted.pdf\">Sluzben vesnik 8-12-converted</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":4264} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/08-Copy.jpg\" alt=\"\" class=\"wp-image-4264\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4265} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/09-Copy.jpg\" alt=\"\" class=\"wp-image-4265\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4266} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/10-Copy.jpg\" alt=\"\" class=\"wp-image-4266\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4267} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/11-Copy.jpg\" alt=\"\" class=\"wp-image-4267\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4269} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/12.jpg\" alt=\"\" class=\"wp-image-4269\"/></figure>\n<!-- /wp:image -->','PROTOCOL FOR THE OPERATION OF LIBRARIES, MUSEUMS, GALLERIES, AND EXHIBITION SPACES — Official Gazette, pp. 8–12, No. 175, dated 01.07.2020.','','inherit','closed','closed','','728-revision-v1','','','2026-02-08 16:17:21','2026-02-08 16:17:21','',728,'https://user17.delovna.finki.ukim.mk/?p=729',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (730,1,'2026-02-08 16:19:26','2026-02-08 16:19:26','<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>12/06/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/7.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>во Центар за култура го одбележавме 1 јуни, денот на детето.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Уметнички преформанс преку симболично прикажување на Денот на букварот од учениците од II-4 одделение, при ОУ Толи Зордумис под менторство на нивната учителка Зејенпе Бајрами.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Sot ne Qendren për kulturë në Kumanovë u festuan dy festa të rëndësishme dhe simbolike “Dita e Abetares” dhe Dita e fëmijeve “1 Qershori”.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Performuan fëmijët e klasës II4 të shkollës fillore ,,Toli Zordumis”,nën përkujdesjen e mësueses Zejnepe Bajrami.<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/1-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/1-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/1-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/1-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/2-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/2-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/2-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/2-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/3-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/3-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/3-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/3-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/4-683x1024.jpg\" alt=\"\" width=\"640\" height=\"960\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/4-683x1024.jpg 683w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/4-200x300.jpg 200w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/4-768x1152.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/4.jpg 1365w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/5-683x1024.jpg\" alt=\"\" width=\"640\" height=\"960\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/5-683x1024.jpg 683w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/5-200x300.jpg 200w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/5-768x1152.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/5.jpg 1365w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/6-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/6-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/6-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/6-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/7-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/7-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/7-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/7-768x512.jpg 768w\"></p>\n<!-- /wp:paragraph -->','Ден на детето','','publish','open','open','','%d0%b4%d0%b5%d0%bd-%d0%bd%d0%b0-%d0%b4%d0%b5%d1%82%d0%b5%d1%82%d0%be','','','2026-02-08 16:20:17','2026-02-08 16:20:17','',0,'https://user17.delovna.finki.ukim.mk/?p=730',0,'post','',0);
