INSERT INTO `wp_posts` VALUES (764,1,'2026-02-08 16:33:39','2026-02-08 16:33:39','<!-- wp:paragraph -->\n<p>26/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-3.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5744} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-3.jpg\" alt=\"\" class=\"wp-image-5744\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5745} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-3-1024x682.jpg\" alt=\"\" class=\"wp-image-5745\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5746} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-3-1024x682.jpg\" alt=\"\" class=\"wp-image-5746\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5747} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-3-1024x682.jpg\" alt=\"\" class=\"wp-image-5747\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5748} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/6-3-1024x682.jpg\" alt=\"\" class=\"wp-image-5748\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5749} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-3-1024x682.jpg\" alt=\"\" class=\"wp-image-5749\"/></figure>\n<!-- /wp:image -->','Biljana Kamcheva Concert','','inherit','closed','closed','','763-revision-v1','','','2026-02-08 16:33:39','2026-02-08 16:33:39','',763,'https://user17.delovna.finki.ukim.mk/?p=764',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (765,1,'2026-02-08 16:34:12','2026-02-08 16:34:12','<!-- wp:paragraph -->\n<p>11/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/6.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Семинар за традиционална музика и игра ШОПЦИ/КОТОРЦИ. На семинарот се зборуваше за базичните етнолошки и етнокореолошки информации до врвни научни дострели по прашање на овие науки.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Вториот ден играорците од фолклорните друштва „Срма“ и „Панче Пешев “ учествуваа на вежбите организирани од предавачите.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Мастеркласот го оддржаа етнокореологот Бојан Петковски и етнокореологот Симона Китановска.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Проектот е поддржан од страна на Министерството за култура.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5733} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-2-1024x683.jpg\" alt=\"\" class=\"wp-image-5733\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5734} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/6-2-1024x683.jpg\" alt=\"\" class=\"wp-image-5734\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5735} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-2-1024x683.jpg\" alt=\"\" class=\"wp-image-5735\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5736} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/8-2-1024x683.jpg\" alt=\"\" class=\"wp-image-5736\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5737} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/9-2-683x1024.jpg\" alt=\"\" class=\"wp-image-5737\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5738} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/10-2-1024x683.jpg\" alt=\"\" class=\"wp-image-5738\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5739} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/11-2-1024x683.jpg\" alt=\"\" class=\"wp-image-5739\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5740} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/12-2-1024x683.jpg\" alt=\"\" class=\"wp-image-5740\"/></figure>\n<!-- /wp:image -->','Фотографии од II Семинар за традиционална музика и игра „Шопци/Которци“','','publish','open','open','','%d1%84%d0%be%d1%82%d0%be%d0%b3%d1%80%d0%b0%d1%84%d0%b8%d0%b8-%d0%be%d0%b4-ii-%d1%81%d0%b5%d0%bc%d0%b8%d0%bd%d0%b0%d1%80-%d0%b7%d0%b0-%d1%82%d1%80%d0%b0%d0%b4%d0%b8%d1%86%d0%b8%d0%be%d0%bd%d0%b0%d0%bb','','','2026-02-08 16:34:12','2026-02-08 16:34:12','',0,'https://user17.delovna.finki.ukim.mk/?p=765',0,'post','',0);
