INSERT INTO `wp_posts` VALUES (777,1,'2026-02-08 16:37:49','2026-02-08 16:37:49','<!-- wp:paragraph -->\n<p>03/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-724x1024.jpg\" alt=\"\" width=\"640\" height=\"905\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-724x1024.jpg 724w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-212x300.jpg 212w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-768x1086.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1.jpg 1131w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-724x1024.jpg\" alt=\"\" width=\"640\" height=\"905\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-724x1024.jpg 724w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-212x300.jpg 212w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-768x1086.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2.jpg 1131w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-768x1024.jpg\" alt=\"\" width=\"640\" height=\"853\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-768x1024.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-225x300.jpg 225w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3.jpg 1200w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-1024x682.jpg\" alt=\"\" width=\"640\" height=\"426\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-1024x682.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-768x512.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4.jpg 1600w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-1024x682.jpg\" alt=\"\" width=\"640\" height=\"426\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-1024x682.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-768x512.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5.jpg 1600w\">Денеска го реализиравме проектот насловен „Моќта на уметноста на нашиот ум“.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Се чувствуваме почестени од присуството на нашите професори, кои ги споделија со нас нивните професионални и педагошки вредности на предавањето во НУЦК „Трајко Прокопиев“ Куманово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ви благодариме на сите за учеството!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Sot realizuam projektin me titull „Fuqia e artit mbi mendjen tonë”.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ndjehemi të nderuar me prezencën e Profesorëve tanë, të cilët ndanë me ne vlerat e tyre profesionale dhe pedagogjike gjatë ligjërimit në INQK „Trajko Prokopiev” Kumanovë.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ju faleminderit të gjithve për pjesëmarrjen!</p>\n<!-- /wp:paragraph -->','Моќта на уметноста над нашиот ум Семинар.Fuqia e artit mbi mendjen tonë – Seminar','','publish','open','open','','%d0%bc%d0%be%d1%9c%d1%82%d0%b0-%d0%bd%d0%b0-%d1%83%d0%bc%d0%b5%d1%82%d0%bd%d0%be%d1%81%d1%82%d0%b0-%d0%bd%d0%b0%d0%b4-%d0%bd%d0%b0%d1%88%d0%b8%d0%be%d1%82-%d1%83%d0%bc-%d1%81%d0%b5%d0%bc%d0%b8%d0%bd','','','2026-02-08 16:37:49','2026-02-08 16:37:49','',0,'https://user17.delovna.finki.ukim.mk/?p=777',0,'post','',0);
