INSERT INTO `wp_posts` VALUES (810,1,'2026-02-08 16:44:46','2026-02-08 16:44:46','<!-- wp:paragraph -->\n<p>23/03/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337094198_1295395391322670_1963423304880124409_n.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Ballet–dance performance.<br>Through dance and art, gender equality was discussed, as well as a topic that is rarely spoken about — violence against women in society.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-1024x683.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-1024x683.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336909901_1834282197312133_4909731007186784640_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336909901_1834282197312133_490973100718678464