INSERT INTO `wp_posts` VALUES (811,1,'2026-02-08 16:44:46','2026-02-08 16:44:46','<!-- wp:paragraph -->\n<p>23/03/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337094198_1295395391322670_1963423304880124409_n.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Ballet–dance performance.<br>Through dance and art, gender equality was discussed, as well as a topic that is rarely spoken about — violence against women in society.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336661639_565490665647506_689371479233907482_n-1024x683.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336753009_1505981560210676_5782172101851542894_n-1024x683.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336909901_1834282197312133_4909731007186784640_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336909901_1834282197312133_4909731007186784640_n-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336909901_1834282197312133_4909731007186784640_n-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/336909901_1834282197312133_4909731007186784640_n-1024x683.jpg\" alt=\"\"> <img width=\"640\" height=\"360\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337094198_1295395391322670_1963423304880124409_n-1024x576.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337094198_1295395391322670_1963423304880124409_n-300x169.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337094198_1295395391322670_1963423304880124409_n-768x432.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337094198_1295395391322670_1963423304880124409_n.jpg 1080w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337094198_1295395391322670_1963423304880124409_n-1024x576.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337157228_749251006660426_3945287573345769367_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337157228_749251006660426_3945287573345769367_n-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337157228_749251006660426_3945287573345769367_n-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337157228_749251006660426_3945287573345769367_n-1024x683.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337290347_728830695639430_4038540466813183507_n-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337290347_728830695639430_4038540466813183507_n-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337290347_728830695639430_4038540466813183507_n-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/03/337290347_728830695639430_4038540466813183507_n-1024x683.jpg\" alt=\"\"></p>\n<!-- /wp:paragraph -->','THE DANCING (TALKING) TABLE / Space for Conversation','','inherit','closed','closed','','810-revision-v1','','','2026-02-08 16:44:46','2026-02-08 16:44:46','',810,'https://user17.delovna.finki.ukim.mk/?p=811',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (812,1,'2026-02-08 16:45:30','2026-02-08 16:45:30','<!-- wp:paragraph -->\n<p>17/05/2022</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/Muzika-nema-granici-Bugarija.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong><em>Во македонскиот Културно информативниот центар на&nbsp; во Софија се одржа концерт „Музиката нема граници“ во изведба на Младинскиот оркестар на Центарот за култура „Трајко Прокопиев“ од Куманово, јави дописникот на МИА од Софија.</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Оркестарот изведе многу популарни македонски песни, како и рок музика, преработки на македонски евергрини и народни песни.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Во програмата на оркестарот беа вклучени музички композиции од настапи на Каролина Гочева, Тоше Проески, Александар Митевски и Драган Спасов Дац, Влатко Стефановски, Ареа, Куку Леле, Нон Стоп, Александра Јанева, Зијан, Ана Костовска, а исто така и џез-преработки на познати македонски народни песни, како и песни од кумановскиот крај.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Посетителите во преполната сала на КИЦ во Софија го наградија оркестарот со долги аплаузи.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Уметничкиот раководител на оркестарот од Куманово, Александар Митрички, за МИА изјави дека се потрудиле да дадат се од себе и оти се радуваат оти публиката во Софија тоа го препознала.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>– Атмосферата беше прекрасна и за исполнителите и за музичарите. Песните беа прифатени одлично, рече Митрички.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Тој додава дека уметноста и музиката поврзуваат и оти овој концерт е пример за сите дека треба да се унапредува културната соработка.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Младинскиот оркестар брои над 15 члена, а неговиот инструментариум е составен од вокални солисти, бас-гитара, соло-гитара, акустична гитара, клавијатури, саксофон, кларинет, кавал, хармоника, кахон, тарамбука, виолина, труба, тромбон.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Покрај композициите што се пеат, оркестарот изведува и композиции во форма на џез стандарди, преработки на песни во инструментална форма и преработки на песни од традиционалната македонска музика.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Оркестарот е формиран во 2020 година и работи под уметничко раководство на Александар Митрички, Мима Младеновска – вокал и Филип Гелевски – вокал.&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5181} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280547711_3198647133753279_8223758290952102294_n-1024x768.jpg\" alt=\"\" class=\"wp-image-5181\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5182} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280644306_3198647110419948_3754411764879977538_n-1024x768.jpg\" alt=\"\" class=\"wp-image-5182\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5183} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280732303_3198647173753275_5821478391244768562_n-1024x768.jpg\" alt=\"\" class=\"wp-image-5183\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5184} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280788831_3198647153753277_5617826323946464520_n-1024x768.jpg\" alt=\"\" class=\"wp-image-5184\"/></figure>\n<!-- /wp:image -->','Настап на Младинскиот оркестар при НУЦК во Културниот Центар во Софија','','publish','open','open','','%d0%bd%d0%b0%d1%81%d1%82%d0%b0%d0%bf-%d0%bd%d0%b0-%d0%bc%d0%bb%d0%b0%d0%b4%d0%b8%d0%bd%d1%81%d0%ba%d0%b8%d0%be%d1%82-%d0%be%d1%80%d0%ba%d0%b5%d1%81%d1%82%d0%b0%d1%80-%d0%bf%d1%80%d0%b8-%d0%bd%d1%83','','','2026-02-08 16:45:30','2026-02-08 16:45:30','',0,'https://user17.delovna.finki.ukim.mk/?p=812',0,'post','',0);
INSERT INTO `wp_posts` VALUES (813,1,'2026-02-08 16:45:23','2026-02-08 16:45:23','','Muzika-nema-granici-Bugarija','','inherit','open','closed','','muzika-nema-granici-bugarija','','','2026-02-08 16:45:23','2026-02-08 16:45:23','',812,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/Muzika-nema-granici-Bugarija.jpg',0,'attachment','image/jpeg',0);
