INSERT INTO `wp_posts` VALUES (844,1,'2026-02-08 17:57:03','2026-02-08 17:57:03','<!-- wp:paragraph -->\n<p>15/12/2021</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/267140792_3090989371185723_6186370034175482465_n.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Maja Popović graduated from the Piano Department at the Faculty of Music Arts in Skopje, and later completed her master’s degree at the same institution. She currently works as a professor of piano and chamber music at the Secondary Music School in Skopje, and as a professional associate — accompanist for the saxophone class at the Faculty of Music Arts.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":4712} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/266182347_3090989307852396_5008750576734991938_n.jpg\" alt=\"\" class=\"wp-image-4712\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4713} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/266232500_3090989044519089_727335582722472333_n.jpg\" alt=\"\" class=\"wp-image-4713\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4714} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/266308979_3090988244519169_7872477343495687610_n.jpg\" alt=\"\" class=\"wp-image-4714\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4715} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/266352709_3090997984518195_4939061435800483407_n.jpg\" alt=\"\" class=\"wp-image-4715\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4716} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/266379968_3090989087852418_3020334300054439