INSERT INTO `wp_posts` VALUES (849,1,'2026-02-08 17:58:07','2026-02-08 17:58:07','<!-- wp:paragraph -->\n<p>10/12/2021</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/kULTURAN-27-DEKEMVRI.png\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4649} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/kULTURAN-27-DEKEMVRI.png\" alt=\"\" class=\"wp-image-4649\"/></figure>\n<!-- /wp:image -->','New Year’s Magic — Milena and Marko — Piano Duo','','publish','open','open','','new-years-magic-milena-and-marko-piano-duo','','','2026-02-08 17:58:07','2026-02-08 17:58:07','',0,'https://user17.delovna.finki.ukim.mk/?p=849',0,'post','',0);
INSERT INTO `wp_posts` VALUES (850,1,'2026-02-08 17:58:07','2026-02-08 17:58:07','<!-- wp:paragraph -->\n<p>10/12/2021</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/kULTURAN-27-DEKEMVRI.png\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4649} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2021/12/kULTURAN-27-DEKEMVRI.png\" alt=\"\" class=\"wp-image-4649\"/></figure>\n<!-- /wp:image -->','New Year’s Magic — Milena and Marko — Piano Duo','','inherit','closed','closed','','849-revision-v1','','','2026-02-08 17:58:07','2026-02-08 17:58:07','',849,'https://user17.delovna.finki.ukim.mk/?p=850',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (851,1,'2026-02-08 17:58:50','2026-02-08 17:58:50','<!-- wp:paragraph -->\n<p>10/11/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/%D0%93%D0%B5%D0%BB%D0%B5%D0%B1%D0%B5%D1%81%D0%B5%D0%B2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4430} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/GELEBESEVA.jpg\" alt=\"\" class=\"wp-image-4430\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Катерина Гелебешева Костадиновска е уметник со истакнат и индивидуален пијанистички сензибилитет, откриен и едуциран низ класите на професорите: Евушка Елезовиќ-Трпкова и професор Тодор Светиев. Дипломирала на Музичката академија во Загреб, во класата на истакнатиот професор и пијанист Владимир Крпан во 1991 год., а магистрирала во Скопје 1993 год., во класата на професор Борис Романов. Учествувала на семинари раководени од еминентни пијанисти и педагози: Керер, Мураро, Тимакин, Гинзбург, Икуко Ендо.. и бројни натпревари со освоени највисоки награди. Особено почесно место зазема освоената трета награда на 24-от натпревар на Млади музички уметници во Загреб, одржан 1990 год., како и спијалното меѓународно признание за изведба на дела од Б. Папандопуло во Грожњан, Хрватска, во 1986.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Нејзината успешна уметничка кариера како пијанист, која ја започнува многу рано, ја одбележуваат бројни настапи, како во нашата земја така и во: Турција, Португалија, Словенија, Хрватска, Италија, Холандија, Франција… проследени со инзвонреден прием од публиката и музичката критика. Со посебен успех и високи оценки од музичката критика, повеќекратно настапува со: Македонската филхармонија, Камерниот оркестар при МФ, Загребската филхармонија, Симфонискиот оркестар на ХРТВ Загреб.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Покрај нејзината активност на сцената како самостоен солист, учествува и во различни камерни состави. Особено акцентирана концертна дејност од 2001 год. па се до денес, остварува со пијано дуото Гелебешеви, кое го формира со нејзиниот сопруг Глигор Гелебешев. Дуото остварува концерти на скоро сите најзначајни фестивали во државата: Охридско лето, Скопско лето, Битолско лето, Интерфест Битола, Златна лира, Денови на македонска музика… Од 2005 година со настапот во Париз, дуото ја започнува и својата меѓународна кариера. Следат настапи во: Италија, Холандија, Романија, Полска, Србија, Словенија, Хрватска, Бугарија, Турција, САД… Во 2012 година, ја добиваат наградата ‘Златна лира’ врачена од СМУМ. Во текот на својата повеќегодишна работа, дуото Гелебешеви имаат објавено и две аудио изданија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Денес Катерина Гелебешева Костадиновска работи како редовен професор по пијано на Факултетот за музичка уметност во Скопје.</p>\n<!-- /wp:paragraph -->','ВЕЧЕР ПОСВЕТЕНА НА КЛАРА ШУМАН – КОНЦЕРТ НА КАТЕРИНА ГЕЛЕБЕШЕВА КОСТАДИНОВСКА 12.11.2020 (ЧЕТВРТОК) 19ч.','','publish','open','open','','%d0%b2%d0%b5%d1%87%d0%b5%d1%80-%d0%bf%d0%be%d1%81%d0%b2%d0%b5%d1%82%d0%b5%d0%bd%d0%b0-%d0%bd%d0%b0-%d0%ba%d0%bb%d0%b0%d1%80%d0%b0-%d1%88%d1%83%d0%bc%d0%b0%d0%bd-%d0%ba%d0%be%d0%bd%d1%86','','','2026-02-08 17:58:50','2026-02-08 17:58:50','',0,'https://user17.delovna.finki.ukim.mk/?p=851',0,'post','',0);
INSERT INTO `wp_posts` VALUES (852,1,'2026-02-08 17:58:24','2026-02-08 17:58:24','','Гелебесев','','inherit','open','closed','','%d0%b3%d0%b5%d0%bb%d0%b5%d0%b1%d0%b5%d1%81%d0%b5%d0%b2','','','2026-02-08 17:58:24','2026-02-08 17:58:24','',851,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/Гелебесев.jpg',0,'attachment','image/jpeg',0);
INSERT INTO `wp_posts` VALUES (853,1,'2026-02-08 17:58:50','2026-02-08 17:58:50','<!-- wp:paragraph -->\n<p>10/11/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/%D0%93%D0%B5%D0%BB%D0%B5%D0%B1%D0%B5%D1%81%D0%B5%D0%B2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4430} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/GELEBESEVA.jpg\" alt=\"\" class=\"wp-image-4430\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Катерина Гелебешева Костадиновска е уметник со истакнат и индивидуален пијанистички сензибилитет, откриен и едуциран низ класите на професорите: Евушка Елезовиќ-Трпкова и професор Тодор Светиев. Дипломирала на Музичката академија во Загреб, во класата на истакнатиот професор и пијанист Владимир Крпан во 1991 год., а магистрирала во Скопје 1993 год., во класата на професор Борис Романов. Учествувала на семинари раководени од еминентни пијанисти и педагози: Керер, Мураро, Тимакин, Гинзбург, Икуко Ендо.. и бројни натпревари со освоени највисоки награди. Особено почесно место зазема освоената трета награда на 24-от натпревар на Млади музички уметници во Загреб, одржан 1990 год., како и спијалното меѓународно признание за изведба на дела од Б. Папандопуло во Грожњан, Хрватска, во 1986.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Нејзината успешна уметничка кариера како пијанист, која ја започнува многу рано, ја одбележуваат бројни настапи, како во нашата земја така и во: Турција, Португалија, Словенија, Хрватска, Италија, Холандија, Франција… проследени со инзвонреден прием од публиката и музичката критика. Со посебен успех и високи оценки од музичката критика, повеќекратно настапува со: Македонската филхармонија, Камерниот оркестар при МФ, Загребската филхармонија, Симфонискиот оркестар на ХРТВ Загреб.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Покрај нејзината активност на сцената како самостоен солист, учествува и во различни камерни состави. Особено акцентирана концертна дејност од 2001 год. па се до денес, остварува со пијано дуото Гелебешеви, кое го формира со нејзиниот сопруг Глигор Гелебешев. Дуото остварува концерти на скоро сите најзначајни фестивали во државата: Охридско лето, Скопско лето, Битолско лето, Интерфест Битола, Златна лира, Денови на македонска музика… Од 2005 година со настапот во Париз, дуото ја започнува и својата меѓународна кариера. Следат настапи во: Италија, Холандија, Романија, Полска, Србија, Словенија, Хрватска, Бугарија, Турција, САД… Во 2012 година, ја добиваат наградата ‘Златна лира’ врачена од СМУМ. Во текот на својата повеќегодишна работа, дуото Гелебешеви имаат објавено и две аудио изданија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Денес Катерина Гелебешева Костадиновска работи како редовен професор по пијано на Факултетот за музичка уметност во Скопје.</p>\n<!-- /wp:paragraph -->','ВЕЧЕР ПОСВЕТЕНА НА КЛАРА ШУМАН – КОНЦЕРТ НА КАТЕРИНА ГЕЛЕБЕШЕВА КОСТАДИНОВСКА 12.11.2020 (ЧЕТВРТОК) 19ч.','','inherit','closed','closed','','851-revision-v1','','','2026-02-08 17:58:50','2026-02-08 17:58:50','',851,'https://user17.delovna.finki.ukim.mk/?p=853',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (854,1,'2026-02-08 17:59:35','2026-02-08 17:59:35','<!-- wp:paragraph -->\n<p>10/11/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/%D0%93%D0%B5%D0%BB%D0%B5%D0%B1%D0%B5%D1%81%D0%B5%D0%B2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4430} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/GELEBESEVA.jpg\" alt=\"\" class=\"wp-image-4430\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Katerina Gelebesheva Kostadinovska is an artist with a distinguished and individual pianistic sensibility, discovered and developed through the classes of professors Evuška Elezović-Trpkova and Todor Svetiev. She graduated from the Music Academy in Zagreb in 1991 in the class of the renowned professor and pianist Vladimir Krpan, and earned her master’s degree in Skopje in 1993 in the class of Professor Boris Romanov. She has participated in seminars led by eminent pianists and pedagogues including Kehrer, Muraro, Timakin, Ginzburg, Ikuko Endo, and others, as well as numerous competitions where she won top prizes. A particularly honorable achievement is the third prize at the 24th Young Music Artists Competition in Zagreb in 1990, as well as a special international recognition for performing works by B. Papandopulo in Grožnjan, Croatia, in 1986.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Her successful artistic career as a pianist, which began very early, includes numerous performances both in her home country and abroad — in Turkey, Portugal, Slovenia, Croatia, Italy, the Netherlands, France, and others — receiving outstanding responses from audiences and music critics. With special success and high critical acclaim, she has performed multiple times with the Macedonian Philharmonic, the Chamber Orchestra at the Faculty of Music Arts, the Zagreb Philharmonic, and the HRTV Symphony Orchestra Zagreb.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>In addition to her solo concert activity, she performs in various chamber ensembles. Since 2001 she has maintained an especially active concert career with the Gelebeshevi Piano Duo, formed with her husband Gligor Gelebeshev. The duo has performed at nearly all major festivals in the country, including Ohrid Summer, Skopje Summer, Bitola Summer, Interfest Bitola, Golden Lyre, Days of Macedonian Music, and others. With a performance in Paris in 2005, the duo began its international career, followed by concerts in Italy, the Netherlands, Romania, Poland, Serbia, Slovenia, Croatia, Bulgaria, Turkey, the USA, and more. In 2012 they received the “Golden Lyre” award from the Association of Music Artists. Over the years, the Gelebeshevi Duo has released two audio editions.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Today, Katerina Gelebesheva Kostadinovska works as a full professor of piano at the Faculty of Music Arts in Skopje.</p>\n<!-- /wp:paragraph -->','AN EVENING DEDICATED TO CLARA SCHUMANN — CONCERT BY KATERINA GELEBESHEVA KOSTADINOVSKA12.11.2020 (THURSDAY) — 19:00','','publish','open','open','','an-evening-dedicated-to-clara-schumann-concert-by-katerina-gelebesheva-kostadinovska12-11-2020-thursday-1900','','','2026-02-08 17:59:35','2026-02-08 17:59:35','',0,'https://user17.delovna.finki.ukim.mk/?p=854',0,'post','',0);
INSERT INTO `wp_posts` VALUES (855,1,'2026-02-08 17:59:35','2026-02-08 17:59:35','<!-- wp:paragraph -->\n<p>10/11/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/%D0%93%D0%B5%D0%BB%D0%B5%D0%B1%D0%B5%D1%81%D0%B5%D0%B2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4430} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/GELEBESEVA.jpg\" alt=\"\" class=\"wp-image-4430\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Katerina Gelebesheva Kostadinovska is an artist with a distinguished and individual pianistic sensibility, discovered and developed through the classes of professors Evuška Elezović-Trpkova and Todor Svetiev. She graduated from the Music Academy in Zagreb in 1991 in the class of the renowned professor and pianist Vladimir Krpan, and earned her master’s degree in Skopje in 1993 in the class of Professor Boris Romanov. She has participated in seminars led by eminent pianists and pedagogues including Kehrer, Muraro, Timakin, Ginzburg, Ikuko Endo, and others, as well as numerous competitions where she won top prizes. A particularly honorable achievement is the third prize at the 24th Young Music Artists Competition in Zagreb in 1990, as well as a special international recognition for performing works by B. Papandopulo in Grožnjan, Croatia, in 1986.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Her successful artistic career as a pianist, which began very early, includes numerous performances both in her home country and abroad — in Turkey, Portugal, Slovenia, Croatia, Italy, the Netherlands, France, and others — receiving outstanding responses from audiences and music critics. With special success and high critical acclaim, she has performed multiple times with the Macedonian Philharmonic, the Chamber Orchestra at the Faculty of Music Arts, the Zagreb Philharmonic, and the HRTV Symphony Orchestra Zagreb.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>In addition to her solo concert activity, she performs in various chamber ensembles. Since 2001 she has maintained an especially active concert career with the Gelebeshevi Piano Duo, formed with her husband Gligor Gelebeshev. The duo has performed at nearly all major festivals in the country, including Ohrid Summer, Skopje Summer, Bitola Summer, Interfest Bitola, Golden Lyre, Days of Macedonian Music, and others. With a performance in Paris in 2005, the duo began its international career, followed by concerts in Italy, the Netherlands, Romania, Poland, Serbia, Slovenia, Croatia, Bulgaria, Turkey, the USA, and more. In 2012 they received the “Golden Lyre” award from the Association of Music Artists. Over the years, the Gelebeshevi Duo has released two audio editions.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Today, Katerina Gelebesheva Kostadinovska works as a full professor of piano at the Faculty of Music Arts in Skopje.</p>\n<!-- /wp:paragraph -->','AN EVENING DEDICATED TO CLARA SCHUMANN — CONCERT BY KATERINA GELEBESHEVA KOSTADINOVSKA12.11.2020 (THURSDAY) — 19:00','','inherit','closed','closed','','854-revision-v1','','','2026-02-08 17:59:35','2026-02-08 17:59:35','',854,'https://user17.delovna.finki.ukim.mk/?p=855',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (856,1,'2026-02-08 18:00:52','2026-02-08 18:00:52','<!-- wp:paragraph -->\n<p>02/11/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/PLAKAT-TP-color-02.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Трајко Прокопиев (6.11.1909 – 20.01.1978)&nbsp;</strong>големиот македонски композитор диригент, музички педагог и организатор на музичкиот живот во Република Македонија. Еден од најдоследните поборници во изградбата на македонскиот национален музички правец, композитор кој беше сликар на човечката душа, композитор со широка словенска душа, длабоко мисловен и чувствителен, кој остави партитури со трајни вредности и дела со хумани пораки.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Роден во Куманово 1909, дипломира на Музичката школа во Белград 1934, Прв директор на Средното музичко училиште во Скопје 1944, студент на Прашкиот конзерваториум 1946-47, Началник на музичката програма на Радио Скопје и диригент на симфонискиот Радио оркестар, 1948 работи како диригент на хорот “Кочо Рацин” и ја добива наградата на Министерството за просвета и култура на НРМ за хорската песна “Ленка“, 1949 со премиерата на “Продадена невеста“ од Сметана дебитира како оперски диригент, 1951 – 54 ја диригира Вердиевата опера “Трубадур”, диригира со симфонискиот концерт на Македонската филхармонија, ја диригира Вердиевата опера “Риголето“, ги диригира премиерите на балетот “Копелија” од Лео Делиб и операта “Севилскиот бербер” од Ѓоакино Росини, 1963 се враќа на старото место како диригент на МНТ, со група македонски композитори гостува во Грузија, во Ленинград се сретнува со Дмитриј Шостакович, работи како директорна Ансамблот за народни песни и игри на Македонија “Танец”, 1967 ја добива Октомвриската награда за животно дело на СР Македонија, 1969 со хорот “Кочо Рацин” ја освојува првата награда на VIII интернационален фестивал на хорови во Горица, Италија, 1975 се пензионира, 1977 ја добива наградата АВНОЈ за музика,1978 ја завршува оркестрацијата на операта “Кузман Капидан”, 1979 умира во Белград. Погребан е во Скопје, во Алејата на великаните на Градските гробишта во Бутел.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Име кое претставува едно од најплодните и најзначајни композиторски имиња на Македонија, со петдецениско творештво, кое е дел од историјата на младата македонска музичка култура и вредни дела, како хорските дела: “Ленка“, “Кумановки од I до VI“, “Илинденка“, “Очи“, “Свадбарска“, “Туѓина“, “Роса“, “Ракатка II“, и други, духовна музика, бројни камерни композиции, сценска и филмска музика “Чорбаџи Теодос“, “Бегалка“, “Илинден 1903“, “Комитска легемда“ и други музичко-сценски дела: балетот “лабин и Дојрана“ и оперите “Разделба“ и “Кузман Капидан“, кои влегуваат во антологијата на македонската музика, а сите проткаени со теми и експресии, како и разновидниритмички структури од македонско фолклорно богатство. Дела од кои зрачат убавината и духот на родното и поширокото македонско тло.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“…На оваа могила ќе доаѓа цела Македонија, да му се поклонуваат вистинските љубители и познавачи на музичката уметност… Од таткото на македонската музичка култура ќе остане неговата творечка порака, неговата композиторска мисла како светол, блескав пример и патоказ…“<br>Властимир Николовски,<br>од името на Друштвото на композиторите на Македонија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','ВЕЧЕР ПОСВЕТЕНА НА ТРАЈКО ПРОКОПИЕВ 06.11.2020 (ПЕТОК) САЛА ТЕАТАР 19.00ч.','','publish','open','open','','%d0%b2%d0%b5%d1%87%d0%b5%d1%80-%d0%bf%d0%be%d1%81%d0%b2%d0%b5%d1%82%d0%b5%d0%bd%d0%b0-%d0%bd%d0%b0-%d1%82%d1%80%d0%b0%d1%98%d0%ba%d0%be-%d0%bf%d1%80%d0%be%d0%ba%d0%be%d0%bf%d0%b8%d0%b5%d0%b2-06-11-202','','','2026-02-08 18:01:04','2026-02-08 18:01:04','',0,'https://user17.delovna.finki.ukim.mk/?p=856',0,'post','',0);
INSERT INTO `wp_posts` VALUES (857,1,'2026-02-08 18:00:06','2026-02-08 18:00:06','','PLAKAT-TP-color-02','','inherit','open','closed','','plakat-tp-color-02','','','2026-02-08 18:00:06','2026-02-08 18:00:06','',856,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/PLAKAT-TP-color-02.jpg',0,'attachment','image/jpeg',0);
INSERT INTO `wp_posts` VALUES (858,1,'2026-02-08 18:00:52','2026-02-08 18:00:52','<!-- wp:paragraph -->\n<p>02/11/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/11/PLAKAT-TP-color-02.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Трајко Прокопиев (6.11.1909 – 20.01.1978)&nbsp;</strong>големиот македонски композитор диригент, музички педагог и организатор на музичкиот живот во Република Македонија. Еден од најдоследните поборници во изградбата на македонскиот национален музички правец, композитор кој беше сликар на човечката душа, композитор со широка словенска душа, длабоко мисловен и чувствителен, кој остави партитури со трајни вредности и дела со хумани пораки.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Роден во Куманово 1909, дипломира на Музичката школа во Белград 1934, Прв директор на Средното музичко училиште во Скопје 1944, студент на Прашкиот конзерваториум 1946-47, Началник на музичката програма на Радио Скопје и диригент на симфонискиот Радио оркестар, 1948 работи како диригент на хорот “Кочо Рацин” и ја добива наградата на Министерството за просвета и култура на НРМ за хорската песна “Ленка“, 1949 со премиерата на “Продадена невеста“ од Сметана дебитира како оперски диригент, 1951 – 54 ја диригира Вердиевата опера “Трубадур”, диригира со симфонискиот концерт на Македонската филхармонија, ја диригира Вердиевата опера “Риголето“, ги диригира премиерите на балетот “Копелија” од Лео Делиб и операта “Севилскиот бербер” од Ѓоакино Росини, 1963 се враќа на старото место како диригент на МНТ, со група македонски композитори гостува во Грузија, во Ленинград се сретнува со Дмитриј Шостакович, работи како директорна Ансамблот за народни песни и игри на Македонија “Танец”, 1967 ја добива Октомвриската награда за животно дело на СР Македонија, 1969 со хорот “Кочо Рацин” ја освојува првата награда на VIII интернаци