evision','',0);
INSERT INTO `wp_posts` VALUES (861,1,'2026-02-08 18:02:09','2026-02-08 18:02:09','<!-- wp:paragraph -->\n<p>09/10/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/10/koncert-duo-pijano-2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->','15.10.2020 (ЧЕТВРТОК) МАЛА САЛА 20ч. МУЗИЧКО ПАТУВАЊЕ НИЗ СВЕТОТ','','publish','open','open','','15-10-2020-%d1%87%d0%b5%d1%82%d0%b2%d1%80%d1%82%d0%be%d0%ba-%d0%bc%d0%b0%d0%bb%d0%b0-%d1%81%d0%b0%d0%bb%d0%b0-20%d1%87-%d0%bc%d1%83%d0%b7%d0%b8%d1%87%d0%ba%d0%be-%d0%bf%d0%b0%d1%82%d1%83%d0%b2','','','2026-02-08 18:02:09','2026-02-08 18:02:09','',0,'https://user17.delovna.finki.ukim.mk/?p=861',0,'post','',0);
