INSERT INTO `wp_posts` VALUES (917,1,'2026-02-08 18:16:24','2026-02-08 18:16:24','<!-- wp:paragraph -->\n<p>06/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/PLAKAT-2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>КОНЦЕРТ “ЗА ДАМАТА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ТРИО ЏЕНТЛМЕН</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>09.07.2020 (ЧЕТВРТОК)<br>ПЛАТО НА ЦЕНТАРОТ ЗА КУЛТУРА 20 ч.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ДЕЈАН СТОЕВ – тенор,<br>КРИСТИЈАН АНТОВСКИ – баритон<br>и ЈАНЕ ДУНИМАГЛОСКИ – тенор</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ПРОГРАМА:<br>Caruso, Que sara, Mama son tanto felice, Parla piu piano, L’Italiano vero, Volare, Piensa en mi,<br>Quisaz, Beautiful Maria, Тајно моја, Штом се сака, Едно лето, Само сеќавања…</p>\n<!-- /wp:paragraph -->','КОНЦЕРТ “ЗА ДАМАТА“ – ТРИО ЏЕНТЛМЕН 09.07.2020 (ЧЕТВРТОК) ПЛАТО НА ЦЕНТАРОТ 20 ч.','','publish','open','open','','%d0%ba%d0%be%d0%bd%d1%86%d0%b5%d1%80%d1%82-%d0%b7%d0%b0-%d0%b4%d0%b0%d0%bc%d0%b0%d1%82%d0%b0-%d1%82%d1%80%d0%b8%d0%be-%d1%9f%d0%b5%d0%bd%d1%82%d0%bb%d0%bc%d0%b5%d0%bd-09-07','','','2026-02-08 18:16:24','2026-02-08 18:16:24','',0,'https://user17.delovna.finki.ukim.mk/?p=917',0,'post','',0);
