INSERT INTO `wp_posts` VALUES (919,1,'2026-02-08 18:16:24','2026-02-08 18:16:24','<!-- wp:paragraph -->\n<p>06/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/PLAKAT-2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>КОНЦЕРТ “ЗА ДАМАТА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ТРИО ЏЕНТЛМЕН</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>09.07.2020 (ЧЕТВРТОК)<br>ПЛАТО НА ЦЕНТАРОТ ЗА КУЛТУРА 20 ч.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ДЕЈАН СТОЕВ – тенор,<br>КРИСТИЈАН АНТОВСКИ – баритон<br>и ЈАНЕ ДУНИМАГЛОСКИ – тенор</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ПРОГРАМА:<br>Caruso, Que sara, Mama son tanto felice, Parla piu piano, L’Italiano vero, Volare, Piensa en mi,<br>Quisaz, Beautiful Maria, Тајно моја, Штом се сака, Едно лето, Само сеќавања…</p>\n<!-- /wp:paragraph -->','КОНЦЕРТ “ЗА ДАМАТА“ – ТРИО ЏЕНТЛМЕН 09.07.2020 (ЧЕТВРТОК) ПЛАТО НА ЦЕНТАРОТ 20 ч.','','inherit','closed','closed','','917-revision-v1','','','2026-02-08 18:16:24','2026-02-08 18:16:24','',917,'https://user17.delovna.finki.ukim.mk/?p=919',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (920,1,'2026-02-08 18:16:55','2026-02-08 18:16:55','<!-- wp:paragraph -->\n<p>06/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/PLAKAT-2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>CONCERT “FOR THE LADY”<br>TRIO GENTLEMAN</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dejan Stoev — tenor<br>Kristijan Antovski — baritone<br>Jane Dunimagloski — tenor</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Program:<br>Caruso, Que Sera, Mama Son Tanto Felice, Parla Più Piano, L’Italiano Vero, Volare, Piensa en Mí,<br>Quizás, Beautiful Maria, Tajno Moja, Shtom Se Saka, Edno Leto, Samo Sekjavanja…</p>\n<!-- /wp:paragraph -->','CONCERT “FOR THE LADY” — TRIO GENTLEMAN — 09.07.2020 (THURSDAY) — CENTER FOR CULTURE PLATEAU — 20:00','','publish','open','open','','concert-for-the-lady-trio-gentleman-09-07-2020-thursday-center-for-culture-plateau-2000','','','2026-02-08 18:16:55','2026-02-08 18:16:55','',0,'https://user17.delovna.finki.ukim.mk/?p=920',0,'post','',0);
INSERT INTO `wp_posts` VALUES (921,1,'2026-02-08 18:16:55','2026-02-08 18:16:55','<!-- wp:paragraph -->\n<p>06/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/PLAKAT-2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>CONCERT “FOR THE LADY”<br>TRIO GENTLEMAN</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dejan Stoev — tenor<br>Kristijan Antovski — baritone<br>Jane Dunimagloski — tenor</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Program:<br>Caruso, Que Sera, Mama Son Tanto Felice, Parla Più Piano, L’Italiano Vero, Volare, Piensa en Mí,<br>Quizás, Beautiful Maria, Tajno Moja, Shtom Se Saka, Edno Leto, Samo Sekjavanja…</p>\n<!-- /wp:paragraph -->','CONCERT “FOR THE LADY” — TRIO GENTLEMAN — 09.07.2020 (THURSDAY) — CENTER FOR CULTURE PLATEAU — 20:00','','inherit','closed','closed','','920-revision-v1','','','2026-02-08 18:16:55','2026-02-08 18:16:55','',920,'https://user17.delovna.finki.ukim.mk/?p=921',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (922,1,'2026-02-08 18:17:48','2026-02-08 18:17:48','<!-- wp:paragraph -->\n<p>27/11/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/11/oboa-plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>КОНЦЕРТ – СО ЗВУЦИТЕ НА ОБОАТА… – 03.12.2019 (ВТОРНИК) МАЛА САЛА 19.00ч.</strong><br><strong>ГОРДАНА</strong><br><strong>ЈОСИФОВА НЕДЕЛКОВСКА,</strong><br><strong>обоа</strong><br><strong>ЕЛЕНА</strong><br><strong>АТАНАСОВСКА ИВАНОВСКА,</strong><br><strong>пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>ПРОГРАМА:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><strong>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ј. С. Бах – Ариа за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ф. Геминиани&nbsp; – Соната за за обоа и пијано&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Анданте</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Алегро</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ларго</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Алегро</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>3.&nbsp;&nbsp;&nbsp;&nbsp;С. Вероуст – Концертно соло за обоа и пијано Бр. 4&nbsp;&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>4. Ч. Колин – Конкурс за соло бр. 1 оп.33 – за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>5. Т. Лалиет – Фантазие оригинале оп. 6 за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>6. Е. Мориконе: Обоата на Габриел (Мисија) за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>7. „Не си го продавај Кољо“ за обоа и пијано (аранжман Кире Костов)</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p><strong>ГОРДАНА ЈОСИФОВА-НЕДЕЛКОВСКА (ОБОИСТ)</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„<em>Енио Мориконе беше воодушевен од настапот на обоистката Гордана Јосифова-Неделковска, која е селектор на музичката програма на фестивалот: Ме смири нејзиното свирење. Толку е внимателна, елоквентна и прецизна во изразот што веднаш ме воодушеви кога ја слушнав. Не очекував дека ќе чујам таков настап – рече Мориконе и посака да настапи со неа специјално на отворањето</em>.“ (Дневник, 13.07.2009)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Проф. м-р Гордана Јосифова-Неделковска дипломира и магистрира на Факултетот за музичка уметност при Универзитетот „Св. Кирил и Методиј“ во Скопје, во класата на проф. Киро Давидовски, а се усовршува на академијата „Моцарт“ во Варшава, Полска и BANFF центарот за музика и звук во Канада, како нивен стипендист. Добитник е на повеќе награди на државни и меѓународни натпревари.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Јосифова-Неделковска како солист настапува со многу значајни оркестри како Симфонискиот оркестар на националната капела на Санкт-Петербург, камерниот оркестар „Музика вива“ под водство на истакнатиот диригент и виолончелист Александар Рудин, Сервантес Филхармонија од Шпанија, oркестарот Кими Синфониета од Финска, оркестарот на Вилах Филхармонија од Австрија, оркестарот на Моравската Филхармонија од Чешка, оркестарот Талин Синфониета од Естонија, Симфонискиот оркестар на Рим, Симфонискиот оркестар на Белград, Гудачкиот камерен оркестар на Словенската филхармонија, камерниот оркестар „Софиски Солисти“, Македонската филхармонија, Македонскиот камерен оркестар, камерниот оркестар „Св. Ѓорѓе“, Оркестар на Авињон-Прованса, Камерен оркестар на Порто Алегре – Бразил, Обединет европски камерен оркестар, итн. Со бројни рецитали има настапувано во Канада, САД, Кина, Бразил, Естонија, Холандија, Франција, Белгија, Шпанија, Португалија, Полска, Италија, Германија, Чешка, Русија, Украина (настап со извонредниот виолинист Најџел Кенеди), Финска, Турција, Грција, Бугарија, Хрватска, Словенија, Босна и Херцеговина, Србија, Црна Гора и Македонија, настапувајќи во сали како престижните: „Верди“ во Милано, Аудиториумот&nbsp; „S. Margherita“ во Венеција, „Botteghino Auditorium conciliazione“ во Рим, „Сметана Хол“ во Прага, итн. Репертоарот на Јосифова-Неделковска опфаќа дела од раниот барок, па се до современото творештво, вклучувајќи и бројни праизведби на дела од современите композитори и голем број на дела од македонски автори. Од големо значење е поканата од страна на легендарниот Енио Мориконе, Гордана Јосифова-Неделковска да настапи заедно со него на свеченото отворање на фестивалот „Охридско Лето“ во 2009 година.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>По успешното претставување во 2010 на московскиот „Арт Новембер“ фестивал, каде критиката ја претстави како „поетеса на обоа“, Јосифова-Неделковска активно настапува во Русија и тоа на фестивали како Бах Маратонот во 2011 година и Моцарт Маратонот во 2014 година, делејќи ја сцената на најпознатата руска сала, Бољшој Зал, со едни од најистакнатите светски музички имиња: Петер Лаул, Александар Гиндин, Алексеј Володин, Илја Гринголц, Кристофер Тејлор и други.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Она што ја прави комплетна нејзината личност се несомнено и нејзините организаторски способности. Во изминатиот период заземала повеќе значајни функции: претседател на Музичката младина на Македонија, шеф на катедрата за дувачки инструменти на Факултетот за музичка уметност, а во два мандата е и продекан на истиот факултет и член на сенатот на УКИМ. Од 2005 година е назначена&nbsp; за претседател на Комисијата&nbsp; за култура&nbsp; на Универзитетот „Св. Кирил и Методиј“, а исто така со предлог на УКИМ, а по избор од страна на собранието на Република Македонија, е избрана за член на советот на Македонската радио-телевизија во два мандата. Во 2008 година (од страна на тогашниот ректор на универзитетот „Св. Кирил и Методиј“, Ѓорѓи Мартиновски) и е доделена плакета во знак на признание, за придонес во афирмација на универзитетот во земјата и странство. Како член е ангажирана и во неколку други одбори, меѓу кои одборoт за доделување на наградата „Св. Климент Охридски“, а од 2014 година член е на одборот за доделување на наградата „Мајка Тереза“. Во периодот 2001-2003 била&nbsp; претседател на Управниот одбор&nbsp; и селектор на музичката програма на фестивалот „Охридско лето“, а од 2007 – 2016 година е селектор на музичката програма на овој најреномиран фестивал во државата.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Нејзиното дејствување е од особено значење за културата во Република Македонија. Таа се има закитено и со многу награди и признанија, меѓу кои е и наградата „13 Ноември“, која ја доби во 2009 година од Град Скопје за високи достигнувања на меѓународната музичка сцена. Во 2014 година се закити и со наградата „Виртуози“ во категоријата меѓународна афирмација. Гордана Јосифова Неделковска, за нејзините достигнувања во промоцијата на уметноста во Македонија, промоцијата на македонската уметност надвор од земјата и поддршката на промоцијата на француската култура во Македонија, е одликувана со престижниот орден на Република Франција – „Витез од Редот на уметности и книжевност“, кој се вбројува во четирите најважни одликувања во Франција.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Успешноста на нејзиното делување е потврдена&nbsp; со едно светско признание – имено, во 2004 година&nbsp; од Уредничкиот одбор на Американскиот биографски институт Гордана Јосифова-Неделковска е номинирана&nbsp; во категоријата&nbsp; „Успешни жени на 21 век“. Во публикацијата која содржи биографии и трудови на жените кои се влијателни и креативни во општествениот живот во своите земји, токму таа е избрана&nbsp; меѓу жените во светот,&nbsp; бидејќи со своето делување како уметник и педагог оставила длабоки&nbsp; траги во својата средина. Во текстот на Американскиот биографски институт се наведува дека Гордана Јосифова-Неделковска е една од успешните жени на 21 век, која со својата севкупна активност&nbsp; може да послужи како пример и патоказ за младите генерации.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Гордана Јосифова-Неделковска е редовен професор по предметите обоа, камерна музика и методика на наставата на дувачките инструменти на Факултетот за музичка уметност – Скопје. Од учебната 2009/2010 година таа е избрана за декан на овој факултет, а во учебната 2013/2014 година е реизбрана за декан за уште еден мандатен период. Од 15.09.2016 е назначена за Проректор за меѓународна соработка на Универзитетот „Св. Кирил и Методиј“ во Скопје.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>м-р ЕЛЕНА АТАНАСОВСКА ИВАНОВСКА</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Елена Атанасовска-Ивановска е една од најуспешните и најафирмираните пијанисти во Република Македонија, која активно учествува во музичкиот живот во земјава, но и надвор од неа. Основното и средното музичко образование го завршува во ДМБУЦ „Илија Николовски – Луј“ во класата на проф.&nbsp;Лепа Мрмевска. Дипломира со највисока оцена CUM LAUDE на Факултетот за музичк­а уметност во Скопје во класата на еминентниот проф. Борис Романов. Во 2005 година завршува постдипломски студии во класата на истиот професор.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во текот на музичкото образование се здобива со награди на државни и меѓународни натпревари. Повеќе први награди на републичко ниво, I награда на меѓународниот натпревар „Златен Лист“ во категорија на дуо состав во Сан Бартоломео, Италија (1996), II награда на истиот натпревар во категорија соло пијано (1996), II награда на натпреварот „Музиката и земјата“ во категорија на камерни состави, Софија, Р. Бугарија (1996), III награда на Шопеновиот натпревар во Нови Сад, Србија (1997).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Учествувала на пијано семинари кај еминентни професори: проф. Љ. Рошчина, проф. С. Доренски, проф. А. Бондурјански,проф. А. Валдма, проф. Ј. Михајловиќ, проф. М. Молова, проф. Н. Макарова, но најплодна и најуспешна е соработката со рускиот проф. Борис Романов, во чија класа ги продолжува студиите по пијано.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Учествувала на летната музичка школа „Нови имиња“ во Суздаљ, Русија, каде што имаше забележителен настап на концертот на најуспешни семинаристи.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во 2003 година добива награда за најдобар студент од фондацијата „Франк Манинг“.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Повеќепати имала соло настапи&nbsp; со Македонската Филхармонија и Камерниот оркестар на Музичката Младина на Македонија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Бројни се концертите во рамките на домашните реномирани фестивали „Охридско лето“, „Скопско Лето“, „Есенски музички свечености“, „Интерфест Битола“, „Денови на Македонска музика“, „Битолско лето“, „Гевгелиска есен“, но и фестивали надвор од земјава: „Сараевска Зима“ – Босна и Херцеговина, „Festival de Musica do palacio da Bolsa“ – Португалија, „Festival de Musica de Sant Pere de Rodes“ – Шпанија,&nbsp; „Guarnerius, Centar lepih umetnosti Jovana Kolundzije“- Р.Србија, „Carniarmonie“, „Нимус“- Р. Србија, „ДАМ фестивал“- Приштина, Косово и др.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со рецитали, полурецитали и како пијано соработник настапувала низ цела Македонија и надвор од неа: Русија, Америка, Франција, Шпанија, Португалија, Италија, Грција, Република Србија, Бугарија, Босна и Херцеговина, Косово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;Активно соработува со неколку уметници од Македонија, меѓу кои вредно е да се споменат проф. м-р Гордана Јосифова- Неделковска, обоа, пијано дуото со проф. д-р Марија Ѓошевска, проф. д-р Горан Начевски, баритон и Ристо Ѓоревски- кларинет.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во 2015 година имаше успешен настап во Москва, каде настапи како гостин на концертот на дувачкиот квинтет од „Балшој Театар“, Москва, а по покана од музичкото училиште „М. Балакирјев“, беше член на жири на 11-от Фестивал&nbsp; за Славјанска музика, во категорија пијано.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Соработувала со Македонската Филхармонија како нејзин надворешен пијанист, како и со оркестарот за филмска музика F.A.M.E.S.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во моментов работи како доцент по корепетиција и практика на Факултетот за музичка уметност- Скопје.&nbsp;</p>\n<!-- /wp:paragraph -->','КОНЦЕРТ – СО ЗВУЦИТЕ НА ОБОАТА… – 03.12.2019 (ВТОРНИК) МАЛА САЛА 19.00ч.','','publish','open','open','','%d0%ba%d0%be%d0%bd%d1%86%d0%b5%d1%80%d1%82-%d1%81%d0%be-%d0%b7%d0%b2%d1%83%d1%86%d0%b8%d1%82%d0%b5-%d0%bd%d0%b0-%d0%be%d0%b1%d0%be%d0%b0%d1%82%d0%b0-03-12-2019-%d0%b2','','','2026-02-08 18:17:48','2026-02-08 18:17:48','',0,'https://user17.delovna.finki.ukim.mk/?p=922',0,'post','',0);
INSERT INTO `wp_posts` VALUES (923,1,'2026-02-08 18:17:43','2026-02-08 18:17:43','','image_2026-02-08_191742404','','inherit','open','closed','','image_2026-02-08_191742404','','','2026-02-08 18:17:43','2026-02-08 18:17:43','',922,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/image_2026-02-08_191742404.png',0,'attachment','image/png',0);
INSERT INTO `wp_posts` VALUES (924,1,'2026-02-08 18:17:48','2026-02-08 18:17:48','<!-- wp:paragraph -->\n<p>27/11/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/11/oboa-plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>КОНЦЕРТ – СО ЗВУЦИТЕ НА ОБОАТА… – 03.12.2019 (ВТОРНИК) МАЛА САЛА 19.00ч.</strong><br><strong>ГОРДАНА</strong><br><strong>ЈОСИФОВА НЕДЕЛКОВСКА,</strong><br><strong>обоа</strong><br><strong>ЕЛЕНА</strong><br><strong>АТАНАСОВСКА ИВАНОВСКА,</strong><br><strong>пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>ПРОГРАМА:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><strong>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ј. С. Бах – Ариа за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ф. Геминиани&nbsp; – Соната за за обоа и пијано&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Анданте</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Алегро</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Ларго</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Алегро</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>3.&nbsp;&nbsp;&nbsp;&nbsp;С. Вероуст – Концертно соло за обоа и пијано Бр. 4&nbsp;&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>4. Ч. Колин – Конкурс за соло бр. 1 оп.33 – за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>5. Т. Лалиет – Фантазие оригинале оп. 6 за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>6. Е. Мориконе: Обоата на Габриел (Мисија) за обоа и пијано</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>7. „Не си го продавај Кољо“ за обоа и пијано (аранжман Кире Костов)</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p><strong>ГОРДАНА ЈОСИФОВА-НЕДЕЛКОВСКА (ОБОИСТ)</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„<em>Енио Мориконе беше воодушевен од настапот на обоистката Гордана Јосифова-Неделковска, која е селектор на музичката програма на фестивалот: Ме смири нејзиното свирење. Толку е внимателна, елоквентна и прецизна во изразот што веднаш ме воодушеви кога ја слушнав. Не очекував дека ќе чујам таков настап – рече Мориконе и посака да настапи со неа специјално на отворањето</em>.“ (Дневник, 13.07.2009)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Проф. м-р Гордана Јосифова-Неделковска дипломира и магистрира на Факултетот за музичка уметност при Универзитетот „Св. Кирил и Методиј“ во Скопје, во класата на проф. Киро Давидовски, а се усовршува на академијата „Моцарт“ во Варшава, Полска и BANFF центарот за музика и звук во Канада, како нивен стипендист. Добитник е на повеќе награди на државни и меѓународни натпревари.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Јосифова-Неделковска како солист настапува со многу значајни оркестри како Симфонискиот оркестар на националната капела на Санкт-Петербург, камерниот оркестар „Музика вива“ под водство на истакнатиот диригент и виолончелист Александар Рудин, Сервантес Филхармонија од Шпанија, oркестарот Кими Синфониета од Финска, оркестарот на Вилах Филхармонија од Австрија, оркестарот на Моравската Филхармонија од Чешка, оркестарот Талин Синфониета од Естонија, Симфонискиот оркестар на Рим, Симфонискиот оркестар на Белград, Гудачкиот камерен оркестар на Словенската филхармонија, камерниот оркестар „Софиски Солисти“, Македонската филхармонија, Македонскиот камерен оркестар, камерниот оркестар „Св. Ѓорѓе“, Оркестар на Авињон-Прованса, Камерен оркестар на Порто Алегре – Бразил, Обединет европски камерен оркестар, итн. Со бројни рецитали има настапувано во Канада, САД, Кина, Бразил, Естонија, Холандија, Франција, Белгија, Шпанија, Португалија, Полска, Италија, Германија, Чешка, Русија, Украина (настап со извонредниот виолинист Најџел Кенеди), Финска, Турција, Грција, Бугарија, Хрватска, Словенија, Босна и Херцеговина, Србија, Црна Гора и Македонија, настапувајќи во сали како престижните: „Верди“ во Милано, Аудиториумот&nbsp; „S. Margherita“ во Венеција, „Botteghino Auditorium conciliazione“ во Рим, „Сметана Хол“ во Прага, итн. Репертоарот на Јосифова-Неделковска опфаќа дела од раниот барок, па се до современото творештво, вклучувајќи и бројни праизведби на дела од современите композитори и голем број на дела од македонски автори. Од големо значење е поканата од страна на легендарниот Енио Мориконе, Гордана Јосифова-Неделковска да настапи заедно со него на свеченото отворање на фестивалот „Охридско Лето“ во 2009 година.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>По успешното претставување во 2010 на московскиот „Арт Новембер“ фестивал, каде критиката ја претстави како „поетеса на обоа“, Јосифова-Неделковска активно настапува во Русија и тоа на фестивали како Бах Маратонот во 2011 година и Моцарт Маратонот во 2014 година, делејќи ја сцената на најпознатата руска сала, Бољшој Зал, со едни од најистакнатите светски музички имиња: Петер Лаул, Александар Гиндин, Алексеј Володин, Илја Гринголц, Кристофер Тејлор и други.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Она што ја прави комплетна нејзината личност се несомнено и нејзините организаторски способности. Во изминатиот период заземала повеќе значајни функции: претседател на Музичката младина на Македонија, шеф на катедрата за дувачки инструменти на Факултетот за музичка уметност, а во два мандата е и продекан на истиот факултет и член на сенатот на УКИМ. Од 2005 година е назначена&nbsp; за претседател на Комисијата&nbsp; за култура&nbsp; на Универзитетот „Св. Кирил и Методиј“, а исто така со предлог на УКИМ, а по избор од страна на собранието на Република Македонија, е избрана за член на советот на Македонската радио-телевизија во два мандата. Во 2008 година (од страна на тогашниот ректор на универзитетот „Св. Кирил и Методиј“, Ѓорѓи Мартиновски) и е доделена плакета во знак на признание, за придонес во афирмација на универзитетот во земјата и странство. Како член е ангажирана и во неколку други одбори, меѓу кои одборoт за доделување на наградата „Св. Климент Охридски“, а од 2014 година член е на одборот за доделување на наградата „Мајка Тереза“. Во периодот 2001-2003 била&nbsp; претседател на Управниот одбор&nbsp; и селектор на музичката програма на фестивалот „Охридско лето“, а од 2007 – 2016 година е селектор на музичката програма на овој најреномиран фестивал во државата.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Нејзиното дејствување е од особено значење за културата во Република Македонија. Таа се има закитено и со многу награди и признанија, меѓу кои е и наградата „13 Ноември“, која ја доби во 2009 година од Град Скопје за високи достигнувања на меѓународната музичка сцена. Во 2014 година се закити и со наградата „Виртуози“ во категоријата меѓународна афирмација. Гордана Јосифова Неделковска, за нејзините достигнувања во промоцијата на уметноста во Македонија, промоцијата на македонската уметност надвор од земјата и поддршката на промоцијата на француската култура во Македонија, е одликувана со престижниот орден на Република Франција – „Витез од Редот на уметности и книжевност“, кој се вбројува во четирите најважни одликувања во Франција.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Успешноста на нејзиното делување е потврдена&nbsp; со едно светско признание – имено, во 2004 година&nbsp; од Уредничкиот одбор на Американскиот биографски институт Гордана Јосифова-Неделковска е номинирана&nbsp; во категоријата&nbsp; „Успешни жени на 21 век“. Во публикацијата која содржи биографии и трудови на жените кои се влијателни и креативни во општествениот живот во своите земји, токму таа е избрана&nbsp; меѓу жените во светот,&nbsp; бидејќи со своето делување како уметник и педагог оставила длабоки&nbsp; траги во својата средина. Во текстот на Американскиот биографски институт се наведува дека Гордана Јосифова-Неделковска е една од успешните жени на 21 век, која со својата севкупна активност&nbsp; може да послужи како пример и патоказ за младите генерации.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Гордана Јосифова-Неделковска е редовен професор по предметите обоа, камерна музика и методика на наставата на дувачките инструменти на Факултетот за музичка уметност – Скопје. Од учебната 2009/2010 година таа е избрана за декан на овој факултет, а во учебната 2013/2014 година е реизбрана за декан за уште еден мандатен период. Од 15.09.2016 е назначена за Проректор за меѓународна соработка на Универзитетот „Св. Кирил и Методиј“ во Скопје.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>м-р ЕЛЕНА АТАНАСОВСКА ИВАНОВСКА</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Елена Атанасовска-Ивановска е една од најуспешните и најафирмираните пијанисти во Република Македонија, која активно учествува во музичкиот живот во земјава, но и надвор од неа. Основното и средното музичко образование го завршува во ДМБУЦ „Илија Николовски – Луј“ во класата на проф.&nbsp;Лепа Мрмевска. Дипломира со највисока оцена CUM LAUDE на Факултетот за музичк­а уметност во Скопје во класата на еминентниот проф. Борис Романов. Во 2005 година завршува постдипломски студии во класата на истиот професор.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во текот на музичкото образование се здобива со награди на државни и меѓународни натпревари. Повеќе први награди на републичко ниво, I награда на меѓународниот натпревар „Златен Лист“ во категорија на дуо состав во Сан Бартоломео, Италија (1996), II награда на истиот натпревар во категорија соло пијано (1996), II награда на натпреварот „Музиката и земјата“ во категорија на камерни состави, Софија, Р. Бугарија (1996), III награда на Шопеновиот натпревар во Нови Сад, Србија (1997).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Учествувала на пијано семинари кај еминентни професори: проф. Љ. Рошчина, проф. С. Доренски, проф. А. Бондурјански,проф. А. Валдма, проф. Ј. Михајловиќ, проф. М. Молова, проф. Н. Макарова, но најплодна и најуспешна е соработката со рускиот проф. Борис Романов, во чија класа ги продолжува студиите по пијано.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Учествувала на летната музичка школа „Нови имиња“ во Суздаљ, Русија, каде што имаше забележителен настап на концертот на најуспешни семинаристи.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во 2003 година добива награда за најдобар студент од фондацијата „Франк Манинг“.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Повеќепати имала соло настапи&nbsp; со Македонската Филхармонија и Камерниот оркестар на Музичката Младина на Македонија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Бројни се концертите во рамките на домашните реномирани фестивали „Охридско лето“, „Скопско Лето“, „Есенски музички свечености“, „Интерфест Битола“, „Денови на Македонска музика“, „Битолско лето“, „Гевгелиска есен“, но и фестивали надвор од земјава: „Сараевска Зима“ – Босна и Херцеговина, „Festival de Musica do palacio da Bolsa“ – Португалија, „Festival de Musica de Sant Pere de Rodes“ – Шпанија,&nbsp; „Guarnerius, Centar lepih umetnosti Jovana Kolundzije“- Р.Србија, „Carniarmonie“, „Нимус“- Р. Србија, „ДАМ фестивал“- Приштина, Косово и др.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со рецитали, полурецитали и како пијано соработник настапувала низ цела Македонија и надвор од неа: Русија, Америка, Франција, Шпанија, Португалија, Италија, Грција, Република Србија, Бугарија, Босна и Херцеговина, Косово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;Активно соработува со неколку уметници од Македонија, меѓу кои вредно е да се споменат проф. м-р Гордана Јосифова- Неделковска, обоа, пијано дуото со проф. д-р Марија Ѓошевска, проф. д-р Горан Начевски, баритон и Ристо Ѓоревски- кларинет.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во 2015 година имаше успешен настап во Москва, каде настапи како гостин на концертот на дувачкиот квинтет од „Балшој Театар“, Москва, а по покана од музичкото училиште „М. Балакирјев“, беше член на жири на 11-от Фестивал&nbsp; за Славјанска музика, во категорија пијано.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Соработувала со Македонската Филхармонија како нејзин надворешен пијанист, како и со оркестарот за филмска музика F.A.M.E.S.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во моментов работи како доцент по корепетиција и практика на Факултетот за музичка уметност- Скопје.&nbsp;</p>\n<!-- /wp:paragraph -->','КОНЦЕРТ – СО ЗВУЦИТЕ НА ОБОАТА… – 03.12.2019 (ВТОРНИК) МАЛА САЛА 19.00ч.','','inherit','closed','closed','','922-revision-v1','','','2026-02-08 18:17:48','2026-02-08 18:17:48','',922,'https://user17.delovna.finki.ukim.mk/?p=924',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (925,1,'2026-02-08 18:18:21','2026-02-08 18:18:21','<!-- wp:paragraph -->\n<p>27/11/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/11/oboa-plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>CONCERT — WITH THE SOUNDS OF THE OBOE…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Gordana Josifova-Nedelkovska — oboe<br>Elena Atanasovska-Ivanovska — piano</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>PROGRAM:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>J. S. Bach — Aria for Oboe and Piano</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>F. Geminiani — Sonata for Oboe and Piano<br>Andante<br>Allegro<br>Largo<br>Allegro</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>S. Verroust — Concert Solo No. 4 for Oboe and Piano</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>C. Colin — Competition Solo No. 1, Op. 33 — for Oboe and Piano</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>T. Lalliet — Fantaisie Originale, Op. 6 — for Oboe and Piano</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>E. Morricone — Gabriel’s Oboe (The Mission) — for Oboe and Piano</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>“Ne si go prodavaj Koljo” — for Oboe and Piano (arr. Kire Kostov)</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>—</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>GORDANA JOSIFOVA-NEDELKOVSKA (OBOIST)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“Ennio Morricone was delighted by the performance of oboist Gordana Josifova-Nedelkovska, selector of the festival’s music program: ‘Her playing calmed me. She is so attentive, eloquent, and precise in expression that I was immediately impressed when I heard her. I did not expect to hear such a performance,’ said Morricone, expressing his wish to perform with her at a festival opening.” (Dnevnik, 13.07.2009)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Prof. Gordana Josifova-Nedelkovska graduated and earned her master’s degree at the Faculty of Music Arts at Ss. Cyril and Methodius University in Skopje, and continued her training at the “Mozart” Academy in Warsaw and the Banff Centre for Music and Sound in Canada as a scholarship holder. She has won numerous national and international awards.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She has appeared as a soloist with many major orchestras worldwide, including orchestras in Saint Petersburg, Spain, Finland, Austria, the Czech Republic, Estonia, Italy, Serbia, Slovenia, Brazil, and others, as well as the Macedonian Philharmonic. She has performed in prestigious halls such as Verdi Hall in Milan, Smetana Hall in Prague, and major venues in Venice and Rome. Her repertoire ranges from early Baroque to contemporary music, including many premieres and works by Macedonian composers. She was invited by Ennio Morricone to perform with him at the opening of the Ohrid Summer Festival in 2009.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She has held numerous important leadership roles in Macedonian musical institutions and has received many honors, including the “13 November” Award of the City of Skopje and the French order Knight of the Order of Arts and Letters. She has been recognized internationally, including a nomination by the American Biographical Institute among Successful Women of the 21st Century. She is a full professor of oboe, chamber music, and wind pedagogy at the Faculty of Music Arts in Skopje and has served as dean and later as Vice-Rector for International Cooperation at the university.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>—</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>M.Sc. ELENA ATANASOVSKA-IVANOVSKA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Elena Atanasovska-Ivanovska is one of the most successful and recognized pianists in North Macedonia, active both domestically and internationally. She completed her music education in Skopje and graduated cum laude at the Faculty of Music Arts under Prof. Boris Romanov, later completing postgraduate studies with him.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She has won multiple national and international competition awards and has performed at many major festivals in Macedonia and abroad (Bosnia and Herzegovina, Portugal, Spain, Serbia, Kosovo, and others), as well as in Russia, the USA, France, Italy, Greece, and more. She has appeared as a soloist with the Macedonian Philharmonic and chamber orchestras, and collaborates with prominent Macedonian artists and ensembles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She has also performed in Moscow and served as a jury member at a Slavic music festival there. She collaborates with the Macedonian Philharmonic and the F.A.M.E.S. film music orchestra. She currently works as an assistant professor of accompaniment and performance practice at the Faculty of Music Arts in Skopje.</p>\n<!-- /wp:paragraph -->','CONCERT — WITH THE SOUNDS OF THE OBOE… — 03.12.2019 (TUESDAY) — SMALL HALL — 19:00','','publish','open','open','','concert-with-the-sounds-of-the-oboe-03-12-2019-tuesday-small-hall-1900','','','2026-02-08 18:18:22','2026-02-08 18:18:22','',0,'https://user17.delovna.finki.ukim.mk/?p=925',0,'post','',0);
