INSERT INTO `wp_posts` VALUES (1017,1,'2026-02-08 18:40:24','2026-02-08 18:40:24','<!-- wp:paragraph -->\n<p>27/03/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/03/MASKENBAL-2019-MK.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>12.04.2019 (Friday) — 19:00 — MASKED BALL FOR CHILDREN AND YOUTH<br>Registration no later than 11.04.2019 (Thursday) by 14:00, on every working day.</p>\n<!-- /wp:paragraph -->','12.04.2019 (FRIDAY) — 19:00 — GRAND HALL — MASKED BALL FOR CHILDREN AND YOUTH','','inherit','closed','closed','','1016-revision-v1','','','2026-02-08 18:40:24','2026-02-08 18:40:24','',1016,'https://user17.delovna.finki.ukim.mk/?p=1017',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1018,1,'2026-02-08 18:41:13','2026-02-08 18:41:13','<!-- wp:paragraph -->\n<p>18/10/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/%D0%93%D0%9E%D0%A0%D0%88%D0%90%D0%9D%D0%90-%D0%9F%D0%9B.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>ПРОГРАМА</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>R. Schumann<br>“Waldszenen”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>J. Haydn<br>Sonata HobXVI:50</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>F. Chopin<br>Phantasie Op.49</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>M. Ravel<br>“Le tombeau de Couperin”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Горјана Стојановска е родена на 11.12.1994 година во Битола, Македонија. На осумгодишна возраст го започнува своето музичко образование во Државното основното музичко училиште во Битола и продолжува и во средното музичко училиште во класата на д-р. Татјана Божиновска. Првите две години од високото образование на Факултетот за музичка уметност во Скопје, ги поминува во класата на проф. Борис Романов, а вторите две во класата на проф. д-р. Марија Ѓошевска, во чија класа и дипломира во 2017 година.Горјана Стојановска е родена на 11.12.1994 година во Битола, Македонија. На осумгодишна возраст го започнува своето музичко образование во Државното основното музичко училиште во Битола и продолжува и во средното музичко училиште во класата на д-р. Татјана Божиновска. Првите две години од високото образование на Факултетот за музичка уметност во Скопје, ги поминува во класата на проф. Борис Романов, а вторите две во класата на проф. д-р. Марија Ѓошевска, во чија класа и дипломира во 2017 година.Низ годините има освоено многу награди меѓу кои:· II награда на државниот натпревар по пијано во 2007 година во Битола· III награда на меѓународниот натпревар по пијано”Даворин Јенко” во 2008 година во Белград, Србија · Специјална награда за изведба на делото “Срцето на поетот” од Едвард Григ на меѓународниот натпревар по пијано “Охридски бисери” во 2008 година во Охрид, Македонија· Спецјална награда со максимум 100 поена и трет лауреат на државниот натпревар по пијано во 2010 година во Скопје, Македонија· Спецјална награда со максимум 100 поена на меѓународниот натпревар по пијано “Арс Косова”&nbsp; &nbsp; &nbsp; &nbsp;во 2010 година во Приштина, Косово· III награда на меѓународниот натпревар по пијано “Охридски бисери” во 2010 година во Охрид· Специјална награда со максимум 100 поена и лауреат на меѓународниот натпревар по камерна музика во категорија пијано-виолина во 2011 година во Кавадарци, Македонија· I награда на државниот натпревар по камерна музика во категорија пијано-виолина во 2011 година во Скопје· I награда на државниот по камерна музика во категорија дуо пијано во 2011 година во Скопје· I награда на државниот по камерна музика во категорија дуо пијано во 2011 година во Скопје· II награда на меѓународниот натпревар по пијано “Охридски бисери”во 2012 година во Охрид· Спецјална награда со максимум 100 поена, Гран При и ЕМCY награда на државниот натпревар по пијано во 2013 година во Скопје· Спецјална награда на полифониот конкурс во рамките на ФМУ-Скопје во 2014, 2015 и I награда на истиот во 2017 годинаВо текот на основното и средното музичко образование настапува на годишните концерти во организација на музичкото училиште во Битола и на годишниот концерт “Шопенова вечер”, како и на концерти во организација на Факултетот за музичка уметност-Скопје во текот на студиите на истиот. До сега има одржано повеќе солистички концерти, а во 2011 и 2014 година настапува како солист со Македонската филхармонија. Во 2008 година зема учество на фестивалот за пијано во организација на ЕПТА.Учествува на мастеркласи кај неколку професори меѓу кои Борис Романов, Јури Кот, Андреј Диев.</p>\n<!-- /wp:paragraph -->','25.10.2018 (ЧЕТВРТОК) КОНЦЕРТ НА СЕРИОЗНА МУЗИКА – ГОРЈАНА СТОЈАНОВСКА – ПИЈАНО МАЛА САЛА 19.00 ч.','','publish','open','open','','25-10-2018-%d1%87%d0%b5%d1%82%d0%b2%d1%80%d1%82%d0%be%d0%ba-%d0%ba%d0%be%d0%bd%d1%86%d0%b5%d1%80%d1%82-%d0%bd%d0%b0-%d1%81%d0%b5%d1%80%d0%b8%d0%be%d0%b7%d0%bd%d0%b0-%d0%bc%d1%83%d0%b7%d0%b8%d0%ba','','','2026-02-08 18:41:13','2026-02-08 18:41:13','',0,'https://user17.delovna.finki.ukim.mk/?p=1018',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1019,1,'2026-02-08 18:41:02','2026-02-08 18:41:02','','image_2026-02-08_194101527','','inherit','open','closed','','image_2026-02-08_194101527','','','2026-02-08 18:41:02','2026-02-08 18:41:02','',1018,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/image_2026-02-08_194101527.png',0,'attachment','image/png',0);
