INSERT INTO `wp_posts` VALUES (1043,1,'2026-02-08 18:46:07','2026-02-08 18:46:07','<!-- wp:paragraph -->\n<p>12/09/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/%D0%9A%D0%A3%D0%91%D0%90.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>12/09/2018</p>\n<!-- /wp:paragraph -->','THE CONCERT IS POSTPONED — CONCERT BY THE GROUP “ECOS FLAMENCO” FROM CUBA — 20.09.2018 (THURSDAY) — GRAND HALL — 21:00','','inherit','closed','closed','','1042-revision-v1','','','2026-02-08 18:46:07','2026-02-08 18:46:07','',1042,'https://user17.delovna.finki.ukim.mk/?p=1043',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1044,1,'2026-02-08 18:47:02','2026-02-08 18:47:02','<!-- wp:paragraph -->\n<p>26/06/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/06/naunov-str-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>ПРОГРАМА</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>1. Franz Schubert&nbsp;“ Auf dem wasser zu singen ”<br>2. Robert Schumann&nbsp;&nbsp;“ Singet nicht in trauertönen ”<br>3. Johannes Brahms“ Wir wandelten ”<br>4. Johannes Brahms&nbsp;&nbsp;“ Botschaft ”<br>5. Franz Schubert&nbsp;&nbsp;“ Der Hirt auf dem felsen ”<br>6. &nbsp; Franc Lehar”Dein ist mein ganzes Herz”&nbsp; &nbsp;исполнува: Влатко Груевски<br>7. Franc Lehar&nbsp;&nbsp;арија на Giuditta ” Meine Lippen, sie küssen so heib ”<br>8. Johann Strauss&nbsp;“Frulingsstimmen ”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":2726} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/06/%D0%90%D0%BD%D0%B0-%D0%A0%D0%BE%D1%98%D0%B4%D0%B5%D0%B2%D0%B0.jpg\" alt=\"\" class=\"wp-image-2726\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":2727} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/06/G38A0282-1-1024x683.jpg\" alt=\"\" class=\"wp-image-2727\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>АНА РОЈДЕВА – ТАЛЕВСКА (сопран). Родена е 1978 година во Скопје. Завршила соло пеење на Факултетот за музичка уметност во класата на проф. Марија Муратовска- Наумовска. Во текот на студирањето настапува на концерти организирани од ФМУ. Зема учество и на мајстрската школа на Мирела Паруто и Антонио Боаје во рамките на Интерфест- Битола. Нејзин постојан ментор е М-р Славица Петровска- Галиќ, првенец на Македонската Опера.<br>Во 2001 год. Дебитира на сцената на МОБ со улогата на Берта во “Севилскиот Бербер” од Џоакино Росини, потоа Церлина во “Дон Џовани” од Волфанг Амадеус Моцарт, Фраскита во “Кармен” од Жорж Бизе, Аделе во ”Лилјакот” од Јохан Штраус помладиот, Каролина во ”Таен Брак” од Чимароза, Првата Дама во ”Посета од Старата Дама” од Готфрид фон Аднем, Асиа во ”Лидија од Македонија” од Ристо Аврамовски, Рита во ”Рита” од Гаетано Доницети, Првата дама во ”Волшебната Флејта” од Волфанг Амадеус Моцарт, Првата Собарка од операта ”Џуџето” од Александар фон Злемински, Амор во ”Орфеј” од Кристоф Вилибалд Глук, Џована и Џилда во ”Риголето” од Џузепе Верди, Марика во ”Јованче и Марика” од Енгелберт Хумпердинк, Анина во ”Травијата” од Џузепе Верди, Кралицата на Ноќта во Мала ”Волшебна Флејта” од Волфанг Амадеус Моцарт, Другарките на Црвенкапа во операта ”Црвенкапа” од Цезар Кјус. Зема и учество на бројни настани, на гала оперски концерти на МОБ и рецитали во рамките на ”Скопско Лето”, ”Штипско Културно Лето”, ”Битолско Лето”.<br>Од септември 2004 е стипендист на Централно Источниот Европски музички театар од Виена. Од 2005 е солист во операта при Македонската Опера и Балет. Во 2010 год. се запишува на постипломски студии во класата на професор М-р Славица Петковска Галиќ при ФМУ. Во 2012 магистрира со концертна изведба на ”Љубовен Напиток” од Гаетано Доницети.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>АНДРЕЈ НАУНОВ е роден во Кочани. Дипломира на ФМУ – Скопје на одделот пијано во класата на Симон Трпчески, како негов прв студент во чија класа е и на постдипломски студии. Студира диригирање на ФМУ во класата на Саша Николовски- Ѓумар. Добитник е на државни награди по камерна музика и пијано во Македонија и странство, а има и остварено бројни солистички рецитали, настапи со Македонската филхармонија и оркестарот на Македонската Опера и Балет. Еден од позначајните настапи се турнеите со пијанистот и негов професор Симон Трпчески на територијата на Македонија.<br>Дава свој придонес и во хуманитарните манифестации како концертни изведби, претстави и сл Како корепетитор тој има извонредни можности да ги истакнува своите изведувачки вештини на пијаното низ завиден број настапи во државата со различни ансамбли и солисти во Македонија и странство (Швајцарија, Австрија, Србија, Германија, Унгарија, Романија, Словенија, Грција, САД). Како свои соработници во концертната – корепетиторска дејност има соработка со првенците на МОБ, како и со најистакнатите инструменталисти во државата. Во својот репертоар има околу 40 опери, како и кантати и ораториуми. Вработен е како корепетитор во Македонската Опера и Балет и како музички соработник на Факултетот за музичка уметност во Скопје.</p>\n<!-- /wp:paragraph -->','КОНЦЕРТ – ГЕРМАНСКА ВЕЧЕР АНА РОЈДЕВА – ТАЛЕВСКА И АНДРЕЈ НАУНОВ 26.06.2018 ВТОРНИК 20ч.','','publish','open','open','','%d0%ba%d0%be%d0%bd%d1%86%d0%b5%d1%80%d1%82-%d0%b3%d0%b5%d1%80%d0%bc%d0%b0%d0%bd%d1%81%d0%ba%d0%b0-%d0%b2%d0%b5%d1%87%d0%b5%d1%80-%d0%b0%d0%bd%d0%b0-%d1%80%d0%be%d1%98%d0%b4%d0%b5%d0%b2%d0%b0','','','2026-02-08 18:47:02','2026-02-08 18:47:02','',0,'https://user17.delovna.finki.ukim.mk/?p=1044',0,'post','',0);
