INSERT INTO `wp_posts` VALUES (1089,1,'2026-02-13 22:20:50','2026-02-13 22:20:50','<label> Your name\r\n    [text* your-name autocomplete:name] </label>\r\n\r\n<label> Your email\r\n    [email* your-email autocomplete:email] </label>\r\n\r\n<label> Subject\r\n    [text* your-subject] </label>\r\n\r\n<label> Your message (optional)\r\n    [textarea your-message] </label>\r\n\r\n[submit \"Submit\"]\n1\n[_site_title] \"[your-subject]\"\n[_site_title] <wordpress@user17.delovna.finki.ukim.mk>\napslabs24@gmail.com\nFrom: [your-name] [your-email]\r\nSubject: [your-subject]\r\n\r\nMessage Body:\r\n[your-message]\r\n\r\n-- \r\nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\nReply-To: [your-email]\n\n1\n1\n\n[_site_title] \"[your-subject]\"\n[_site_title] <wordpress@user17.delovna.finki.ukim.mk>\n[your-email]\nMessage Body:\r\n[your-message]\r\n\r\n-- \r\nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\nReply-To: [_site_admin_email]\n\n1\n1\nThank you for your message. It has been sent.\nThere was an error trying to send your message. Please try again later.\nOne or more fields have an error. Please check and try again.\nThere was an error trying to send your message. Please try again later.\nYou must accept the terms and conditions before sending your message.\nPlease fill out this field.\nThis field has a too long input.\nThis field has a too short input.\nThere was an unknown error uploading the file.\nYou are not allowed to upload files of this type.\nThe uploaded file is too large.\nThere was an error uploading the file.\nPlease enter a date in YYYY-MM-DD format.\nThis field has a too early date.\nThis field has a too late date.\nPlease enter a number.\nThis field has a too small number.\nThis field has a too large number.\nThe answer to the quiz is incorrect.\nPlease enter an email address.\nPlease enter a URL.\nPlease enter a telephone number.','Contact from EN','','publish','closed','closed','','contact-from-en','','','2026-02-13 22:20:57','2026-02-13 22:20:57','',0,'https://user17.delovna.finki.ukim.mk/?post_type=wpcf7_contact_form&#038;p=1089',0,'wpcf7_contact_form','',0);
INSERT INTO `wp_posts` VALUES (1090,1,'2026-02-13 22:21:15','2026-02-13 22:21:15','<!-- wp:contact-form-7/contact-form-selector {\"id\":1089,\"hash\":\"a3cb493\",\"title\":\"Contact from EN\"} -->\n<div class=\"wp-block-contact-form-7-contact-form-selector\">[contact-form-7 id=\"a3cb493\" title=\"Contact from EN\"]</div>\n<!-- /wp:contact-form-7/contact-form-selector -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Contact','','inherit','closed','closed','','105-revision-v1','','','2026-02-13 22:21:15','2026-02-13 22:21:15','',105,'https://user17.delovna.finki.ukim.mk/?p=1090',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1091,1,'2026-02-13 22:35:43','2026-02-13 22:35:43','<!-- wp:paragraph -->\n<p>30/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Работилница и разговор за книгата „ВЕДРА“ со нашата најмлада публика заедно со авторката Јулијана Величковска.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дебата за авторскиот превод.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Каде е и каков е преводот во денешно време.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со кои предизвици се соочуваат преведувачите и авторите.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дебатираа: Елена Алексиева (Бугарија), Катица Гаровска (Македонија), Петар Андоновски (Македонија) и Стефан Пуљаревиќ (Словенија).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Модератор: Владимир Мартиновски</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Втора вечер.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Учесници: Калина Малеска, Живко Грозданоски, Елена Алексиева, Арлинд Фаризи и Стефан Алијевиќ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Модератор: Ана Јовковска<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-7-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-7-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-7-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-7-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-8-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-8-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-8-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/2-8-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-8-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-8-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-8-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-8-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-8-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-8-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-8-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-8-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-8-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-8-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-8-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/5-8-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/6-7-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/6-7-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/6-7-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/6-7-768x512.jpg 768w\">&nbsp;<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-6-1024x683.jpg\" alt=\"\" width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-6-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-6-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-6-76