INSERT INTO `wp_posts` VALUES (1094,1,'2026-02-13 22:37:13','2026-02-13 22:37:13','<!-- wp:paragraph -->\n<p>30/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Workshop and discussion about the book “VEDRA” with our youngest audience together with the author Julijana Veličkovska.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Debate: <strong>Authorial Translation — Current State and Challenges</strong><br>Topics:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Where translation stands today and what it looks like</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>What challenges translators and authors face</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Debate participants:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Elena Aleksieva (Bulgaria)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Katica Garovska (North Macedonia)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Petar Andonovski (North Macedonia)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Stefan Puljarević (Slovenia)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Moderator: Vladimir Martinovski</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Second Evening — Literary Program</strong><br>Participants:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Kalina Maleska</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Živko Grozdanoski</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Elena Aleksieva</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Arlind Farizi</li>\n<!-- /wp:list-item -->\