INSERT INTO `wp_posts` VALUES (1109,1,'2026-02-13 22:45:03','2026-02-13 22:45:03','<!-- wp:paragraph -->\n<p>03/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/11.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Tonight we hosted our retirees from Kumanovo who, through their works under the title <em>April Playful Postcard</em>, read poetry and spent time socializing with one another.<img width=\"640\" height=\"960\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/9-683x1024.jpg 683w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/9-200x300.jpg 200w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/9-768x1152.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/9.jpg 1365w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/9-683x1024.jpg\" alt=\"\"> <img width=\"640\" height=\"960\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/10-683x1024.jpg 683w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/10-200x300.jpg 200w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/10-768x1152.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/10.jpg 1365w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/10-683x1024.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/11-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/11-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/11-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/11-1024x683.jpg\" alt=\"\"> <img width=\"640\" height=\"960\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/12-683x1024.jpg 683w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/12-200x300.jpg 200w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/12-768x1152.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/12.jpg 1365w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/12-683x1024.jpg\" alt=\"\"> <img width=\"640\" height=\"427\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/13-1024x683.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/13-300x200.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/13-768x512.jpg 768w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/13-1024x683.jpg\" alt=\"\"></p>\n<!-- /wp:paragraph -->','Playful Postcard','','publish','open','open','','playful-postcard','','','2026-02-13 22:45:30','2026-02-13 22:45:30','',0,'https://user17.delovna.finki.ukim.mk/?p=1109',0,'post','',0);
