INSERT INTO `wp_posts` VALUES (1134,1,'2026-02-13 22:51:51','2026-02-13 22:51:51','<!-- wp:paragraph -->\n<p>24/04/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>23 April<br>World Book and Copyright Day.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“Think carefully before you give something, think twice before you receive something, and think a thousand times before you ask for something.”<br>— Miguel de Cervantes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5602} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12-1-1024x682.jpg\" alt=\"\" class=\"wp-image-5602\"/></figure>\n<!-- /wp:image -->','World Book and Copyright Day','','publish','open','open','','world-book-and-copyright-day','','','2026-02-13 22:51:51','2026-02-13 22:51:51','',0,'https://user17.delovna.finki.ukim.mk/?p=1134',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1135,1,'2026-02-13 22:51:51','2026-02-13 22:51:51','<!-- wp:paragraph -->\n<p>24/04/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>23 April<br>World Book and Copyright Day.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“Think carefully before you give something, think twice before you receive something, and think a thousand times before you ask for something.”<br>— Miguel de Cervantes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5602} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12-1-1024x682.jpg\" alt=\"\" class=\"wp-image-5602\"/></figure>\n<!-- /wp:image -->','World Book and Copyright Day','','inherit','closed','closed','','1134-revision-v1','','','2026-02-13 22:51:51','2026-02-13 22:51:51','',1134,'https://user17.delovna.finki.ukim.mk/?p=1135',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1136,1,'2026-02-13 22:52:32','2026-02-13 22:52:32','<!-- wp:paragraph -->\n<p>05/04/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Со голема чест го најавуваме вториот по ред Меѓународен Фестивал на проза во Куманово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Оваа година фестивалот на два дена ќе ги вдоми домашните и странските автори, кои ќе се обидат, книжевноста да ја доближат до читателската публика. Целта на овој фестивал е прозата да стане дел од културата на секојдневното живеење.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дизајн на плакат: Стефан Јакимовски</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Се гледаме на 25 и 26 мај во Центар за култура Куманово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5531} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12-1024x390.jpg\" alt=\"\" class=\"wp-image-5531\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5532} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/13-734x1024.jpg\" alt=\"\" class=\"wp-image-5532\"/></figure>\n<!-- /wp:image -->','Меѓународен фестивал „Денови на прозата“ 2023','','publish','open','open','','%d0%bc%d0%b5%d1%93%d1%83%d0%bd%d0%b0%d1%80%d0%be%d0%b4%d0%b5%d0%bd-%d1%84%d0%b5%d1%81%d1%82%d0%b8%d0%b2%d0%b0%d0%bb-%d0%b4%d0%b5%d0%bd%d0%be%d0%b2%d0%b8-%d0%bd%d0%b0-%d0%bf%d1%80%d0%be%d0%b7-2','','','2026-02-13 22:52:32','2026-02-13 22:52:32','',0,'https://user17.delovna.finki.ukim.mk/?p=1136',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1137,1,'2026-02-13 22:52:32','2026-02-13 22:52:32','<!-- wp:paragraph -->\n<p>05/04/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Со голема чест го најавуваме вториот по ред Меѓународен Фестивал на проза во Куманово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Оваа година фестивалот на два дена ќе ги вдоми домашните и странските автори, кои ќе се обидат, книжевноста да ја доближат до читателската публика. Целта на овој фестивал е прозата да стане дел од културата на секојдневното живеење.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дизајн на плакат: Стефан Јакимовски</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Се гледаме на 25 и 26 мај во Центар за култура Куманово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5531} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12-1024x390.jpg\" alt=\"\" class=\"wp-image-5531\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5532} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/13-734x1024.jpg\" alt=\"\" class=\"wp-image-5532\"/></figure>\n<!-- /wp:image -->','Меѓународен фестивал „Денови на прозата“ 2023','','inherit','closed','closed','','1136-revision-v1','','','2026-02-13 22:52:32','2026-02-13 22:52:32','',1136,'https://user17.delovna.finki.ukim.mk/?p=1137',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1138,1,'2026-02-13 22:53:05','2026-02-13 22:53:05','<!-- wp:paragraph -->\n<p>05/04/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>With great honor, we announce the second International Prose Festival in Kumanovo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This year, over two days, the festival will host both domestic and international authors who will strive to bring literature closer to readers. The goal of this festival is to make prose part of everyday cultural life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Poster design: Stefan Jakimovski<br>See you on May 25 and 26 at the Center for Culture Kumanovo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5531} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12-1024x390.jpg\" alt=\"\" class=\"wp-image-5531\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5532} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/13-734x1024.jpg\" alt=\"\" class=\"wp-image-5532\"/></figure>\n<!-- /wp:image -->','International Festival “Days of Prose” 2023','','publish','open','open','','international-festival-days-of-prose-2023','','','2026-02-13 22:53:06','2026-02-13 22:53:06','',0,'https://user17.delovna.finki.ukim.mk/?p=1138',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1139,1,'2026-02-13 22:53:05','2026-02-13 22:53:05','<!-- wp:paragraph -->\n<p>05/04/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>With great honor, we announce the second International Prose Festival in Kumanovo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This year, over two days, the festival will host both domestic and international authors who will strive to bring literature closer to readers. The goal of this festival is to make prose part of everyday cultural life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Poster design: Stefan Jakimovski<br>See you on May 25 and 26 at the Center for Culture Kumanovo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5531} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/12-1024x390.jpg\" alt=\"\" class=\"wp-image-5531\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5532} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/13-734x1024.jpg\" alt=\"\" class=\"wp-image-5532\"/></figure>\n<!-- /wp:image -->','International Festival “Days of Prose” 2023','','inherit','closed','closed','','1138-revision-v1','','','2026-02-13 22:53:05','2026-02-13 22:53:05','',1138,'https://user17.delovna.finki.ukim.mk/?p=1139',0,'revision','',0);
