INSERT INTO `wp_posts` VALUES (1188,1,'2026-02-13 23:56:29','2026-02-13 23:56:29','<!-- wp:paragraph -->\n<p>22/10/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/%D0%91%D0%9E%D0%97%D0%90%D0%9D%D0%90-%D0%9F%D0%9B.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>With award-winning students<br>from primary and secondary schools</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Musical part: Students from the Municipal Music School “Panche Peshev” – Kumanovo</p>\n<!-- /wp:paragraph -->','29.10.2018 (MONDAY) – SMALL HALL – 6:00 PM – LITERARY–MUSICAL EVENING','','inherit','closed','closed','','1187-revision-v1','','','2026-02-13 23:56:29','2026-02-13 23:56:29','',1187,'https://user17.delovna.finki.ukim.mk/?p=1188',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1189,1,'2026-02-13 23:57:30','2026-02-13 23:57:30','<!-- wp:paragraph -->\n<p>28/11/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/11/FILIP-PETROVSKI-KNIGA-PL.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Филип Петровски е роден&nbsp; 1993 г. во Куманово. &nbsp;Дипломиран фаготист на ФМУ во Скопје. &nbsp;<br>Зад себе го има своето прво психолошко спиритуално книжевно дело&nbsp; „Светот во Световите“.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Книгата&nbsp; е плод на неговата духовна и психичка созреаност. &nbsp;Рецезент е на неколку книжевни дела и е промотор на истите. &nbsp;<br>Зема учество во многу музички манифестации и има бројни награди во областа на музиката како професионален музички уметник.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дали ќе преживееме на планетата Земја во блиска иднина?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ќе се уништиме ли самите себе како влог за нов живот таму горе?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дали Матка е само подземна пештера или таму се кријат светски тајни?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Љубовта за подобро утро згаснува во последните денови на планетата Земја,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>можеби за еден ден да воскресне уште посилна во новите вечности.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Вирусот е пуштен и никого не чека…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дали главниот лик ќе го издржи интензитетот на авантурата што постои?</p>\n<!-- /wp:paragraph -->','06.12.2018 (ЧЕТВРТОК) ПРОМОЦИЈА НА КНИГА “ПОСЛЕДНАТА КНИГА НА ПЛАНЕТАТА ЗЕМЈА“ – МАЛА САЛА 19ч.','','publish','open','open','','06-12-2018-%d1%87%d0%b5%d1%82%d0%b2%d1%80%d1%82%d0%be%d0%ba-%d0%bf%d1%80%d0%be%d0%bc%d0%be%d1%86%d0%b8%d1%98%d0%b0-%d0%bd%d0%b0-%d0%ba%d0%bd%d0%b8%d0%b3%d0%b0-%d0%bf%d0%be%d1%81%d0%bb%d0%b5','','','2026-02-13 23:57:31','2026-02-13 23:57:31','',0,'https://user17.delovna.finki.ukim.mk/?p=1189',0,'post','',0);
