INSERT INTO `wp_posts` VALUES (1196,1,'2026-02-13 23:58:36','2026-02-13 23:58:36','<!-- wp:paragraph -->\n<p>10/04/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/04/olivera-pok-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Сите мигови поминати,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; врежани во&nbsp; секоја мала ситница,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;втисната какo &nbsp;прав, како печат за потврда,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;како капка вода на дланка расипана,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;воздух низ прозорец влезен,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;китка чај истискана,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;јас сум …</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp; Биографија</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp; Оливера Доцевска&nbsp; дипломирала&nbsp; на Универзитетот „Св. Кирил и Методиј“ &nbsp;во Скопје, Правен факултет, правни студии, казнено правна група. Работи&nbsp; како адвокат. Поседува полуформална диплома на ОХЦХР и ООН. Магистрант е на Мастер студии&nbsp; Меѓународни односи и дипломатија на Правен факултет во Скопје. Таа е поетеса, активист за човекови права, хуманист, еволуционист, есеист, колумнист, приредувач и преведувач, уредник на нејзиниот портал за општество и култура budnost.mk</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Од 2012 година член е на Друштво на писатели на Македонија – ДПМ, а од 2014 – 2018 година е претседател на статутарна комисија на ДПМ воедно и &nbsp;член на Собраниски одбор на ДПМ.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp; Нејзина прва &nbsp;објавена стихозбирка е „Илузија за сон“ а&nbsp;&nbsp; потоа следат збирките: „Портокалова“- 2013 година, „Сончица – Сончоглед – Сунцокрет“ (тројазично издание), „Цветови на илузија – Cvetke iluzije“&nbsp; и „Еден миг од времето“&nbsp; 2015 година. Застапена е во повеќе антологии и зборници: Зборник на автори од регионот и Балканот „Алманах 2“, „Измеѓу два света – Сеќање на Бранка Миљковиќа“ 2012 и 2013 година (на македонски и српскохрватски јазик), „Бунт балканских жена“- 2013 година, интернет издание, „100.000 поети за промени„- интернет издание, Војводина 2012 година и Македонија 2017 година.&nbsp;&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp; Добитник е на наградите: „Денови на Бранко Миљковиќ“&nbsp; Ниш, Србија, Повелба за специјални заслуги&nbsp; за песната „Ода“, „Царица Теодора“, „Осми словенски кљекларски денови“, влегува во избор на 87 книги од регионот за наградата „Алекса Шантиќ“ во 2012 година, добитник е на посебно признание на „Трирема на јонска поезија„ Албанија.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3359} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/04/olivera-docevska-kniga-730x1024.jpg\" alt=\"\" class=\"wp-image-3359\"/></figure>\n<!-- /wp:image -->','17.04.2019 (СРЕДА) МАЛА САЛА 19.00 ч. ПРОМОЦИЈА НА КНИГА “ЕСТЕР ИХАЗ“ ОД ОЛИВЕРА ДОЦЕВСКА','','inherit','closed','closed','','1194-revision-v1','','','2026-02-13 23:58:36','2026-02-13 23:58:36','',1194,'https://user17.delovna.finki.ukim.mk/?p=1196',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1197,1,'2026-02-13 23:59:34','2026-02-13 23:59:34','<!-- wp:paragraph -->\n<p>10/04/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/04/olivera-pok-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>  All moments passed,<br>engraved in every little detail,<br>imprinted like dust, like a seal of confirmation,<br>like a drop of water spilled on the palm,<br>air entering through the window,<br>a squeezed bouquet of tea,<br>that is me…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Biography</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Olivera Docevska graduated from the <em>Ss. Cyril and Methodius University</em> in Skopje, Faculty of Law, criminal law program. She works as a lawyer. She holds a semi-formal diploma from OHCHR and the UN. She is a master’s candidate in International Relations and Diplomacy at the Faculty of Law in Skopje.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She is a poet, human rights activist, humanitarian, evolutionist, essayist, columnist, editor and translator, and editor of her society and culture portal budnost.mk.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Since 2012 she has been a member of the Society of Writers of Macedonia (DPM), and from 2014 to 2018 she served as president of the Statutory Commission of DPM and a member of its Assembly Board.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Her first published poetry book is <em>“Illusion for a Dream”</em>, followed by:<br><em>“Orange”</em> (2013),<br><em>“Sonchica – Sunflower – Suncokret”</em> (trilingual edition),<br><em>“Flowers of Illusion – Cvetke Iluzije”</em>,<br>and <em>“A Moment of Time”</em> (2015).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She is represented in multiple anthologies and collections across the region and the Balkans, including <em>Almanac 2</em>, <em>Between Two Worlds – In Memory of Branko Miljković</em>, <em>Rebellion of Balkan Women</em>, <em>100,000 Poets for Change</em>, and others.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She is the recipient of several awards and recognitions, including awards from the <em>Days of Branko Miljković</em> in Niš, Serbia, a Charter for Special Merit for the poem “Ode,” recognitions from Slavic poetry events, selection among 87 regional books for the “Aleksa Šantić” award, and a special recognition from the <em>Trireme of Ionian Poetry</em> in Albania.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3359} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/04/olivera-docevska-kniga-730x1024.jpg\" alt=\"\" class=\"wp-image-3359\"/></figure>\n<!-- /wp:image -->','17.04.2019 (WEDNESDAY) – SMALL HALL – 7:00 PM – BOOK PROMOTION “ESTER IHAZ” BY OLIVERA DOCEVSKA','','publish','open','open','','17-04-2019-wednesday-small-hall-700-pm-book-promotion-ester-ihaz-by-olivera-docevska','','','2026-02-13 23:59:34','2026-02-13 23:59:34','',0,'https://user17.delovna.finki.ukim.mk/?p=1197',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1198,1,'2026-02-13 23:59:34','2026-02-13 23:59:34','<!-- wp:paragraph -->\n<p>10/04/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/04/olivera-pok-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>  All moments passed,<br>engraved in every little detail,<br>imprinted like dust, like a seal of confirmation,<br>like a drop of water spilled on the palm,<br>air entering through the window,<br>a squeezed bouquet of tea,<br>that is me…</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Biography</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Olivera Docevska graduated from the <em>Ss. Cyril and Methodius University</em> in Skopje, Faculty of Law, criminal law program. She works as a lawyer. She holds a semi-formal diploma from OHCHR and the UN. She is a master’s candidate in International Relations and Diplomacy at the Faculty of Law in Skopje.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She is a poet, human rights activist, humanitarian, evolutionist, essayist, columnist, editor and translator, and editor of her society and culture portal budnost.mk.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Since 2012 she has been a member of the Society of Writers of Macedonia (DPM), and from 2014 to 2018 she served as president of the Statutory Commission of DPM and a member of its Assembly Board.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Her first published poetry book is <em>“Illusion for a Dream”</em>, followed by:<br><em>“Orange”</em> (2013),<br><em>“Sonchica – Sunflower – Suncokret”</em> (trilingual edition),<br><em>“Flowers of Illusion – Cvetke Iluzije”</em>,<br>and <em>“A Moment of Time”</em> (2015).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She is represented in multiple anthologies and collections across the region and the Balkans, including <em>Almanac 2</em>, <em>Between Two Worlds – In Memory of Branko Miljković</em>, <em>Rebellion of Balkan Women</em>, <em>100,000 Poets for Change</em>, and others.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She is the recipient of several awards and recognitions, including awards from the <em>Days of Branko Miljković</em> in Niš, Serbia, a Charter for Special Merit for the poem “Ode,” recognitions from Slavic poetry events, selection among 87 regional books for the “Aleksa Šantić” award, and a special recognition from the <em>Trireme of Ionian Poetry</em> in Albania.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3359} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/04/olivera-docevska-kniga-730x1024.jpg\" alt=\"\" class=\"wp-image-3359\"/></figure>\n<!-- /wp:image -->','17.04.2019 (WEDNESDAY) – SMALL HALL – 7:00 PM – BOOK PROMOTION “ESTER IHAZ” BY OLIVERA DOCEVSKA','','inherit','closed','closed','','1197-revision-v1','','','2026-02-13 23:59:34','2026-02-13 23:59:34','',1197,'https://user17.delovna.finki.ukim.mk/?p=1198',0,'revision','',0);
