INSERT INTO `wp_posts` VALUES (1204,1,'2026-02-14 00:03:35','2026-02-14 00:03:35','<!-- wp:paragraph -->\n<p>19/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>“ШШШ! Интимистичка Вајбер поезија“ на поетесата Елена Пренџова е најновото поетско остварување за кое таа е носителка на наградата „Јован Котески“ за 2018 година.</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>&nbsp;&nbsp;&nbsp; Поетесата во оваа најнова стихозбирка ги отвора железните порти на сопствените интимни соби. Насловот на стихозбирката е заводлив, бидејќи низ него испарува женскиот здив и ономатопејата „Шшш!“ како метафора за женскиот молк или цензурата на женскиот глас. Насловот е прва котва што ја разгатнува табу-темата да се говори низ женска оптика за интимниот свет и сексуалното искуство на жената. Интересно е што поетесата е во дослух со ерата на технологијата, а поезијата е разголување преку новата апликација вајбер како најпогодна за секојдневна комуникација на поголема просторна далечина.</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>     „ШШШ! Интимистичка вајбер поезија“ на Елена Пренџова е храбро поетско женско писмо кое заведува, намамува и преку субверзивниот женскиот глас носи општествени промени. Тоа е крик за женска телесна слобода, а воедно и поетска слобода за ludens преку јазикот и пишувањето. Со оваа одлично компонирана, стилски конструирана поетска идеја; Пренџова го поместува подот на цврстото розово гето и ПСТ-жената и создава еден лизгав и отворен простор за еднаквост преку ГЛАС-от на писателката.</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Д-р Марина Мијаковска</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3903} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/DSC_6646-725x1024.jpg\" alt=\"\" class=\"wp-image-3903\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3905} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/poster.png\" alt=\"\" class=\"wp-image-3905\"/></figure>\n<!-- /wp:image -->','ПРОМОЦИЈА НА КНИГА – ШШШ! ИНТИМИСТИЧКА ВАЈБЕР ПОЕЗИЈА 27.09.2019 (ПЕТОК) ФОАЈЕ 18ч.','','publish','open','open','','%d0%bf%d1%80%d0%be%d0%bc%d0%be%d1%86%d0%b8%d1%98%d0%b0-%d0%bd%d0%b0-%d0%ba%d0%bd%d0%b8%d0%b3%d0%b0-%d1%88%d1%88%d1%88-%d0%b8%d0%bd%d1%82%d0%b8%d0%bc%d0%b8%d1%81%d1%82%d0%b8%d1%87%d0%ba','','','2026-02-14 00:03:35','2026-02-14 00:03:35','',0,'https://user17.delovna.finki.ukim.mk/?p=1204',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1205,1,'2026-02-14 00:03:02','2026-02-14 00:03:02','','image_2026-02-14_010302012','','inherit','open','closed','','image_2026-02-14_010302012','','','2026-02-14 00:03:02','2026-02-14 00:03:02','',1204,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/image_2026-02-14_010302012.png',0,'attachment','image/png',0);
INSERT INTO `wp_posts` VALUES (1206,1,'2026-02-14 00:03:35','2026-02-14 00:03:35','<!-- wp:paragraph -->\n<p>19/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>“ШШШ! Интимистичка Вајбер поезија“ на поетесата Елена Пренџова е најновото поетско остварување за кое таа е носителка на наградата „Јован Котески“ за 2018 година.</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>&nbsp;&nbsp;&nbsp; Поетесата во оваа најнова стихозбирка ги отвора железните порти на сопствените интимни соби. Насловот на стихозбирката е заводлив, бидејќи низ него испарува женскиот здив и ономатопејата „Шшш!“ како метафора за женскиот молк или цензурата на женскиот глас. Насловот е прва котва што ја разгатнува табу-темата да се говори низ женска оптика за интимниот свет и сексуалното искуство на жената. Интересно е што поетесата е во дослух со ерата на технологијата, а поезијата е разголување преку новата апликација вајбер како најпогодна за секојдневна комуникација на поголема просторна далечина.</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>     „ШШШ! Интимистичка вајбер поезија“ на Елена Пренџова е храбро поетско женско писмо кое заведува, намамува и преку субверзивниот женскиот глас носи општествени промени. Тоа е крик за женска телесна слобода, а воедно и поетска слобода за ludens преку јазикот и пишувањето. Со оваа одлично компонирана, стилски конструирана поетска идеја; Пренџова го поместува подот на цврстото розово гето и ПСТ-жената и создава еден лизгав и отворен простор за еднаквост преку ГЛАС-от на писателката.</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Д-р Марина Мијаковска</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3903} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/DSC_6646-725x1024.jpg\" alt=\"\" class=\"wp-image-3903\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3905} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/poster.png\" alt=\"\" class=\"wp-image-3905\"/></figure>\n<!-- /wp:image -->','ПРОМОЦИЈА НА КНИГА – ШШШ! ИНТИМИСТИЧКА ВАЈБЕР ПОЕЗИЈА 27.09.2019 (ПЕТОК) ФОАЈЕ 18ч.','','inherit','closed','closed','','1204-revision-v1','','','2026-02-14 00:03:35','2026-02-14 00:03:35','',1204,'https://user17.delovna.finki.ukim.mk/?p=1206',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1207,1,'2026-02-14 00:04:23','2026-02-14 00:04:23','<!-- wp:paragraph -->\n<p>19/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">“Shhh! Intimist Viber Poetry” by poet Elena Prendžova is her latest poetry collection, for which she received the “Jovan Koteski” Award for 2018.<br>In this collection, the poet opens the iron gates of her own intimate rooms. The title itself is suggestive — the onomatopoeic “Shhh!” acts as a metaphor for female silence and censorship of the female voice. Through a woman’s perspective, the book addresses intimacy and female sexual experience as a once-taboo subject.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The poetry is connected with the technology era, using Viber — a modern everyday communication tool — as a symbolic and expressive medium. The collection represents a bold female poetic voice that challenges norms and calls for both bodily and artistic freedom through language and writing.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Д-р Марина Мијаковска</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3903} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/DSC_6646-725x1024.jpg\" alt=\"\" class=\"wp-image-3903\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3905} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/poster.png\" alt=\"\" class=\"wp-image-3905\"/></figure>\n<!-- /wp:image -->','BOOK PROMOTION – “SHHH! INTIMIST VIBER POETRY”27.09.2019 (FRIDAY) – FOYER – 6:00 PM','','publish','open','open','','book-promotion-shhh-intimist-viber-poetry27-09-2019-friday-foyer-600-pm','','','2026-02-14 00:04:23','2026-02-14 00:04:23','',0,'https://user17.delovna.finki.ukim.mk/?p=1207',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1208,1,'2026-02-14 00:04:23','2026-02-14 00:04:23','<!-- wp:paragraph -->\n<p>19/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">“Shhh! Intimist Viber Poetry” by poet Elena Prendžova is her latest poetry collection, for which she received the “Jovan Koteski” Award for 2018.<br>In this collection, the poet opens the iron gates of her own intimate rooms. The title itself is suggestive — the onomatopoeic “Shhh!” acts as a metaphor for female silence and censorship of the female voice. Through a woman’s perspective, the book addresses intimacy and female sexual experience as a once-taboo subject.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The poetry is connected with the technology era, using Viber — a modern everyday communication tool — as a symbolic and expressive medium. The collection represents a bold female poetic voice that challenges norms and calls for both bodily and artistic freedom through language and writing.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Д-р Марина Мијаковска</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3903} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/DSC_6646-725x1024.jpg\" alt=\"\" class=\"wp-image-3903\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3905} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/poster.png\" alt=\"\" class=\"wp-image-3905\"/></figure>\n<!-- /wp:image -->','BOOK PROMOTION – “SHHH! INTIMIST VIBER POETRY”27.09.2019 (FRIDAY) – FOYER – 6:00 PM','','inherit','closed','closed','','1207-revision-v1','','','2026-02-14 00:04:23','2026-02-14 00:04:23','',1207,'https://user17.delovna.finki.ukim.mk/?p=1208',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1209,1,'2026-02-14 00:05:02','2026-02-14 00:05:02','<!-- wp:paragraph -->\n<p>15/10/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/%D0%9B%D0%98%D0%A2%D0%95%D0%A0%D0%90%D0%A2%D0%A3%D0%A0%D0%95%D0%9D-%D0%9A%D0%9E%D0%9D%D0%9A%D0%A3%D0%A0%D0%A1-2019.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>НУЦК „ТРАЈКО ПРОКОПИЕВ“ КУМАНОВО ПО ПОВОД 11 НОЕМВРИ – ДЕН НА ГРАДОТ КУМАНОВО РАСПИШУВА:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ЛИТЕРАТУРЕН КОНКУРС НА ТЕМА „ГРАД ПО ВАША МЕРКА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Конкурсот е наменет за учениците од основните училишта.&nbsp;Учесниците треба да ги достават своите творби (поезија и проза) во еден примерок, под шифра (заедно со творбата на посебен лист да бидат наведени името и презимето на авторот, називот на училиштето, името и презимето на менторот и тел. број за контакт) на следнава адреса: Плоштад Маршал Тито бр.3 Куманово или во просториите на Центарот за култура „Трајко Прокопиев“, со назнака за Литературен конкурс на тема „Град по ваша мерка“. Творбите да бидат оригинални и автентични. Со учеството на конкурсот, учесниците прифаќаат испратената творба да биде објавена во Зборник што ќе го подготви и издаде организаторот.<br>Целта на конкурсот е поттикнување на младите творци да творат, да ги изразат своите видувања, креативноста, доживувањата и да дадат своја слика за градот. Тоа ќе овозможи нашите млади творци да го промовираат богатството на нашиот град во културно-уметничка смисла, како и да се следат/ слушнат&nbsp; прогресивните и иновативните идеии на младите умови.<br>Литературниот конкурс е со награден карактер. За најуспешните ќе бидат доделени награди, дипломи, пофалници и благодарници. Комисијата го задржува правото да не ги разгледува творбите што заговараат насилство, нетолеранција и дискриминација.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Конкурсот трае од 15.10 до 01.11.2019 година.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Завршната манифестација ќе биде на 08.11.2019 година (петок) во 12 ч. во просториите на Центарот за култура „Трајко Прокопиев“ Куманово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>IKQK “TRAJKO PROKOPIEV” KUMANOVË ME RASTIN E 11 NËNTORIT – DITA E QYTETIT TË KUMANOVËS SHPALL: KONKURS LETRAR ME TEMËN “QYTETI SIPAS DËSHIRËS SUAJ ”<br>Konkursi zgjat nga 15.10 deri më 01.11. 2019.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Konkursi është i dedikuar për nxënësit e shkollave fillore. Pjesëmarrësit duhet të dorëzojnë punimet e tyre (poezi dhe prozë) në një mostër, sipas kodit (së bashku me krijimin e një fletë të veçantë të jetë emri dhe mbiemri, emri i shkollës, emri i mentorit dhe tel. numri i kontaktit) në adresën: Marshal Tito Nr.3 Kumanovë ose në Qendrën e kulturës “Trajko Prokopiev” i emëruar konkursi letrar “Qyteti sipas dëshirës suaj”. Punimet të jenë origjinale dhe autentike. Me marjen pjesë në konkurs, pjesmarrësit pranojnë që punimet tʾju publikohen në Koleksionim që do ta përgatit dhe do ta jap organizatori.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Qëllimi i konkursit është të inkurajojë artistët e rinj për të krijuar, për të shprehur pikëpamjet e tyre, kreativitetin, përvojat dhe të japin imazhin e tyre për qytetin. Kjo do t’i mundësojë krijuesit tanë të rinj të promovojnë pasurinë e qytetit tonë në një kuptim kulturor dhe artistik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Konkursi letrar është me karakter shpërblyes. Më të suksesshmit do t’u jepen çmime, diploma dhe ҫertifikata vlersimi. Komisioni rezervon të drejtën të mos shqyrtojë veprat që promovojnë dhunën, jotolerancën dhe diskriminimin.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Shfaqja përfundimtare do të jetë më 08.11.2019 (e premte) në ora 12.00. në ambientet e Qendrës Kulturore “Trajko Prokopiev” në Kumanovë.</p>\n<!-- /wp:paragraph -->','ЛИТЕРАТУРЕН КОНКУРС – НУЦК „ТРАЈКО ПРОКОПИЕВ“ КУМАНОВО ПО ПОВОД 11 НОЕМВРИ – ДЕН НА ГРАДОТ КУМАНОВО РАСПИШУВА: ЛИТЕРАТУРЕН КОНКУРС НА ТЕМА „ГРАД ПО ВАША МЕРКА“','','publish','open','open','','%d0%bb%d0%b8%d1%82%d0%b5%d1%80%d0%b0%d1%82%d1%83%d1%80%d0%b5%d0%bd-%d0%ba%d0%be%d0%bd%d0%ba%d1%83%d1%80%d1%81-%d0%bd%d1%83%d1%86%d0%ba-%d1%82%d1%80%d0%b0%d1%98%d0%ba%d0%be-%d0%bf','','','2026-02-14 00:05:03','2026-02-14 00:05:03','',0,'https://user17.delovna.finki.ukim.mk/?p=1209',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1210,1,'2026-02-14 00:04:40','2026-02-14 00:04:40','','image_2026-02-14_010440309','','inherit','open','closed','','image_2026-02-14_010440309','','','2026-02-14 00:04:40','2026-02-14 00:04:40','',1209,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/image_2026-02-14_010440309.png',0,'attachment','image/png',0);
INSERT INTO `wp_posts` VALUES (1211,1,'2026-02-14 00:05:02','2026-02-14 00:05:02','<!-- wp:paragraph -->\n<p>15/10/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/%D0%9B%D0%98%D0%A2%D0%95%D0%A0%D0%90%D0%A2%D0%A3%D0%A0%D0%95%D0%9D-%D0%9A%D0%9E%D0%9D%D0%9A%D0%A3%D0%A0%D0%A1-2019.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>НУЦК „ТРАЈКО ПРОКОПИЕВ“ КУМАНОВО ПО ПОВОД 11 НОЕМВРИ – ДЕН НА ГРАДОТ КУМАНОВО РАСПИШУВА:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ЛИТЕРАТУРЕН КОНКУРС НА ТЕМА „ГРАД ПО ВАША МЕРКА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Конкурсот е наменет за учениците од основните училишта.&nbsp;Учесниците треба да ги достават своите творби (поезија и проза) во еден примерок, под шифра (заедно со творбата на посебен лист да бидат наведени името и презимето на авторот, називот на училиштето, името и презимето на менторот и тел. број за контакт) на следнава адреса: Плоштад Маршал Тито бр.3 Куманово или во просториите на Центарот за култура „Трајко Прокопиев“, со назнака за Литературен конкурс на тема „Град по ваша мерка“. Творбите да бидат оригинални и автентични. Со учеството на конкурсот, учесниците прифаќаат испратената творба да биде објавена во Зборник што ќе го подготви и издаде организаторот.<br>Целта на конкурсот е поттикнување на младите творци да творат, да ги изразат своите видувања, креативноста, доживувањата и да дадат своја слика за градот. Тоа ќе овозможи нашите млади творци да го промовираат богатството на нашиот град во културно-уметничка смисла, како и да се следат/ слушнат&nbsp; прогресивните и иновативните идеии на младите умови.<br>Литературниот конкурс е со награден карактер. За најуспешните ќе бидат доделени награди, дипломи, пофалници и благодарници. Комисијата го задржува правото да не ги разгледува творбите што заговараат насилство, нетолеранција и дискриминација.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Конкурсот трае од 15.10 до 01.11.2019 година.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Завршната манифестација ќе биде на 08.11.2019 година (петок) во 12 ч. во просториите на Центарот за култура „Трајко Прокопиев“ Куманово.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>IKQK “TRAJKO PROKOPIEV” KUMANOVË ME RASTIN E 11 NËNTORIT – DITA E QYTETIT TË KUMANOVËS SHPALL: KONKURS LETRAR ME TEMËN “QYTETI SIPAS DËSHIRËS SUAJ ”<br>Konkursi zgjat nga 15.10 deri më 01.11. 2019.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Konkursi është i dedikuar për nxënësit e shkollave fillore. Pjesëmarrësit duhet të dorëzojnë punimet e tyre (poezi dhe prozë) në një mostër, sipas kodit (së bashku me krijimin e një fletë të veçantë të jetë emri dhe mbiemri, emri i shkollës, emri i mentorit dhe tel. numri i kontaktit) në adresën: Marshal Tito Nr.3 Kumanovë ose në Qendrën e kulturës “Trajko Prokopiev” i emëruar konkursi letrar “Qyteti sipas dëshirës suaj”. Punimet të jenë origjinale dhe autentike. Me marjen pjesë në konkurs, pjesmarrësit pranojnë që punimet tʾju publikohen në Koleksionim që do ta përgatit dhe do ta jap organizatori.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Qëllimi i konkursit është të inkurajojë artistët e rinj për të krijuar, për të shprehur pikëpamjet e tyre, kreativitetin, përvojat dhe të japin imazhin e tyre për qytetin. Kjo do t’i mundësojë krijuesit tanë të rinj të promovojnë pasurinë e qytetit tonë në një kuptim kulturor dhe artistik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Konkursi letrar është me karakter shpërblyes. Më të suksesshmit do t’u jepen çmime, diploma dhe ҫertifikata vlersimi. Komisioni rezervon të drejtën të mos shqyrtojë veprat që promovojnë dhunën, jotolerancën dhe diskriminimin.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Shfaqja përfundimtare do të jetë më 08.11.2019 (e premte) në ora 12.00. në ambientet e Qendrës Kulturore “Trajko Prokopiev” në Kumanovë.</p>\n<!-- /wp:paragraph -->','ЛИТЕРАТУРЕН КОНКУРС – НУЦК „ТРАЈКО ПРОКОПИЕВ“ КУМАНОВО ПО ПОВОД 11 НОЕМВРИ – ДЕН НА ГРАДОТ КУМАНОВО РАСПИШУВА: ЛИТЕРАТУРЕН КОНКУРС НА ТЕМА „ГРАД ПО ВАША МЕРКА“','','inherit','closed','closed','','1209-revision-v1','','','2026-02-14 00:05:02','2026-02-14 00:05:02','',1209,'https://user17.delovna.finki.ukim.mk/?p=1211',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1212,1,'2026-02-14 00:05:27','2026-02-14 00:05:27','<!-- wp:paragraph -->\n<p>15/10/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/%D0%9B%D0%98%D0%A2%D0%95%D0%A0%D0%90%D0%A2%D0%A3%D0%A0%D0%95%D0%9D-%D0%9A%D0%9E%D0%9D%D0%9A%D0%A3%D0%A0%D0%A1-2019.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>The National Center for Culture “Trajko Prokopiev” Kumanovo announces a <strong>literary competition</strong> dedicated to elementary school students.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Participants should submit their works (poetry or prose) in one copy, under a code name. In addition to the coded work, a separate sheet should include: the author’s full name, school name, mentor’s name, and a contact phone number. Submissions should be sent to: Marshal Tito Square No. 3, Kumanovo, or delivered in person at the Center for Culture “Trajko Prokopiev”, marked for the literary competition “A City of Your Own Measure.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>All works must be original and authentic. By participating, authors agree that their work may be published in a collection prepared and issued by the organizer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The goal of the competition is to encourage young creators to express their views, creativity, and experiences, and to present their own vision of the city. The competition is award-based. The best works will receive prizes, diplomas, certificates, and acknowledgments. The commission reserves the right to exclude works that promote violence, intolerance, or discrimination.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Competition period:</strong> 15.10 – 01.11.2019<br><strong>Final event:</strong> 08.11.2019 (Friday) at 12:00, Center for Culture “Trajko Prokopiev”, Kumanovo.</p>\n<!-- /wp:paragraph -->','LITERARY COMPETITION – NCC “Trajko Prokopiev” Kumanovo on the Occasion of November 11 – Day of the City of KumanovoTopic: “A City of Your Own Measure”','','publish','open','open','','literary-competition-ncc-trajko-prokopiev-kumanovo-on-the-occasion-of-november-11-day-of-the-city-of-kumanovotopic-a-city-of-your-own-measure','','','2026-02-14 00:05:28','2026-02-14 00:05:28','',0,'https://user17.delovna.finki.ukim.mk/?p=1212',0,'post','',0);
