INSERT INTO `wp_posts` VALUES (1217,1,'2026-02-14 00:06:23','2026-02-14 00:06:23','<!-- wp:paragraph -->\n<p>16/10/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/%D0%9B%D0%98%D0%A2%D0%95%D0%A0-%D0%9F%D0%9E%D0%95%D0%A2%D0%A1%D0%9A%D0%90-%D0%92%D0%95%D0%A7%D0%95%D0%A0-2019.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->','Literary–Musical Evening – 24.10.2019 (Thursday), Small Hall, 18:30','','publish','open','open','','literary-musical-evening-24-10-2019-thursday-small-hall-1830','','','2026-02-14 00:06:24','2026-02-14 00:06:24','',0,'https://user17.delovna.finki.ukim.mk/?p=1217',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1218,1,'2026-02-14 00:06:23','2026-02-14 00:06:23','<!-- wp:paragraph -->\n<p>16/10/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/%D0%9B%D0%98%D0%A2%D0%95%D0%A0-%D0%9F%D0%9E%D0%95%D0%A2%D0%A1%D0%9A%D0%90-%D0%92%D0%95%D0%A7%D0%95%D0%A0-2019.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->','Literary–Musical Evening – 24.10.2019 (Thursday), Small Hall, 18:30','','inherit','closed','closed','','1217-revision-v1','','','2026-02-14 00:06:23','2026-02-14 00:06:23','',1217,'https://user17.delovna.finki.ukim.mk/?p=1218',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1219,1,'2026-02-14 00:07:02','2026-02-14 00:07:02','<!-- wp:paragraph -->\n<p>16/10/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/%D0%BF%D0%BE%D0%BA%D0%B0%D0%BD%D0%B0-%D0%92%D0%BB%D0%B0%D1%82%D0%BA%D0%BE.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Во четврток на 24 октомври во Центарот за култура Трајко Прокопиев во Куманово со почеток во 20:00 часот ќе биде отворена изложбата на фотографии Прага интима&nbsp; на фотографот Влатко Деков.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„Прага интима“ е личен, интимен портрет на еден од најубавите градови во светот, Прага. На трагите на она што го работеше познатиот чешки фотограф, Јосеф Судек, „Прага интима“ ги доловува скриените, вонвременски делови на градот, најчесто без присуство на луѓе. Проектот е работен 2 години, период во кој авторот ја посетува Прага 5 пати, живее и ја фотографира&nbsp; вкупно 44 денови, во текот на летниот и во зимскиот период.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ќе бидат изложени 34 црно бели фотографии. Воедно ќе биде промовирана и фото книга со истото име како и изложбата.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Изложбата е финансирана од Министерството за култура на Република Северна Македонија, а книгата е во издание на Издавачката куќа ИЛИ ИЛИ од Скопје.</p>\n<!-- /wp:paragraph -->','ИЗЛОЖБА НА ФОТОГРАФИИ и ПРОМОЦИЈА НА КНИГА: “ПРАГА ИНТИМА“ од ВЛАТКО ДЕКОВ 24.10.2019 (четврток) ИЗЛОЖБЕН САЛОН 20ч.','','publish','open','open','','%d0%b8%d0%b7%d0%bb%d0%be%d0%b6%d0%b1%d0%b0-%d0%bd%d0%b0-%d1%84%d0%be%d1%82%d0%be%d0%b3%d1%80%d0%b0%d1%84%d0%b8%d0%b8-%d0%b8-%d0%bf%d1%80%d0%be%d0%bc%d0%be%d1%86%d0%b8%d1%98%d0%b0-%d0%bd%d0%b0-%d0%ba','','','2026-02-14 00:07:02','2026-02-14 00:07:02','',0,'https://user17.delovna.finki.ukim.mk/?p=1219',0,'post','',0);
