INSERT INTO `wp_posts` VALUES (1228,1,'2026-02-14 00:08:16','2026-02-14 00:08:16','<!-- wp:paragraph -->\n<p>19/10/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/sinisa-stankovic-plakat.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4001} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/10/sinisa-stankovic-plakat-1024x712.jpg\" alt=\"\" class=\"wp-image-4001\"/></figure>\n<!-- /wp:image -->','“NEIGHBORHOOD STORIES (1+2)” BY SINIŠA STANKOVIĆ – 29.10.2019 (Tuesday), Foyer, 18:30','','inherit','closed','closed','','1227-revision-v1','','','2026-02-14 00:08:16','2026-02-14 00:08:16','',1227,'https://user17.delovna.finki.ukim.mk/?p=1228',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1229,1,'2026-02-14 00:08:47','2026-02-14 00:08:47','<!-- wp:paragraph -->\n<p>26/11/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/11/milko-bojkovski-PLAKAT.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; „Хиени во градот“ од Милко Бојковски</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Поетскиот ракопис на Милко Бојковски „Хиени во градот“ претставува компјутерски изработен текст. Се работи за нова поетска збирка, на млад и талентиран македонски поет кој веќе објавувал раскази во Маргина, песни БКГ и на српскиот сајт за поезија Поезин.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Во своите стихови младиот Бојковски е предизвикувачки отворен,&nbsp; по малку парадоксален, но младешки оргинален. Тој развива луциден и ироничен однос кон животот и кон литературата. Структурата на неговите песни покажува возбудлив поетски модел кој не е само референцијален, туку и постпоетичен. Ракописот на Милко Бојковски е полн со иронија. Тој им нуди слобода на зборовите и на формата градејќи го препознатливиот посмодернистички концепт на светот, по урнек, можеби, на веќе докажаните поети од помладата македонска генерација. Бојковски негува синкретичен јазик, користи урбана лексика и младешки жаргон.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Акцентот го ставил врз својата најинтимна и најрефлексивна сфера.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>&nbsp;&nbsp;&nbsp;&nbsp; Ангелина Бановиќ-Марковска</p>\n<!-- /wp:paragraph -->','ПРОМОЦИЈА НА КНИГА – “ХИЕНИ ВО ГРАДОТ“ ОД МИЛКО БОЈКОВСКИ – 29.11.2019 (ПЕТОК) МАЛА САЛА 19.00ч.','','publish','open','open','','%d0%bf%d1%80%d0%be%d0%bc%d0%be%d1%86%d0%b8%d1%98%d0%b0-%d0%bd%d0%b0-%d0%ba%d0%bd%d0%b8%d0%b3%d0%b0-%d1%85%d0%b8%d0%b5%d0%bd%d0%b8-%d0%b2%d0%be-%d0%b3%d1%80%d0%b0%d0%b4%d0%be%d1%82','','','2026-02-14 00:08:48','2026-02-14 00:08:48','',0,'https://user17.delovna.finki.ukim.mk/?p=1229',0,'post','',0);
