INSERT INTO `wp_posts` VALUES (1237,1,'2026-02-14 00:10:25','2026-02-14 00:10:25','<!-- wp:paragraph -->\n<p>02/12/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/%D0%BA%D0%BE%D0%BD%D0%BA%D1%83%D1%80%D1%81.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>      NUCC “Trajko Prokopiev” Kumanovo, on the occasion of the New Year holidays, announces a:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>LITERARY COMPETITION ON THE THEME “NEW YEAR’S WISH”</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The competition is intended for primary school students. Participants should submit their works (poetry or prose) in one copy, under a code name. On a separate sheet enclosed with the work, they must include: the author’s full name, school name, mentor’s full name, and a contact phone number.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Submissions should be sent to the following address:<br>Marshal Tito Square no. 3, Kumanovo,<br>or delivered in person at the Cultural Center “Trajko Prokopiev,”<br>marked: <em>For the Literary Competition on the theme “New Year’s Wish.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Works must be original and authentic. By participating, contestants agree that their submitted work may be published in a collection prepared and issued by the organizer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The competition has an award character. The most successful entries will receive prizes, diplomas, commendations, and certificates of appreciation. The committee reserves the right not to consider works that promote violence, intolerance, or discrimination.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Competition period:</strong> 03.12 – 20.12.2019<br><strong>Final event:</strong> 25.12.2019 (Wednesday) at 12:00,<br>at the Cultural Center “Trajko Prokopiev” Kumanovo.</p>\n<!-- /wp:paragraph -->','LITERARY COMPETITION ON THE THEME “NEW YEAR’S WISH” – APPLICATION PERIOD: 03–20.12.2019','','publish','open','open','','literary-competition-on-the-theme-new-years-wish-application-period-03-20-12-2019','','','2026-02-14 00:10:26','2026-02-14 00:10:26','',0,'https://user17.delovna.finki.ukim.mk/?p=1237',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1238,1,'2026-02-14 00:10:25','2026-02-14 00:10:25','<!-- wp:paragraph -->\n<p>02/12/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/%D0%BA%D0%BE%D0%BD%D0%BA%D1%83%D1%80%D1%81.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>      NUCC “Trajko Prokopiev” Kumanovo, on the occasion of the New Year holidays, announces a:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>LITERARY COMPETITION ON THE THEME “NEW YEAR’S WISH”</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The competition is intended for primary school students. Participants should submit their works (poetry or prose) in one copy, under a code name. On a separate sheet enclosed with the work, they must include: the author’s full name, school name, mentor’s full name, and a contact phone number.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Submissions should be sent to the following address:<br>Marshal Tito Square no. 3, Kumanovo,<br>or delivered in person at the Cultural Center “Trajko Prokopiev,”<br>marked: <em>For the Literary Competition on the theme “New Year’s Wish.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Works must be original and authentic. By participating, contestants agree that their submitted work may be published in a collection prepared and issued by the organizer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The competition has an award character. The most successful entries will receive prizes, diplomas, commendations, and certificates of appreciation. The committee reserves the right not to consider works that promote violence, intolerance, or discrimination.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Competition period:</strong> 03.12 – 20.12.2019<br><strong>Final event:</strong> 25.12.2019 (Wednesday) at 12:00,<br>at the Cultural Center “Trajko Prokopiev” Kumanovo.</p>\n<!-- /wp:paragraph -->','LITERARY COMPETITION ON THE THEME “NEW YEAR’S WISH” – APPLICATION PERIOD: 03–20.12.2019','','inherit','closed','closed','','1237-revision-v1','','','2026-02-14 00:10:25','2026-02-14 00:10:25','',1237,'https://user17.delovna.finki.ukim.mk/?p=1238',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1239,1,'2026-02-14 00:11:02','2026-02-14 00:11:02','<!-- wp:paragraph -->\n<p>27/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/%D0%9D%D0%90%D0%94%D0%90-%D0%9C%D0%98%D0%A5%D0%90%D0%88%D0%9B%D0%9E%D0%92%D0%90-%D0%BF%D0%BB.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->','ПОЕТСКО-МУЗИЧКА ВЕЧЕР “ИЛИНДЕНСКИ СЕКАВИЦИ 2020“ 30.07.2020 (ЧЕТВРТОК) ПЛАТО НА ЦЕНТАР ПОЧ. 19ч.','','publish','open','open','','%d0%bf%d0%be%d0%b5%d1%82%d1%81%d0%ba%d0%be-%d0%bc%d1%83%d0%b7%d0%b8%d1%87%d0%ba%d0%b0-%d0%b2%d0%b5%d1%87%d0%b5%d1%80-%d0%b8%d0%bb%d0%b8%d0%bd%d0%b4%d0%b5%d0%bd%d1%81%d0%ba%d0%b8-%d1%81%d0%b5-2','','','2026-02-14 00:11:02','2026-02-14 00:11:02','',0,'https://user17.delovna.finki.ukim.mk/?p=1239',0,'post','',0);
