INSERT INTO `wp_posts` VALUES (1242,1,'2026-02-14 00:11:29','2026-02-14 00:11:29','<!-- wp:paragraph -->\n<p>27/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/%D0%9D%D0%90%D0%94%D0%90-%D0%9C%D0%98%D0%A5%D0%90%D0%88%D0%9B%D0%9E%D0%92%D0%90-%D0%BF%D0%BB.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->','POETRY–MUSIC EVENING “ILINDEN LIGHTNINGS 2020”30.07.2020 (THURSDAY) – Center Plateau – Start: 19:00','','publish','open','open','','poetry-music-evening-ilinden-lightnings-202030-07-2020-thursday-center-plateau-start-1900','','','2026-02-14 00:11:29','2026-02-14 00:11:29','',0,'https://user17.delovna.finki.ukim.mk/?p=1242',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1243,1,'2026-02-14 00:11:29','2026-02-14 00:11:29','<!-- wp:paragraph -->\n<p>27/07/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/07/%D0%9D%D0%90%D0%94%D0%90-%D0%9C%D0%98%D0%A5%D0%90%D0%88%D0%9B%D0%9E%D0%92%D0%90-%D0%BF%D0%BB.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->','POETRY–MUSIC EVENING “ILINDEN LIGHTNINGS 2020”30.07.2020 (THURSDAY) – Center Plateau – Start: 19:00','','inherit','closed','closed','','1242-revision-v1','','','2026-02-14 00:11:29','2026-02-14 00:11:29','',1242,'https://user17.delovna.finki.ukim.mk/?p=1243',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1244,1,'2026-02-14 00:12:25','2026-02-14 00:12:25','<!-- wp:paragraph -->\n<p>15/09/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/09/promocija-svetlana.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Промоција на книга</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“МОЛЧИ И ТАНЦУВАЈ“</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Од СВЕТЛАНА АНТИЌ – ЈОВЧЕВСКА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>21.09.2020 (ПОНЕДЕЛНИК)&nbsp; ТЕАТАР КУМАНОВО&nbsp; 20ч.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ПРОМОТОР: Звездан Георгиевски, новинар и писател</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Извадоци од книгата ќе чита: Сања Русеска, актер<br>Водител: Никица Јанковски, актер</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Светлана Антиќ-Јовчевска</strong>&nbsp;(1960), новинар од Куманово.<br>Фрагментарниот роман „Молчи и танцувај“ е нејзината четврта книга. Првата публицистика „Патот на вистината (сведоштва за воениот конфликт и егзодусот во Кумановско, 2001)“ беше објавена во 2004-та, збирката раскази „13“ во 2005-та, а со финансиска поддршка од Министерството за култура на РМ, современиот роман „Ликот од огледалото“ во 2009-та година. Како новинар за професионалното известување од завојуваните подрачја во 2001-та година Редакцијата „Вечер“ и ја додели специјалната годишна награда на весникот. Во 2015-та година Советот на Општината Куманово и го додели највисокото општинско признание Ноемвриска награда за долгогодишна работа како новинар и борец за професионално новинарство и напишаните и објавени три книги од различни жанрови.<br>Антиќ-Јовчевска е само една од оние кои пишуваат од потреба и од зависност. Таа пишува за да живее. И живее за да пишува.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„…Иако книгата е пишувана во исклучива јас-форма, таа е суштински универзална и во неа читателот, особено овој од овие простори, но и пошироко, мошне лесно се идентификува, тој ги препознава сопствените стравови и надежи, а на места и сопствените мисли и ставови. Затоа оваа книга може да се нарече и книга за мудроста на живеењето…“<br>Ѕвездан Георгиевски, новинар и писател</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Рецензија</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>За животот и неговото менување и минување</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Зошто треба да се прочита ова четиво на Светлана Антиќ – Јовчевска? Ова не е роман, барем не во онаа класична смисла на којашто сме навикнале. Не е ниту автобиографија, ни мемоарски записи. Не се ова есеи или раскази. Кога веќе би морале да ја ставиме оваа книга во некаква фиока, како што тоа вообичаено се прави, тогаш ќе кажеме дека станува збор за роман, за автобиографија, за мемоарски записи, за есеи и раскази. Со други зборови, Антиќ – Јовчевска успеала да воспостави еден хибриден жанр, со којшто прилично мајсторски владее и низ којшто со леснотија го води читателот низ темите што сака да ги наметне.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Значи, Светлана Антиќ – Јовчевска го задржува своето внимание и вниманието на читателот врз навидум ситните нешта, катадневните средби, вообичаените предмети и пејзажи што влегуваат, остануваат или поминуваат низ нејзиниот секојдневен животен пат. Се разбира дека овие крајпатни знаци, често незабележливи за човековиот фокус, не се главниот магистрален пат, но Антиќ – Јовчевска многу добро знае дека токму тие ни ја покажуваат насоката на движење. Всушност, тоа се оние ситни и не толку ситни нешта што ни го означуваат животот и нѐ одредуваат како личности. Тоа се оние работи што вообичаено ги нарекуваме животни искуства.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со други зборови, авторката во оваа своја книга, токму преку крајпатните знаци, всушност се занимава со големите теми на нашите животи: со кршливоста, но и цврстината на животот и човекот; со злобата и добрината; со љубовта и омразата (особено за љубовта); со прагмата и теоријата на човековото егзистирање; со духовното и земското; конечно и со смртта, повеќе како нераскинлив дел од животот, отколку како негов неминовен крај… Со еден збор, Светлана Антиќ – Јовчевска ја допира најважната тема на секоја литература и на секоја филозофија – смислата на животот!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>А тоа, веќе знаете, не е ни малку лесно. Овие теми бараат многу „зошто?“ и многу „затоа!“, како што вели авторката. Таа, како долгогодишна новинарка, со огромно наталожено и акумулирано животно и професионално искуство, ги поставува вистинските прашања на вистинските места и, се разбира, ги пронаоѓа и соодветните одговори. Некои од овие одговори можеби и нема да му се допаднат на читателот, но Антиќ -Јовчевска очигледно нема намера да прави компромиси и отстапки. Вистината е единствената работа на овој свет што е вистинска и од неа нема отстапување.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Иако книгата е пишувана во исклучива јас-форма, таа е суштински универзална и во неа читателот, особено овој од овие простори, но и пошироко, мошне лесно се идентификува, тој ги препознава сопствените стравови и надежи, а на места и сопствените мисли и ставови. Затоа оваа книга може да се нарече и&nbsp;<strong>книга за мудроста на живеењето.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Иако книгата допира и до извесни религиски искуства, како начин за барање одговори на прашањата што нѐ мачат, Светлана Антиќ – Јовчевска не паѓа во стапицата на зададени одговори. Таа не ги прима работите „здраво за готово“, односно онака како што ни се зададени, туку напротив. Низ текстот провејува некоја дијалектичка нишка. Работите речиси никогаш не се онакви какви што изгледаат на прв поглед и тие никогаш или речиси никогаш не се непроменливи. Светлана Антиќ – Јовчевска, повторувам наспроти религиското и духовното искуство, не е фаталист и не се залажува со формата или формулата дека „работите се такви затоа што тоа е така“, туку токму спротивното – таа е активен чинител на промените во сопствениот живот, а со тоа и во менувањето на околината и пејзажот во којшто живее.&nbsp;<strong>Од некаква филозофска гледна точка, оваа книга покажува дека, наспроти сѐ, светот може и треба да се менува. Се разбира, само ако сме моќни да се менуваме самите себеси.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со оваа книга, Светлана Антиќ – Јовчевска сериозно и стамено ја промовира сопствената моќ да нѐ менува и нас, нејзините читатели. И тоа на подобро.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ете, затоа треба и мора да се прочита ова исклучително и невообичаено четиво.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Звездан Георгиевски</strong><strong>,</strong><strong>&nbsp;новинар и писател</strong></p>\n<!-- /wp:paragraph -->','ПРОМОЦИЈА НА КНИГА – МОЛЧИ И ТАНЦУВАЈ – СВЕТЛАНА АНТИЌ – ЈОВЧЕВСКА','','publish','open','open','','%d0%bf%d1%80%d0%be%d0%bc%d0%be%d1%86%d0%b8%d1%98%d0%b0-%d0%bd%d0%b0-%d0%ba%d0%bd%d0%b8%d0%b3%d0%b0-%d0%bc%d0%be%d0%bb%d1%87%d0%b8-%d0%b8-%d1%82%d0%b0%d0%bd%d1%86%d1%83%d0%b2%d0%b0%d1%98','','','2026-02-14 00:12:26','2026-02-14 00:12:26','',0,'https://user17.delovna.finki.ukim.mk/?p=1244',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1245,1,'2026-02-14 00:12:13','2026-02-14 00:12:13','','image_2026-02-14_011212584','','inherit','open','closed','','image_2026-02-14_011212584','','','2026-02-14 00:12:13','2026-02-14 00:12:13','',1244,'https://user17.delovna.finki.ukim.mk/wp-content/uploads/2026/02/image_2026-02-14_011212584.png',0,'attachment','image/png',0);
INSERT INTO `wp_posts` VALUES (1246,1,'2026-02-14 00:12:25','2026-02-14 00:12:25','<!-- wp:paragraph -->\n<p>15/09/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/09/promocija-svetlana.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Промоција на книга</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“МОЛЧИ И ТАНЦУВАЈ“</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Од СВЕТЛАНА АНТИЌ – ЈОВЧЕВСКА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>21.09.2020 (ПОНЕДЕЛНИК)&nbsp; ТЕАТАР КУМАНОВО&nbsp; 20ч.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ПРОМОТОР: Звездан Георгиевски, новинар и писател</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Извадоци од книгата ќе чита: Сања Русеска, актер<br>Водител: Никица Јанковски, актер</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Светлана Антиќ-Јовчевска</strong>&nbsp;(1960), новинар од Куманово.<br>Фрагментарниот роман „Молчи и танцувај“ е нејзината четврта книга. Првата публицистика „Патот на вистината (сведоштва за воениот конфликт и егзодусот во Кумановско, 2001)“ беше објавена во 2004-та, збирката раскази „13“ во 2005-та, а со финансиска поддршка од Министерството за култура на РМ, современиот роман „Ликот од огледалото“ во 2009-та година. Како новинар за професионалното известување од завојуваните подрачја во 2001-та година Редакцијата „Вечер“ и ја додели специјалната годишна награда на весникот. Во 2015-та година Советот на Општината Куманово и го додели највисокото општинско признание Ноемвриска награда за долгогодишна работа како новинар и борец за професионално новинарство и напишаните и објавени три книги од различни жанрови.<br>Антиќ-Јовчевска е само една од оние кои пишуваат од потреба и од зависност. Таа пишува за да живее. И живее за да пишува.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„…Иако книгата е пишувана во исклучива јас-форма, таа е суштински универзална и во неа читателот, особено овој од овие простори, но и пошироко, мошне лесно се идентификува, тој ги препознава сопствените стравови и надежи, а на места и сопствените мисли и ставови. Затоа оваа книга може да се нарече и книга за мудроста на живеењето…“<br>Ѕвездан Георгиевски, новинар и писател</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Рецензија</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>За животот и неговото менување и минување</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Зошто треба да се прочита ова четиво на Светлана Антиќ – Јовчевска? Ова не е роман, барем не во онаа класична смисла на којашто сме навикнале. Не е ниту автобиографија, ни мемоарски записи. Не се ова есеи или раскази. Кога веќе би морале да ја ставиме оваа книга во некаква фиока, како што тоа вообичаено се прави, тогаш ќе кажеме дека станува збор за роман, за автобиографија, за мемоарски записи, за есеи и раскази. Со други зборови, Антиќ – Јовчевска успеала да воспостави еден хибриден жанр, со којшто прилично мајсторски владее и низ којшто со леснотија го води читателот низ темите што сака да ги наметне.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Значи, Светлана Антиќ – Јовчевска го задржува своето внимание и вниманието на читателот врз навидум ситните нешта, катадневните средби, вообичаените предмети и пејзажи што влегуваат, остануваат или поминуваат низ нејзиниот секојдневен животен пат. Се разбира дека овие крајпатни знаци, често незабележливи за човековиот фокус, не се главниот магистрален пат, но Антиќ – Јовчевска многу добро знае дека токму тие ни ја покажуваат насоката на движење. Всушност, тоа се оние ситни и не толку ситни нешта што ни го означуваат животот и нѐ одредуваат како личности. Тоа се оние работи што вообичаено ги нарекуваме животни искуства.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со други зборови, авторката во оваа своја книга, токму преку крајпатните знаци, всушност се занимава со големите теми на нашите животи: со кршливоста, но и цврстината на животот и човекот; со злобата и добрината; со љубовта и омразата (особено за љубовта); со прагмата и теоријата на човековото егзистирање; со духовното и земското; конечно и со смртта, повеќе како нераскинлив дел од животот, отколку како негов неминовен крај… Со еден збор, Светлана Антиќ – Јовчевска ја допира најважната тема на секоја литература и на секоја филозофија – смислата на животот!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>А тоа, веќе знаете, не е ни малку лесно. Овие теми бараат многу „зошто?“ и многу „затоа!“, како што вели авторката. Таа, како долгогодишна новинарка, со огромно наталожено и акумулирано животно и професионално искуство, ги поставува вистинските прашања на вистинските места и, се разбира, ги пронаоѓа и соодветните одговори. Некои од овие одговори можеби и нема да му се допаднат на читателот, но Антиќ -Јовчевска очигледно нема намера да прави компромиси и отстапки. Вистината е единствената работа на овој свет што е вистинска и од неа нема отстапување.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Иако книгата е пишувана во исклучива јас-форма, таа е суштински универзална и во неа читателот, особено овој од овие простори, но и пошироко, мошне лесно се идентификува, тој ги препознава сопствените стравови и надежи, а на места и сопствените мисли и ставови. Затоа оваа книга може да се нарече и&nbsp;<strong>книга за мудроста на живеењето.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Иако книгата допира и до извесни религиски искуства, како начин за барање одговори на прашањата што нѐ мачат, Светлана Антиќ – Јовчевска не паѓа во стапицата на зададени одговори. Таа не ги прима работите „здраво за готово“, односно онака како што ни се зададени, туку напротив. Низ текстот провејува некоја дијалектичка нишка. Работите речиси никогаш не се онакви какви што изгледаат на прв поглед и тие никогаш или речиси никогаш не се непроменливи. Светлана Антиќ – Јовчевска, повторувам наспроти религиското и духовното искуство, не е фаталист и не се залажува со формата или формулата дека „работите се такви затоа што тоа е така“, туку токму спротивното – таа е активен чинител на промените во сопствениот живот, а со тоа и во менувањето на околината и пејзажот во којшто живее.&nbsp;<strong>Од некаква филозофска гледна точка, оваа книга покажува дека, наспроти сѐ, светот може и треба да се менува. Се разбира, само ако сме моќни да се менуваме самите себеси.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со оваа книга, Светлана Антиќ – Јовчевска сериозно и стамено ја промовира сопствената моќ да нѐ менува и нас, нејзините читатели. И тоа на подобро.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ете, затоа треба и мора да се прочита ова исклучително и невообичаено четиво.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Звездан Георгиевски</strong><strong>,</strong><strong>&nbsp;новинар и писател</strong></p>\n<!-- /wp:paragraph -->','ПРОМОЦИЈА НА КНИГА – МОЛЧИ И ТАНЦУВАЈ – СВЕТЛАНА АНТИЌ – ЈОВЧЕВСКА','','inherit','closed','closed','','1244-revision-v1','','','2026-02-14 00:12:25','2026-02-14 00:12:25','',1244,'https://user17.delovna.finki.ukim.mk/?p=1246',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1247,1,'2026-02-14 00:12:58','2026-02-14 00:12:58','<!-- wp:paragraph -->\n<p>15/09/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/09/promocija-svetlana.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Book promotion<br><strong>“BE SILENT AND DANCE”</strong><br>by <strong>Svetlana Antić–Jovchevska</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>21.09.2020 (MONDAY) – Theater Kumanovo – 20:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Promoter:</strong> Zvezdan Georgievski, journalist and writer<br><strong>Book excerpts read by:</strong> Sanja Ruseska, actor<br><strong>Host:</strong> Nikica Jankovski, actor</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Svetlana Antić–Jovchevska (1960) is a journalist from Kumanovo. The fragmentary novel <em>“Be Silent and Dance”</em> is her fourth book. Her first work of publicistic writing, <em>“The Path of Truth (testimonies about the military conflict and the exodus in the Kumanovo region, 2001)”</em> was published in 2004, followed by the short story collection <em>“13”</em> in 2005, and the contemporary novel <em>“The Face in the Mirror”</em> in 2009, published with support from the Ministry of Culture. For her professional reporting from conflict areas in 2001, the newsroom of the newspaper <em>Večer</em> awarded her a special annual prize. In 2015 she received the November Award of the Municipality of Kumanovo for her long-standing journalistic work and contribution to professional journalism and literature. She writes out of need and devotion — she writes to live and lives to write.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“…Although written entirely in the first-person voice, the book is essentially universal. Readers can easily recognize their own fears, hopes, thoughts, and attitudes in it. That is why this book can also be called a book about the wisdom of living…”<br>— Zvezdan Georgievski, journalist and writer</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Review – On Life and Its Change and Passing</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Why should this book by Svetlana Antić–Jovchevska be read? It is not a novel in the classical sense, nor a pure autobiography, memoir, essay collection, or short story book. If it must be placed in a category, it is all of these at once — a hybrid genre that the author skillfully controls, guiding the reader through meaningful life themes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She focuses on seemingly small, everyday moments, objects, encounters, and landscapes — the “roadside signs” of life that quietly define who we are. Through them she opens the major themes of human existence: fragility and strength, good and evil, love and hatred, spiritual and earthly life, and death as part of life rather than only its end. At its core, the book explores the meaning of life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Drawing from deep personal and professional experience, she asks the right questions and offers honest answers, without compromise. Truth is central and non-negotiable. Despite touches of religious and spiritual reflection, the author is not fatalistic — she insists that life and the world can change, if we are willing to change ourselves.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>With this book, Antić–Jovchevska strongly promotes literature’s power to transform the reader — for the better. That is why this distinctive and thoughtful work deserves to be read.</p>\n<!-- /wp:paragraph -->','BOOK PROMOTION – “BE SILENT AND DANCE” – SVETLANA ANTIĆ–JOVCHEVSKA','','publish','open','open','','book-promotion-be-silent-and-dance-svetlana-antic-jovchevska','','','2026-02-14 00:12:58','2026-02-14 00:12:58','',0,'https://user17.delovna.finki.ukim.mk/?p=1247',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1248,1,'2026-02-14 00:12:58','2026-02-14 00:12:58','<!-- wp:paragraph -->\n<p>15/09/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/09/promocija-svetlana.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Book promotion<br><strong>“BE SILENT AND DANCE”</strong><br>by <strong>Svetlana Antić–Jovchevska</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>21.09.2020 (MONDAY) – Theater Kumanovo – 20:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Promoter:</strong> Zvezdan Georgievski, journalist and writer<br><strong>Book excerpts read by:</strong> Sanja Ruseska, actor<br><strong>Host:</strong> Nikica Jankovski, actor</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Svetlana Antić–Jovchevska (1960) is a journalist from Kumanovo. The fragmentary novel <em>“Be Silent and Dance”</em> is her fourth book. Her first work of publicistic writing, <em>“The Path of Truth (testimonies about the military conflict and the exodus in the Kumanovo region, 2001)”</em> was published in 2004, followed by the short story collection <em>“13”</em> in 2005, and the contemporary novel <em>“The Face in the Mirror”</em> in 2009, published with support from the Ministry of Culture. For her professional reporting from conflict areas in 2001, the newsroom of the newspaper <em>Večer</em> awarded her a special annual prize. In 2015 she received the November Award of the Municipality of Kumanovo for her long-standing journalistic work and contribution to professional journalism and literature. She writes out of need and devotion — she writes to live and lives to write.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“…Although written entirely in the first-person voice, the book is essentially universal. Readers can easily recognize their own fears, hopes, thoughts, and attitudes in it. That is why this book can also be called a book about the wisdom of living…”<br>— Zvezdan Georgievski, journalist and writer</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Review – On Life and Its Change and Passing</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Why should this book by Svetlana Antić–Jovchevska be read? It is not a novel in the classical sense, nor a pure autobiography, memoir, essay collection, or short story book. If it must be placed in a category, it is all of these at once — a hybrid genre that the author skillfully controls, guiding the reader through meaningful life themes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She focuses on seemingly small, everyday moments, objects, encounters, and landscapes — the “roadside signs” of life that quietly define who we are. Through them she opens the major themes of human existence: fragility and strength, good and evil, love and hatred, spiritual and earthly life, and death as part of life rather than only its end. At its core, the book explores the meaning of life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Drawing from deep personal and professional experience, she asks the right questions and offers honest answers, without compromise. Truth is central and non-negotiable. Despite touches of religious and spiritual reflection, the author is not fatalistic — she insists that life and the world can change, if we are willing to change ourselves.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>With this book, Antić–Jovchevska strongly promotes literature’s power to transform the reader — for the better. That is why this distinctive and thoughtful work deserves to be read.</p>\n<!-- /wp:paragraph -->','BOOK PROMOTION – “BE SILENT AND DANCE” – SVETLANA ANTIĆ–JOVCHEVSKA','','inherit','closed','closed','','1247-revision-v1','','','2026-02-14 00:12:58','2026-02-14 00:12:58','',1247,'https://user17.delovna.finki.ukim.mk/?p=1248',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1249,1,'2026-02-14 00:14:13','2026-02-14 00:14:13','<!-- wp:paragraph -->\n<p>06/10/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/10/MUZPEOTVECER-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>ГОСТИ: УЧЕНИЦИ ОД СОУ “ПЕРО НАКОВ“ КУМАНОВО<br>МЕНТОР: ФРОСИНА МИЛОШЕВСКА<br>ВОДИТЕЛ: ИВАНА МАКСИМОВИЌ</p>\n<!-- /wp:paragraph -->','ПОЕТСКА ВЕЧЕР “11 ОКТОМВРИ 2020“ – 08.10.2020 (ЧЕТВРТОК) МАЛА САЛА 18.00 ч.','','publish','open','open','','%d0%bf%d0%be%d0%b5%d1%82%d1%81%d0%ba%d0%b0-%d0%b2%d0%b5%d1%87%d0%b5%d1%80-11-%d0%be%d0%ba%d1%82%d0%be%d0%bc%d0%b2%d1%80%d0%b8-2020-08-10-2020-%d1%87%d0%b5%d1%82%d0%b2-2','','','2026-02-14 00:14:13','2026-02-14 00:14:13','',0,'https://user17.delovna.finki.ukim.mk/?p=1249',0,'post','',0);
