INSERT INTO `wp_posts` VALUES (1278,1,'2026-02-14 00:20:37','2026-02-14 00:20:37','<!-- wp:paragraph -->\n<p>17/05/2022</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/denot-na-crvot.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>„Денот на црвот“ е роман кој навестува дека е можна „басна“ со воведувањето на главните ликови: Црвот и Чавката. Но, тоа е итра замка која низ многубројни варијанти се преточува во животните судбини на јунаците што му припаѓаат на нашиот род. Се испреплетуваат меѓусебно, се заплетуваат, се расплетуваат, понекогаш ритамот е толку вртоглаво брз што прилега на оној од анимираните филмови. Но, овие, на Јованоска, се повеќе и од живи. Цела една галерија од живописни ликови! Секој на свој начин уникатен, а сепак сите поврзани со една заедничка нишка: ослободување од „прангите“, од внатрешните и од надворешните зандани, посегнување кон Слободата. „Денот на црвот“ изобилува со свежи компарации никаде досега сретнати, ненаметлива духовитост, понекогаш и со одмерена доза сарказам. И без исклучок: проникливост и интелигентност! Сето ова во комбинација со неспорниот талент и безмалку зачудувачки зрелата раскажувачка вештина, му овозможува на нејзиното дело висок дострел“, стои во рецензијата на книгата.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5221} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280296702_3199367210347938_3347430077460038637_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5221\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5222} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280298611_3199367023681290_597215984857640813_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5222\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5223} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280313695_3199367117014614_5947668861809439518_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5223\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5224} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280330539_3199367053681287_2562241835021504952_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5224\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5225} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280365251_3199367237014602_8240244720544804876_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5225\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5226} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280390019_3199366800347979_8843849011412915245_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5226\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5227} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280415994_3199367163681276_6612142292020785485_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5227\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5228} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280463477_3199366900347969_1266116957075236277_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5228\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5229} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280474681_3199366833681309_3975785095353540981_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5229\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5230} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280480854_3199367320347927_6392926699868496751_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5230\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5231} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280500127_3199366710347988_4905627722236151381_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5231\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5232} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280540345_3199366973681295_8006025041312904445_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5232\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5233} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280550974_3199367273681265_6604739626604203034_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5233\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5234} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280566586_3199366597014666_4948455781611445512_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5234\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5235} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280602367_3199366730347986_6677259227675053074_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5235\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5236} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280647956_3199366673681325_4305809891589597832_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5236\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5237} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280662831_3199367090347950_3877543809162934051_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5237\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5238} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280679891_3199366787014647_6436984808374811270_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5238\"/></figure>\n<!-- /wp:image -->','Промоција на романот „Денот на црвот“ од Симона Јовановска','','inherit','closed','closed','','1276-revision-v1','','','2026-02-14 00:20:37','2026-02-14 00:20:37','',1276,'https://user17.delovna.finki.ukim.mk/?p=1278',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1279,1,'2026-02-14 00:21:13','2026-02-14 00:21:13','<!-- wp:paragraph -->\n<p>17/05/2022</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/denot-na-crvot.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>“The Day of the Worm” is a novel that suggests the possibility of a “fable” through the introduction of the main characters: the Worm and the Jackdaw. But this is a clever trap that, through numerous variations, transforms into the life destinies of heroes who belong to our own kind. They intertwine, become entangled, and unravel; at times the rhythm is so dizzyingly fast that it resembles that of animated films. However, Jovanovska’s characters are more than alive. A whole gallery of vivid figures — each unique in their own way, yet all connected by a common thread: liberation from “shackles,” from inner and outer prisons, and reaching toward Freedom. “The Day of the Worm” abounds in fresh, previously unseen comparisons, unobtrusive humor, and at times a measured dose of sarcasm. And without exception: insight and intelligence. All of this, combined with undeniable talent and an almost astonishingly mature narrative skill, enables her work to reach a high artistic level,” states the book’s review.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5221} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280296702_3199367210347938_3347430077460038637_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5221\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5222} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280298611_3199367023681290_597215984857640813_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5222\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5223} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280313695_3199367117014614_5947668861809439518_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5223\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5224} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280330539_3199367053681287_2562241835021504952_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5224\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5225} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280365251_3199367237014602_8240244720544804876_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5225\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5226} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280390019_3199366800347979_8843849011412915245_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5226\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5227} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280415994_3199367163681276_6612142292020785485_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5227\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5228} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280463477_3199366900347969_1266116957075236277_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5228\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5229} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280474681_3199366833681309_3975785095353540981_n-1024x683.jpg\" alt=\"\" class=\"wp-image-5229\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5230} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/280480854_3199367320347927_6392926699868496751_n-1024x683.