INSERT INTO `wp_posts` VALUES (1350,1,'2026-02-14 19:00:06','2026-02-14 19:00:06','<!-- wp:paragraph -->\n<p>25/09/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/%D0%A1%D0%A2%D0%A0%D0%A3%D0%9C%D0%98%D0%A7%D0%9A%D0%90-%D0%9F%D0%9B%D0%90%D0%9A%D0%90%D0%A2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>55 – та Меѓународна Струмичка Ликовна Колонија во Куманово</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://www.facebook.com/robert.cvetkovski.39\" target=\"_blank\" rel=\"noreferrer noopener\">ROBERT CVETKOVSKI</a>·<a href=\"https://www.facebook.com/notes/robert-cvetkovski/55-%D1%82%D0%B0-%D0%BC%D0%B5%D1%93%D1%83%D0%BD%D0%B0%D1%80%D0%BE%D0%B4%D0%BD%D0%B0-%D1%81%D1%82%D1%80%D1%83%D0%BC%D0%B8%D1%87%D0%BA%D0%B0-%D0%BB%D0%B8%D0%BA%D0%BE%D0%B2%D0%BD%D0%B0-%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D0%B8%D1%98%D0%B0-%D0%B2%D0%BE-%D0%BA%D1%83%D0%BC%D0%B0%D0%BD%D0%BE%D0%B2%D0%BE/10155657076151881/\">ЧЕТВРТОК, 27 СЕПТЕМВРИ 2018</a><a href=\"https://www.facebook.com/notes/robert-cvetkovski/55-%D1%82%D0%B0-%D0%BC%D0%B5%D1%93%D1%83%D0%BD%D0%B0%D1%80%D0%BE%D0%B4%D0%BD%D0%B0-%D1%81%D1%82%D1%80%D1%83%D0%BC%D0%B8%D1%87%D0%BA%D0%B0-%D0%BB%D0%B8%D0%BA%D0%BE%D0%B2%D0%BD%D0%B0-%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D0%B8%D1%98%D0%B0-%D0%B2%D0%BE-%D0%BA%D1%83%D0%BC%D0%B0%D0%BD%D0%BE%D0%B2%D0%BE/10155657076151881/#\"></a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>На 01.10.2018 г. / понеделник / со почеток во 20 часот во Изложбениот салон на НУ Центар за култура “Трајко Прокопиев“ – Куманово ќе биде отворена изложба на слики од 55 – та Меѓународна Струмичка Ликовна Колонија. Поставката содржи 29 дела ( 27 слики и два мозаика) а организатор и координатор на колонијата е НУ Центар за култура “Антон Панов“ – Струмица. Како учесници се јавуваат 16 ликовни уметници и тоа:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3171} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-1-1000x1024.jpg\" alt=\"\" class=\"wp-image-3171\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3172} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-5-1000x1024.jpg\" alt=\"\" class=\"wp-image-3172\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3173} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-6-1000x1024.jpg\" alt=\"\" class=\"wp-image-3173\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3174} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-7-1000x1024.jpg\" alt=\"\" class=\"wp-image-3174\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3175} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-8-1000x1024.jpg\" alt=\"\" class=\"wp-image-3175\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3176} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-9-1000x1024.jpg\" alt=\"\" class=\"wp-image-3176\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3177} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-10-1000x1024.jpg\" alt=\"\" class=\"wp-image-3177\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3178} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/katalog-2018-Strumicka-kolonija-11-1000x1024.jpg\" alt=\"\" class=\"wp-image-3178\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3179} -