INSERT INTO `wp_posts` VALUES (1394,1,'2026-02-14 19:12:52','2026-02-14 19:12:52','<!-- wp:paragraph -->\n<p>27/02/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/02/web-05.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3314} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/02/web-06-725x1024.jpg\" alt=\"\" class=\"wp-image-3314\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3316} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/02/web-03-728x1024.jpg\" alt=\"\" class=\"wp-image-3316\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3317} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/02/web-04-728x1024.jpg\" alt=\"\" class=\"wp-image-3317\"/></figure>\n<!-- /wp:image -->','EXHIBITION – 28.02.2019 (THURSDAY) 20:00 – ARCHITECTURAL PROJECT – PROTOTYPE OF A CHILDREN’S GARDEN CREATED IN KUMANOVO','','inherit','closed','closed','','1393-revision-v1','','','2026-02-14 19:12:52','2026-02-14 19:12:52','',1393,'https://user17.delovna.finki.ukim.mk/?p=1394',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1395,1,'2026-02-14 19:13:28','2026-02-14 19:13:28','<!-- wp:paragraph -->\n<p>12/03/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/03/%D0%9A%D0%A3%D0%9C%D0%90%D0%9D%D0%9E%D0%92%D0%A1%D0%9A%D0%98-%D0%93%D0%A0%D0%90%D0%A4%D0%98%D0%A7%D0%90%D0%A0%D0%98.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Биеналната изложба на графики “Кумановски графичари 2018“. На изложбата ќе бидат представени графичарите : Зоран Јакимовски, Мирослава Цветковиќ, Стефан Јакимовски, Ханифе Ислами, Милена Арсовска, Валентина Илијевска, Наим Идризи, Симона Јакимовска, Ана Јовановска, Елеонора Накевска, Сандра Симоновска, Марио Стошевски и Дејвид Стоилковски.<br>Осмото издание на биеналната изложба “Кумановски графичари 2018“ претставува обид на организаторот на оваа изложба, НУ Центар за култура “Трајко Прокопиев“ – Куманово, да овозможи континуитет во презентирањето на најновото графичко творештво од Куманово.</p>\n<!-- /wp:paragraph -->','13.03.2018 СРЕДА ПОЧ. 19.00ч. ГОСТУВАЊЕ ВО ЛИКОВЕН САЛОН ВЕЛЕС СО ИЗЛОЖБАТА “КУМАНОВСКИ ГРАФИЧАРИ 2018“','','publish','open','open','','13-03-2018-%d1%81%d1%80%d0%b5%d0%b4%d0%b0-%d0%bf%d0%be%d1%87-19-00%d1%87-%d0%b3%d0%be%d1%81%d1%82%d1%83%d0%b2%d0%b0%d1%9a%d0%b5-%d0%b2%d0%be-%d0%bb%d0%b8%d0%ba%d0%be%d0%b2%d0%b5%d0%bd-%d1%81%d0%b0','','','2026-02-14 19:13:29','2026-02-14 19:13:29','',0,'https://user17.delovna.finki.ukim.mk/?p=1395',0,'post','',0);
