INSERT INTO `wp_posts` VALUES (1419,1,'2026-02-14 19:19:27','2026-02-14 19:19:27','<!-- wp:paragraph -->\n<p>07/06/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/06/%D0%9F%D0%9B%D0%90%D0%9A%D0%90%D0%A2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->','EXHIBITION “SELF-TAUGHT 2019” – 13.06.2019 (THURSDAY) 20:00','','inherit','closed','closed','','1418-revision-v1','','','2026-02-14 19:19:27','2026-02-14 19:19:27','',1418,'https://user17.delovna.finki.ukim.mk/?p=1419',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1420,1,'2026-02-14 19:20:35','2026-02-14 19:20:35','<!-- wp:paragraph -->\n<p>20/06/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/06/%D0%9F%D0%9E%D0%9A%D0%90%D0%9D%D0%90-%D0%A6%D0%98%D0%93%D0%90%D0%A0%D0%98%D0%94%D0%9E%D0%92.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3414,\"align\":\"left\"} -->\n<figure class=\"wp-block-image alignleft\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/06/portret-201x300.jpg\" alt=\"\" class=\"wp-image-3414\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>ЦИГАРИДОВ СТЕВАН</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Роден е1 951 година во Битола, живее и работи во Скопје,<br>Бул. Јане Сандански 83-I/23. Тел. 02/2446-361,<br>моб. 078/332-236 E-mail: scigarida@yahoo.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Редовен член на ДЛУМ од 1983 година.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Самостојни изложби:<br>Скопје- 1972, 1973, 1975, 1979, 1982, 1995, 2004, 2009 (Јубилејна), 2013 (Јубилејна);<br>Битола – 2006, 2012 (Јубилејна), 2017; Охрид – 2007, 2012; Прилеп – 2010; Куманово – 2013; Скопје (КИЦ) – 2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Групни изложби:<br>Белград (Србија) – 1972, 1981; Врање (Србија) – 1977; Љубљана (Словенија) – 1978; Краљево (Србија) -1981; Париз (Франција) – 2008; Софија (Бугарија) -2009.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Изложби од светски карактер:<br>Мајданпек (Петровец) (Србија) 2014, 2016; Белград (Србија) – 2014, 2016; Рим (Италија) – 2017, Венеција (Италија) – 2018, Тревизо (Италија) – 2018; Порто (Португалија) – 2018; Веиц (Австрија) – 2018.<br>Каталог 5 селектирани уметници – Рим 2018.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>КОН&nbsp; ЈУБИЛЕЈНАТА&nbsp; ИЗЛОЖБА&nbsp; HA&nbsp; СТЕВАН&nbsp; ЦИГАРИДОВ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Сликата пред секој автор поставува некои свои бариери кои треба авторот да ги совлада за да може таа самата да зборува за себе , но и за авторот. Тие бариери се ликовните елементи како цртежот, бојата , композицијата, содржината и т.н.Бидејќи живееме во време кога секој се” може, се’ знае, се” прави , а нема професионална, и морална одговорност спрема ништо и никого, тогаш тешко е да се зборува за некаква стручност, квалитет, етика, естетика и професионализам. За да се влезе , или да се дојде до уметноста , како што реков треба да се совладаат ликовните елементи, бидејќи авторот не може да бара помош од колегите, критиката или публиката . Тој е оставен самиот на себе да се снаоѓа, да бара влез и излез од лавиринтот на уметноста. Cera е тешко некој да го ставиш во некој од познатите ликовни правци, помодни трендови или кованици од некои нео правци, базирани на веќе познатите ликовни правци. Но да се надеваме дека времето ќе најде разрешница за тие дилеми и проблеми.&nbsp; Но сега да кажам нешто и за сликарството на Стеван Цигаридов. Го познавам повеќе години и го пратам неговото движење во сликарството со целосна посветеност кон своето творештво. И порано сум рекол дека не можам да најдам фиока каде би го сместил неговото сликарство, но тоа го оставам на критичарите и кураторите. Можам само да кажам дека тоа што Цигаридов го работи има нагорна линија во употреба на колоритот, оплеменување на формите со омекнати прелази и напредок во техничката реализација на делата. Содржински се движи во рамките на својот препознатлив ракопис.Цигаридов на некој начин во својата симболично апстрактна фигурација ги бара и ги наоѓа своите ликовни патувања и задоволувања на своите сликарски амбиции. Изборот на сликите за оваа 45 -та јубилејна изложба сам ги избра за да може на ликовната публика да му го престави поцелосно или поконтинуирано движењето на своето повеќегодишно творештво. Овие слики изложени пред вас од неговите почетоци до сега претставуваат негов ликовен, а не огледалски автопортрет. Бидејќи јас мислам дека уметноста нема свој мајчин, односно национален јазик и дека таа е универзална и ги&nbsp; зборува&nbsp; сите&nbsp; светски&nbsp; јазици,&nbsp; затоа&nbsp; ве&nbsp; поканувам&nbsp; да комуницирате и да разговарате со сликите на Стеван Цигаридов.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Академик&nbsp; Васко Ташковски</p>\n<!-- /wp:paragraph -->','ИЗЛОЖБА НА СЛИКИ – 45 ГОДИШЕН ЈУБИЛЕЈ НА СТЕВАН ЦИГАРИДОВ 27.06.2019 (ЧЕТВРТОК) 20ч.','','publish','open','open','','%d0%b8%d0%b7%d0%bb%d0%be%d0%b6%d0%b1%d0%b0-%d0%bd%d0%b0-%d1%81%d0%bb%d0%b8%d0%ba%d0%b8-45-%d0%b3%d0%be%d0%b4%d0%b8%d1%88%d0%b5%d0%bd-%d1%98%d1%83%d0%b1%d0%b8%d0%bb%d0%b5%d1%98-%d0%bd%d0%b0','','','2026-02-14 19:20:35','2026-02-14 19:20:35','',0,'https://user17.delovna.finki.ukim.mk/?p=1420',0,'post','',0);
