INSERT INTO `wp_posts` VALUES (1484,1,'2026-02-14 19:40:15','2026-02-14 19:40:15','<!-- wp:paragraph -->\n<p>03/12/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/DARKO-PLAKAT.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>ON THE MARGINS OF THE SKOPJE REGION<br>– SACRAL OBJECTS AND RURAL ARCHITECTURE –</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":4093} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/Untitled-1-1-1024x433.jpg\" alt=\"\" class=\"wp-image-4093\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4094} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/01.jpg\" alt=\"\" class=\"wp-image-4094\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4095} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/02.jpg\" alt=\"\" class=\"wp-image-4095\"/></figure>\n<!-- /wp:image -->','EXHIBITION – DARKO NIKOLOVSKI – WHAT WE SEE FOR THE LAST TIME – 12.12.2019 (THURSDAY) EXHIBITION SALON 19:30','','publish','open','open','','exhibition-darko-nikolovski-what-we-see-for-the-last-time-12-12-2019-thursday-exhibition-salon-1930','','','2026-02-14 19:40:15','2026-02-14 19:40:15','',0,'https://user17.delovna.finki.ukim.mk/?p=1484',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1485,1,'2026-02-14 19:40:15','2026-02-14 19:40:15','<!-- wp:paragraph -->\n<p>03/12/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/DARKO-PLAKAT.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>ON THE MARGINS OF THE SKOPJE REGION<br>– SACRAL OBJECTS AND RURAL ARCHITECTURE –</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":4093} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/Untitled-1-1-1024x433.jpg\" alt=\"\" class=\"wp-image-4093\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4094} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/01.jpg\" alt=\"\" class=\"wp-image-4094\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4095} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/02.jpg\" alt=\"\" class=\"wp-image-4095\"/></figure>\n<!-- /wp:image -->','EXHIBITION – DARKO NIKOLOVSKI – WHAT WE SEE FOR THE LAST TIME – 12.12.2019 (THURSDAY) EXHIBITION SALON 19:30','','inherit','closed','closed','','1484-revision-v1','','','2026-02-14 19:40:15','2026-02-14 19:40:15','',1484,'https://user17.delovna.finki.ukim.mk/?p=1485',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1486,1,'2026-02-14 19:41:34','2026-02-14 19:41:34','<!-- wp:paragraph -->\n<p>11/12/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/DOROTI.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4100} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/12/78633640_3456126281128452_4252349306184400896_n-1024x1024.jpg\" alt=\"\" class=\"wp-image-4100\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>АРТ ФЕММ е производ на согледување на непостоењето на активистички феминистички мрежен центар, кој ги унапредува правата на уметничките, им дава можност за изразување и вмрежување и позитивно ги дискриминира.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Арт Фемм, го градиме оддолу нагоре, па затоа, ова е место за сите уметнички, сите активистки, сите културни работнички.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Во зачетнава фаза се воспоставуваат темели за изградба на силно женско уметничко движење, па затоа ве мотивираме, праќајте ЦВа и портфолиа на нашиот меил: artfem7@gmail.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Се прави ПАТУВАЧКА ИЗЛОЖБА на уметнички дела.<br>Со ова се започнува претставување на мрежното функционирање на жени и девојки уметнички од регионот.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Изложбите се интерактивни, се анкетираат девојки и жени уметнички и од најранливи категории, во однос на нивните мислења, како тие сметаат дека би можеле да се вклучат во АРТ ФЕММ и што би им било нив најмногу од полза ако се дел од Центар за женска слобода и уметност.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Почнуваме со Куманово, па Штип, па Тетово, па Охрид и Струга и завршуваме, за оваа година во Скопје.<br>(Датумите се претпоставени и недефинитивни)*</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Со љубов,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>АртФем тим</p>\n<!-- /wp:paragraph -->','ИЗЛОЖБА НА СЛИКИ – АРТ ФЕМ – 19.12.2019 (ЧЕТВРТОК) ФОАЈЕ 1 – поч.12ч.','','publish','open','open','','%d0%b8%d0%b7%d0%bb%d0%be%d0%b6%d0%b1%d0%b0-%d0%bd%d0%b0-%d1%81%d0%bb%d0%b8%d0%ba%d0%b8-%d0%b0%d1%80%d1%82-%d1%84%d0%b5%d0%bc-19-12-2019-%d1%87%d0%b5%d1%82%d0%b2%d1%80%d1%82%d0%be','','','2026-02-14 19:41:34','2026-02-14 19:41:34','',0,'https://user17.delovna.finki.ukim.mk/?p=1486',0,'post','',0);
