INSERT INTO `wp_posts` VALUES (1498,1,'2026-02-14 19:43:26','2026-02-14 19:43:26','<!-- wp:paragraph -->\n<p>30/01/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/01/anka-memorijalna-izlozba.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Биографија&nbsp;на Анка&nbsp;</strong><strong>Стоилковска (1972-2018)</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>—1972&nbsp; родена во Куманово<br>—1989&nbsp; Завршила средно училиште за применета уметност<br>—1995&nbsp; Завршила ФЛУ- во Скопје на графички оддел во класата на професорот Димче Николов<br>—1997&nbsp; Член е на ДЛУМ – Друштво на ликовни уметници на Македонија<br>—2005&nbsp; Магистерски студии во Софија, Р. Бугарија на графички оддел кај професори Стојан Стојанов и Здравко Стојанов</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Студиски престој</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>—2000 вo&nbsp; Cite Internationale des Arts –Париз- Франција<br>—2006 вo New York, USA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Самостојни изложби</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>—1997&nbsp; во Куманово<br>—1998&nbsp; во Скопје<br>—2002&nbsp; во Париз, (Франција) Струмица, Куманово – ( Македонија)<br>—2004&nbsp; во Софија Р. Бугарија<br>—2005&nbsp; во Скопје, Куманово<br>—2006&nbsp; во Марибор – Словенија, во Берлин, Германија<br>—2007&nbsp; во Гевгелија<br>—2009&nbsp; во Скопје<br>—2010&nbsp; во Софија<br>—2012&nbsp; во Скопје во Кафе – галерија 8<br>—2012 &nbsp;во Скопје во Кафе Ли<br>—2013 &nbsp;во Куманово, Кратово, Кавадарци</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Награди</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>—1998&nbsp; Откупна награда на Галеријата Мијачки Зографи<br>—1998&nbsp; Награда за Мал формат на ДЛУМ<br>—2000&nbsp; Откупна награда за цртеж од НУБ<br>—2000&nbsp; Голема графичка награда на ДЛУМ<br>—2002&nbsp; Награда за графика Димче Николов<br>—2003&nbsp; Награда за Цртеж Никола Мартиновски<br>—2005&nbsp; Откупна награда за Графика за тв. Телма</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>&nbsp;</strong><strong>Учествува</strong><strong>ла</strong><strong>&nbsp;&nbsp;на&nbsp;&nbsp;повеќе национални и интернационални групни изложби</strong><strong>,</strong>&nbsp;<strong>ликовни колонии и проекти</strong><strong>&nbsp;кадешто се презентираше со графики, цртежи и слики</strong><strong>.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>&nbsp;</strong><strong>Почина на 22.12.2018 г.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Од песната “Слика“ (од сликата “Селска куќа“ на сестра ми)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“…Душата страдна<br>ја бара светлината,<br>бара просветлување, прочистување.<br>Растргната меѓу вчера и денес<br>живее за утре…“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Светлана Стоилковска</p>\n<!-- /wp:paragraph -->','ИЗЛОЖБА НА ГРАФИКИ И ЦРТЕЖИ – АНКА СТОИЛКОВСКА – “НЕДОВРШЕНИ СОНИШТА… ТРАГИ КОН ВЕЧНОСТА“ 07.02.2020 ИЗЛОЖБЕН САЛОН 19.30ч.','','inherit','closed','closed','','1496-revision-v1','','','2026-02-14 19:43:26','2026-02-14 19:43:26','',1496,'https://user17.delovna.finki.ukim.mk/?p=1498',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1499,1,'2026-02-14 19:43:48','2026-02-14 19:43:48','<!-- wp:paragraph -->\n<p>30/01/2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2020/01/anka-memorijalna-izlozba.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Biography of Anka Stoilkovska (1972–2018)</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>— 1972 – Born in Kumanovo<br>— 1989 – Graduated from the Secondary School of Applied Arts<br>— 1995 – Graduated from the Faculty of Fine Arts in Skopje, Department of Graphics, in the class of Prof. Dimche Nikolov<br>— 1997 – Became a member of DLUM – Association of Fine Artists of Macedonia<br>— 2005 – Master’s studies in Sofia, Bulgaria, Department of Graphics, under Prof. Stoyan Stoyanov and Prof. Zdravko Stoyanov</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Study residencies</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>— 2000 – Cité Internationale des Arts – Paris, France<br>— 2006 – New York, USA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Solo exhibitions</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>— 1997 – Kumanovo<br>— 1998 – Skopje<br>— 2002 – Paris (France), Strumica, Kumanovo (Macedonia)<br>— 2004 – Sofia, Bulgaria<br>— 2005 – Skopje, Kumanovo<br>— 2006 – Maribor, Slovenia; Berlin, Germany<br>— 2007 – Gevgelija<br>— 2009 – Skopje<br>— 2010 – Sofia<br>— 2012 – Skopje, Café–Gallery 8<br>— 2012 – Skopje, Café Li<br>— 2013 – Kumanovo, Kratovo, Kavadarci</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Awards</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>— 1998 – Purchase Award, Mijak Iconographers Gallery<br>— 1998 – Small Format Award, DLUM<br>— 2000 – Purchase Award for Drawing, National and University Library<br>— 2000 – Grand Graphic Award, DLUM<br>— 2002 – Dimche Nikolov Award for Graphics<br>— 2003 – Nikola Martinoski Award for Drawing<br>— 2005 – Purchase Award for Graphics, Telma TV</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She participated in numerous national and international group exhibitions, art colonies, and projects, presenting prints, drawings, and paintings.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>She passed away on 22.12.2018.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>From the poem “Painting” (inspired by the painting “Village House” by my sister):</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“…The suffering soul<br>seeks the light,<br>seeks enlightenment, purification.<br>Torn between yesterday and today,<br>it lives for tomorrow…”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>— Svetlana Stoilkovska</p>\n<!-- /wp:paragraph -->','EXHIBITION OF PRINTS AND DRAWINGS – ANKA STOILKOVSKA – “UNFINISHED DREAMS… TRACES TOWARD ETERNITY” – 07.02.2020 EXHIBITION SALON 19:30','','publish','open','open','','exhibition-of-prints-and-drawings-anka-stoilkovska-unfinished-dreams-traces-toward-eternity-07-02-2020-exhibition-salon-1930','','','2026-02-14 19:43:48','2026-02-14 19:43:48','',0,'https://user17.delovna.finki.ukim.mk/?p=1499',0,'post','',0);
