INSERT INTO `wp_posts` VALUES (1592,1,'2026-02-14 21:14:45','2026-02-14 21:14:45','<!-- wp:paragraph -->\n<p>03/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Ни пристигнаа преку 150 цртежи од нашите ученици.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Комисијата ги селектираше и ги избра најдобрите.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ви благодариме и ве покануваме на отворање на изложбата.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kanë arritur rreth 150 vizatime nga nxënësit tonë.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Komisioni selektoi dhe zgjodhi vizatimet më të mira</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ju faleminderojmë dhe ju ftojmë në hapjen e ekspozitës.<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-724x1024.jpg\" alt=\"\" width=\"640\" height=\"905\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-724x1024.jpg 724w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-212x300.jpg 212w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-768x1087.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7.jpg 1447w\"></p>\n<!-- /wp:paragraph -->','ИЗЛОЖБА „Мојот имагинарен свет“','','publish','open','open','','%d0%b8%d0%b7%d0%bb%d0%be%d0%b6%d0%b1%d0%b0-%d0%bc%d0%be%d1%98%d0%be%d1%82-%d0%b8%d0%bc%d0%b0%d0%b3%d0%b8%d0%bd%d0%b0%d1%80%d0%b5%d0%bd-%d1%81%d0%b2%d0%b5%d1%82','','','2026-02-14 21:14:45','2026-02-14 21:14:45','',0,'https://user17.delovna.finki.ukim.mk/?p=1592',0,'post','',0);
