INSERT INTO `wp_posts` VALUES (1595,1,'2026-02-14 21:15:06','2026-02-14 21:15:06','<!-- wp:paragraph -->\n<p>03/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>We received over 150 drawings from our students.<br>The commission reviewed them and selected the best works.<br>Thank you, and you are invited to attend the opening of the exhibition.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kanë arritur rreth 150 vizatime nga nxënësit tanë.<br>Komisioni i përzgjodhi dhe zgjodhi vizatimet më të mira.<br>Ju falënderojmë dhe ju ftojmë në hapjen e ekspozitës.<img width=\"640\" height=\"905\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-724x1024.jpg 724w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-212x300.jpg 212w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-768x1087.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7.jpg 1447w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-724x1024.jpg\" alt=\"\"></p>\n<!-- /wp:paragraph -->','Exhibition “My Imaginary World”','','publish','open','open','','exhibition-my-imaginary-world','','','2026-02-14 21:15:06','2026-02-14 21:15:06','',0,'https://user17.delovna.finki.ukim.mk/?p=1595',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1596,1,'2026-02-14 21:15:06','2026-02-14 21:15:06','<!-- wp:paragraph -->\n<p>03/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>We received over 150 drawings from our students.<br>The commission reviewed them and selected the best works.<br>Thank you, and you are invited to attend the opening of the exhibition.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kanë arritur rreth 150 vizatime nga nxënësit tanë.<br>Komisioni i përzgjodhi dhe zgjodhi vizatimet më të mira.<br>Ju falënderojmë dhe ju ftojmë në hapjen e ekspozitës.<img width=\"640\" height=\"905\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-724x1024.jpg 724w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-212x300.jpg 212w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-768x1087.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7.jpg 1447w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/7-724x1024.jpg\" alt=\"\"></p>\n<!-- /wp:paragraph -->','Exhibition “My Imaginary World”','','inherit','closed','closed','','1595-revision-v1','','','2026-02-14 21:15:06','2026-02-14 21:15:06','',1595,'https://user17.delovna.finki.ukim.mk/?p=1596',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1597,1,'2026-02-14 21:15:39','2026-02-14 21:15:39','<!-- wp:paragraph -->\n<p>03/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/8.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Ве очекуваме на изложбата „Графички приказни“ – изложба на Стефан Јакимовски, на 18 мај во 19:30 часот во фоаје на Центар за култура Трајко Прокопиев Куманово.<br>Стефан Јакимовски е уметник кој со својот приказ и експресија на делата го поместува реалното и имагинарното и постојано е во потрага по нови прикази на своите дела кои ги следи и вклопува во модерните текови.<br>Разбирливи, едноставни, а сепак совршено вклопени во една уметничка целина.<br>Стефан Јакимовски е редовен професор е на Факултетот за дизајн и мултимедија при АУЕ-ФОН-Универзитет и основач на катедрата за графички дизајн на истиот факултет.<br>По покана одржува гостински предававања на Балкански универзитет-Скопје, Универзитет Мајка Тереза-Скопје но и научно-истражувачка посета на IT-University of Chopenhagen-Данска одеел за дигитален дизајн.<br>Предава предмети од областа на графика,графички дизајн,типографија,плакат,корпоративна комуникација и друго. Автор е на многу графички решенија и учесник на меѓународни конкурси,симпозиуми и изложби. Јакимовски е член на повеќе стручни жири комисии,рецезент на книги за средно стручно образование и ментор на наставни и вон наставни проекти. Јакимовски за својата досегашна работа има добиено многу награди и признанија.<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/8-1024x390.jpg\" alt=\"\" width=\"640\" height=\"244\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/8-1024x390.jpg 1024w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/8-300x114.jpg 300w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/8-768x292.jpg 768w\"></p>\n<!-- /wp:paragraph -->','Изложба на дигитални графички дела','','publish','open','open','','%d0%b8%d0%b7%d0%bb%d0%be%d0%b6%d0%b1%d0%b0-%d0%bd%d0%b0-%d0%b4%d0%b8%d0%b3%d0%b8%d1%82%d0%b0%d0%bb%d0%bd%d0%b8-%d0%b3%d1%80%d0%b0%d1%84%d0%b8%d1%87%d0%ba%d0%b8-%d0%b4%d0%b5%d0%bb%d0%b0','','','2026-02-14 21:15:39','2026-02-14 21:15:39','',0,'https://user17.delovna.finki.ukim.mk/?p=1597',0,'post','',0);
