INSERT INTO `wp_posts` VALUES (1612,1,'2026-02-14 21:18:38','2026-02-14 21:18:38','<!-- wp:paragraph -->\n<p>12/06/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/lik-rab.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>во Центар за култура ја оддржавме креативната ликовна работилница за деца.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Благодариме на сите дечиња за големиот интерес за оваа работилница на која се дружевме и цртавме.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Се гледаме на следната.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Работилниците се поддржани од Министерство за култура.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5850} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/06/lik-rab-721x1024.jpg\" alt=\"\" class=\"wp-image-5850\"/></figure>\n<!-- /wp:image -->','Детска ликовна работилница 2023','','publish','open','open','','%d0%b4%d0%b5%d1%82%d1%81%d0%ba%d0%b0-%d0%bb%d0%b8%d0%ba%d0%be%d0%b2%d0%bd%d0%b0-%d1%80%d0%b0%d0%b1%d0%be%d1%82%d0%b8%d0%bb%d0%bd%d0%b8%d1%86%d0%b0-2023','','','2026-02-14 21:19:11','2026-02-14 21:19:11','',0,'https://user17.delovna.finki.ukim.mk/?p=1612',0,'post','',0);
