INSERT INTO `wp_posts` VALUES (1655,1,'2026-02-14 22:01:06','2026-02-14 22:01:06','<!-- wp:paragraph -->\n<p>25/09/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/%D1%84%D0%BB%D0%B0%D0%B5%D1%80-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>02.10. (ВТОРНИК) 20ч.<br>ДРАМСКИ ТЕАТАР СКОПЈЕ<br>“КАКО ДА СЕ ОГРАБИ БАНКА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>03.10. (СРЕДА) 20ч.<br>НУЦК “Ј.Х.К. ЏИНОТ“ ТЕАТАР ВЕЛЕС<br>“ВДОВИЦАТА СЕ МАЖИ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>05.10. (ПЕТОК) 20ч.<br>НУЦК “АЦО ШОПОВ“ ТЕАТАР ШТИП<br>“УМРИ МАШКИ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>06.10. (САБОТА) 20ч.<br>ТЕАТАР КОМЕДИЈА СКОПЈЕ<br>“ЖЕНА МИ СЕ ВИКА БОРИС“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>07.10. (НЕДЕЛА) 20ч.<br>ПРОДУКЦИЈА ГМР, БЕЛГРАД, СРБИЈА<br>“СЕ ЗБОРУВА ПО ГРАДОТ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>08.10. (ПОНЕДЕЛНИК) 20ч.<br>ДРЖАВЕН МЛАДИНСКИ ТЕАТАР, ЕРЕВАН, ЕРМЕНИЈА<br>“ВКУС НА МЕДОТ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>09.10. (ВТОРНИК) 20ч.<br>МАКЕДОНСКИ НАРОДЕН ТЕАТАР СКОПЈЕ<br>“КЕЦ НА ДЕСЕТКА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.10. (СРЕДА) 20ч.<br>САТИРИЧЕН ТЕАТАР “АЛЕКО КОНСТАНТИНОВ“<br>СОФИЈА БУГАРИЈА<br>“ТЕРАПЕВТИ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>12.10. (ПЕТОК) 20ч.<br>ПРОДУКЦИЈА “ТРАГ“ БЕЛГРАД, СРБИЈА “СВИЊА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>14.10. (НЕДЕЛА) 20ч.<br>НУЦК “АНТОН ПАНОВ“ ТЕАТАР СТРУМИЦА<br>“ЗАБРАНЕТО СМЕЕЊЕ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.10. (ПОНЕДЕЛНИК) 20ч.<br>АЛБАНСКИ ТЕАТАР СКОПЈЕ “НАОПАКУ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>16.10. (ВТОРНИК) 20ч.<br>РОМСКИ ТЕАТАР “ПТИЦИ“ КУМАНОВО<br>“ВЕЌЕ НЕ ТЕ ПОЗНАВАМ“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>17.10. (СРЕДА) 20ч.<br>ЦРНОГОРСКО НАРОДНО ПОЗОРИШТЕ,<br>ПОДГОРИЦА, ЦРНА ГОРА “ УРНЕБЕСНА ТРАГЕДИЈА“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>18.10. (ЧЕТВРТОК) 20ч.<br>НУЦК “ТРАЈКО ПРОКОПИЕВ“ ТЕАТАР КУМАНОВО<br>“МАНИ, МАНИ, МАНИ“ ПРЕМИЕРА</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":2802} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/%D1%84%D0%BB%D0%B0%D0%B5%D1%80-1024x484.jpg\" alt=\"\" class=\"wp-image-2802\"/></figure>\n<!-- /wp:image -->','21 МЕЃУНАРОДЕН ФЕСТИВАЛ “ДЕНОВИ НА КОМЕДИЈА – КУМАНОВО 2018“ БИЛЕТИТЕ СЕ ВО ПРОДАЖБА','','publish','open','open','','21-%d0%bc%d0%b5%d1%93%d1%83%d0%bd%d0%b0%d1%80%d0%be%d0%b4%d0%b5%d0%bd-%d1%84%d0%b5%d1%81%d1%82%d0%b8%d0%b2%d0%b0%d0%bb-%d0%b4%d0%b5%d0%bd%d0%be%d0%b2%d0%b8-%d0%bd%d0%b0-%d0%ba%d0%be%d0%bc','','','2026-02-14 22:01:06','2026-02-14 22:01:06','',0,'https://user17.delovna.finki.ukim.mk/?p=1655',0,'post','',0);
