INSERT INTO `wp_posts` VALUES (1658,1,'2026-02-14 22:01:32','2026-02-14 22:01:32','<!-- wp:paragraph -->\n<p>25/09/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/%D1%84%D0%BB%D0%B0%D0%B5%D1%80-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Program Schedule:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>02.10 (Tuesday) – 20:00</strong><br>Drama Theatre Skopje<br><em>“How to Rob a Bank”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>03.10 (Wednesday) – 20:00</strong><br>NUCC “J.H.K. Džinot” Theatre Veles<br><em>“The Widow Gets Married”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>05.10 (Friday) – 20:00</strong><br>NUCC “Aco Šopov” Theatre Štip<br><em>“Die Like a Man”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>06.10 (Saturday) – 20:00</strong><br>Comedy Theatre Skopje<br><em>“My Wife Is Called Boris”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>07.10 (Sunday) – 20:00</strong><br>GMR Production, Belgrade, Serbia<br><em>“People Are Talking Around Town”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>08.10 (Monday) – 20:00</strong><br>State Youth Theatre, Yerevan, Armenia<br><em>“A Taste of Honey”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>09.10 (Tuesday) – 20:00</strong><br>Macedonian National Theatre Skopje<br><em>“Ace Up the Sleeve”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>10.10 (Wednesday) – 20:00</strong><br>Satirical Theatre “Aleko Konstantinov”<br>Sofia, Bulgaria<br><em>“Therapists”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>12.10 (Friday) – 20:00</strong><br>“Trag” Production, Belgrade, Serbia<br><em>“Pig”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>14.10 (Sunday) – 20:00</strong><br>NUCC “Anton Panov” Theatre Strumica<br><em>“Forbidden Laughter”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>15.10 (Monday) – 20:00</strong><br>Albanian Theatre Skopje<br><em>“Upside Down”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>16.10 (Tuesday) – 20:00</strong><br>Roma Theatre “Birds” Kumanovo<br><em>“I Don’t Recognize You Anymore”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>17.10 (Wednesday) – 20:00</strong><br>Montenegrin National Theatre<br>Podgorica, Montenegro<br><em>“A Hilarious Tragedy”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>18.10 (Thursday) – 20:00</strong><br>NUCC “Trajko Prokopiev” Theatre Kumanovo<br><em>“Money, Money, Money”</em> — <strong>Premiere</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":2802} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/09/%D1%84%D0%BB%D0%B0%D0%B5%D1%80-1024x484.jpg\" alt=\"\" class=\"wp-image-2802\"/></figure>\n<!-- /wp:image -->','21st INTERNATIONAL FESTIVAL “DAYS OF COMEDY – KUMANOVO 2018” – TICKETS ON SALE','','publish','open','open','','21st-international-festival-days-of-comedy-kumanovo-2018-tickets-on-sale','','','2026-02-14 22:01:32','2026-02-14 22:01:32','',0,'https://user17.delovna.finki.ukim.mk/?p=1658',0,'post','',0);
