INSERT INTO `wp_posts` VALUES (1715,1,'2026-02-14 22:11:28','2026-02-14 22:11:28','<!-- wp:paragraph -->\n<p>12/10/2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/42269557_2212105598803949_1733845277686628352_n.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>ПОРАДИ ТЕХНИЧКИ ПРОБЛЕМИ НА ЕКИПАТА НА ТЕАТАР СТРУМИЦА ЌЕ НАСТАПИ&nbsp;<br>ТЕАТАР “КРИК“ СКОПЈЕ СО ПРЕТСТАВАТА&nbsp;<br>“ПРВИН ЌЕ МЕ ЗЕМЕШ, ПОСЛЕ ЌЕ МЕ…“</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Режија: Ѓорѓи Ризески</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Сценографија: Роберт Ристов</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Костимографија: Елена Лука</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Продукција: Театар КРИК</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Играат:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ѓорѓи Мучев –&nbsp;<a>Роберт Ристов</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kети Мјау Соколовска –&nbsp;<a>Мирјана Поповска Ристов</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Келнерот/ Водителот – Дарко Вељиќ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>„Првин ќе ме земеш, после ќе ме…“ е првото реално шоу во Театар Комедија.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Дејството на претставата се случува овде и сега, во еден реален временски интервал, за време на едновечерна средба „на слепо“ помеѓу лекторката Кети Мјау Соколовска и ветеринарот Ѓорѓи Мучев. Тој – маж со неуспешен брак зад себеси, решен никогаш веќе да не се жени и на оваа средба гледа само како на едновечерна авантура, Таа – девојка со веќе донесена одлука – да се омажи на оваа средба, уште истата вечер.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ова е единствената претстава за време на која вие како публика сте активен учесник во режирањето на претставата. Дали Таа да го бакне или да му удри шамар, дали Тој или Таа да одговори на повикот од неговата бивша жена – одлучувате вие по пат на гласање во живо!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3240} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/FNX_4601-1024x683.jpg\" alt=\"\" class=\"wp-image-3240\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3241} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/FNX_4677-1024x683.jpg\" alt=\"\" class=\"wp-image-3241\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3242} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/FNX_4705-1024x683.jpg\" alt=\"\" class=\"wp-image-3242\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3243} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/FNX_4739-1024x683.jpg\" alt=\"\" class=\"wp-image-3243\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3244} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2018/10/FNX_4756-1024x683.jpg\" alt=\"\" class=\"wp-image-3244\"/></figure>\n<!-- /wp:image -->','4.10. (НЕДЕЛА) 20ч. ПРОДУКЦИЈА ТЕАТАР “КРИК“ СКОПЈЕ','','publish','open','open','','4-10-%d0%bd%d0%b5%d0%b4%d0%b5%d0%bb%d0%b0-20%d1%87-%d0%bf%d1%80%d0%be%d0%b4%d1%83%d0%ba%d1%86%d0%b8%d1%98%d0%b0-%d1%82%d0%b5%d0%b0%d1%82%d0%b0%d1%80-%d0%ba%d1%80%d0%b8%d0%ba','','','2026-02-14 22:11:28','2026-02-14 22:11:28','',0,'https://user17.delovna.finki.ukim.mk/?p=1715',0,'post','',0);
