INSERT INTO `wp_posts` VALUES (1750,1,'2026-02-14 22:20:02','2026-02-14 22:20:02','<!-- wp:paragraph -->\n<p>24/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/srpska-nova.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Due to high interest,<br>the play “School for Lovers” by “Academy 28” from Belgrade, Serbia<br>will also be performed on 09.10.2019 (Wednesday) at 20:00.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Tickets will be on sale from 24.09.2019 at 17:00.</p>\n<!-- /wp:paragraph -->','ANNOUNCEMENT – DAYS OF COMEDY – KUMANOVO 2019 (1–15 October 2019)','','publish','open','open','','announcement-days-of-comedy-kumanovo-2019-1-15-october-2019','','','2026-02-14 22:20:02','2026-02-14 22:20:02','',0,'https://user17.delovna.finki.ukim.mk/?p=1750',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1751,1,'2026-02-14 22:20:02','2026-02-14 22:20:02','<!-- wp:paragraph -->\n<p>24/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/srpska-nova.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Due to high interest,<br>the play “School for Lovers” by “Academy 28” from Belgrade, Serbia<br>will also be performed on 09.10.2019 (Wednesday) at 20:00.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Tickets will be on sale from 24.09.2019 at 17:00.</p>\n<!-- /wp:paragraph -->','ANNOUNCEMENT – DAYS OF COMEDY – KUMANOVO 2019 (1–15 October 2019)','','inherit','closed','closed','','1750-revision-v1','','','2026-02-14 22:20:02','2026-02-14 22:20:02','',1750,'https://user17.delovna.finki.ukim.mk/?p=1751',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1752,1,'2026-02-14 22:21:03','2026-02-14 22:21:03','<!-- wp:paragraph -->\n<p>27/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/PLAKAT-DKK-2019-def.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong>22 МЕЃУНАРОДЕН ТЕАТАРСКИ ФЕСТИВАЛ</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong>ДЕНОВИ&nbsp;</strong><strong>НА КОМЕДИЈА –&nbsp;</strong><strong>КУМАНОВО 2019</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>01.10. (вторник) – „СТРАНЦИ“ – ДРАМСКИ ТЕАТАР&nbsp; – СКОПЈЕ</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>02.10. (среда) – „ЉУБАФ“</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>ГРАДСКО КАЗАЛИШТЕ „ЈОЗА ИВАКИЌ“ ВИНКОВЦИ, ХРВАТСКА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>03.10. (четврток) – „39 ЧЕКОРИ“</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>НУЦК „ТРАЈКО ПРОКОПИЕВ“ АЛБАНСКА ДРАМА КУМАНОВO&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>04.10. (</strong><strong>петок</strong><strong>) – „МОЈ ТЕРМИН“&nbsp; –&nbsp; М Н Т СКОПЈЕ</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>05.10. (сабота) – „ОДАМ НА ЛОВ“ – ТЕАТАР “Ј.Х.К – ЏИНОТ“ – ВЕЛЕС</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>06.10. (недела) – „ВЛАСТ“ – ТЕАТАР “СЛАВИЈА“, БЕЛГРАД, СРБИЈА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>07.10. (понеделник) – „ЖЕНИ ПРЕД НЕРВЕН СЛОМ“</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>ТЕАТАР КОМЕДИЈА – СКОПЈЕ</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>10.10. (четврток) – „ШКОЛО ЗА ЉУБОВНИЦИ“&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>АКАДЕМИЈА 28 СЦЕНА, БЕЛГРАД, СРБИЈА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>12.10. (сабота) – „СМЕЈ СЕ ЗА ЗБОГУМ“&nbsp; САТИРИЧЕН ТЕАТАР</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>„АЛЕКО КОНСТАНТИНОВ“, СОФИЈА, БУГАРИЈА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>13.10. (недела) – „ДОКТОР ШУСТЕР“&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>ТЕАТАР „АНДОН ЗАКО ЧАЈУПИ“ КОРЧА, АЛБАНИЈА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>14.10. (понеделник) – „ЗАПОЗНАЈ ГО МОЈОТ ТАТКО“&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>ПРОДУКЦИЈА „КАКО ВАМ ДРАГО“ БЕЛГРАД, СРБИЈА</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>15.10. (вторник) – „БЕГАЛКА“&nbsp;</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>НУЦК „ТРАЈКО ПРОКОПИЕВ“ ТЕАТАР КУМАНОВО</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3776} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/02-1024x1024.jpg\" alt=\"\" class=\"wp-image-3776\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3777} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/03-1024x1024.jpg\" alt=\"\" class=\"wp-image-3777\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3778} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/04-1024x1024.jpg\" alt=\"\" class=\"wp-image-3778\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3779} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/05-1024x1024.jpg\" alt=\"\" class=\"wp-image-3779\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3844} -->\n<fig