INSERT INTO `wp_posts` VALUES (1755,1,'2026-02-14 22:23:39','2026-02-14 22:23:39','<!-- wp:paragraph -->\n<p>27/09/2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/PLAKAT-DKK-2019-def.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">DAYS OF COMEDY – KUMANOVO 2019 (1–15 October 2019)<br>27/09/2019</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>22nd INTERNATIONAL THEATRE FESTIVAL<br>DAYS OF COMEDY – KUMANOVO 2019</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>01.10 (Tuesday) – “STRANGERS” – Drama Theatre – Skopje</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>02.10 (Wednesday) – “LOVE” – City Theatre “Joza Ivakić”, Vinkovci, Croatia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>03.10 (Thursday) – “The 39 Steps” – NUCC “Trajko Prokopiev” Albanian Drama – Kumanovo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>04.10 (Friday) – “My Appointment” – Macedonian National Theatre Skopje</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>05.10 (Saturday) – “Going Hunting” – Theatre “J.H.K. Dzinot” – Veles</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>06.10 (Sunday) – “Power” – Theatre “Slavija”, Belgrade, Serbia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>07.10 (Monday) – “Women on the Verge of a Nervous Breakdown” – Theatre Comedy – Skopje</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.10 (Thursday) – “School for Lovers” – Academy 28 Scene, Belgrade, Serbia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>12.10 (Saturday) – “Laugh for Goodbye” – Satirical Theatre “Aleko Konstantinov”, Sofia, Bulgaria</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>13.10 (Sunday) – “Doctor Shuster” – Theatre “Andon Zako Çajupi”, Korçë, Albania</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>14.10 (Monday) – “Meet My Father” – Production “Kako Vam Drago”, Belgrade, Serbia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.10 (Tuesday) – “The Runaway Woman” – NUCC “Trajko Prokopiev” Theatre – Kumanovo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3776} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/02-1024x1024.jpg\" alt=\"\" class=\"wp-image-3776\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3777} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/03-1024x1024.jpg\" alt=\"\" class=\"wp-image-3777\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3778} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/04-1024x1024.jpg\" alt=\"\" class=\"wp-image-3778\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3779} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/05-1024x1024.jpg\" alt=\"\" class=\"wp-image-3779\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3844} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/06-1-1024x1024.jpg\" alt=\"\" class=\"wp-image-3844\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3781} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/07-1024x1024.jpg\" alt=\"\" class=\"wp-image-3781\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3782} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/08-1024x1024.jpg\" alt=\"\" class=\"wp-image-3782\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":3783} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2019/09/09-1024x1024.jpg\" alt=\"\" class=\"wp-image-3783\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {