INSERT INTO `wp_posts` VALUES (1786,1,'2026-02-15 20:59:07','2026-02-15 20:59:07','<!-- wp:paragraph -->\n<p>17/05/2022</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/Trite-prasinja.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Моментите на среќа од вчерашната премиера на претставата</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>„Волкот и трите прасиња“</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Уживајте во фотографиите.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Благодариме на нашата публика и ве очекуваме во Театар.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>фото: Иван Михајловиќ</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5152} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/279763897_3195129327438393_8597875171951345299_n-1024x707.jpg\" alt=\"\" class=\"wp-image-5152\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5153} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/279786588_3195129270771732_1695010859529568250_n-1024x682.jpg\" alt=\"\" class=\"wp-image-5153\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5154} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/279798324_3195131364104856_6131089359397569038_n-1024x682.jpg\" alt=\"\" class=\"wp-image-5154\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5155} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2022/05/279803294_3195130144104978_7583133581577817661_n-682x1024.jpg\" alt=\"\" class=\"wp-image-5155\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":5156} -->\n<figure class=\