INSERT INTO `wp_posts` VALUES (1804,1,'2026-02-15 21:03:08','2026-02-15 21:03:08','<!-- wp:paragraph -->\n<p>26/04/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>With great honor, we announce the <strong>PREMIERE</strong> of the play</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“For Whom the Bells Toll”</strong>, directed by Martin Kochovski.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>75 years of Kumanovo Theatre.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>On May 3 at 20:00.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Tickets go on sale starting tomorrow, April 25, at the box office in the Center for Culture.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><br>Box office working hours: 10:00–14:00 and 17:00–20:00.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img width=\"640\" height=\"914\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5-717x1024.jpg 717w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5-210x300.jpg 210w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5-768x1097.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5.jpg 1434w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5-717x1024.jpg\" alt=\"\"></p>\n<!-- /wp:paragraph -->','Premiere of the play “For Whom the Bells Toll”','','publish','open','open','','premiere-of-the-play-for-whom-the-bells-toll','','','2026-02-15 21:03:08','2026-02-15 21:03:08','',0,'https://user17.delovna.finki.ukim.mk/?p=1804',0,'post','',0);
