INSERT INTO `wp_posts` VALUES (1819,1,'2026-02-15 21:05:47','2026-02-15 21:05:47','<!-- wp:paragraph -->\n<p>04/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Dear audience,</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><br>The next performance of the play <strong>“For Whom the Bells Toll”</strong> is scheduled for May 11 at 20:00.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><br>Tickets are on sale starting today (Thursday) at the box office in the Cultural Center.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kumanovo Theater</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><br>Cultural Center</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5645} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/04/6-5-717x1024.jpg\" alt=\"\" class=\"wp-image-5645\"/></figure>\n<!-- /wp:image -->','“For Whom the Bells Toll”','','inherit','closed','closed','','1818-revision-v1','','','2026-02-15 21:05:47','2026-02-15 21:05:47','',1818,'https://user17.delovna.finki.ukim.mk/?p=1819',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1820,1,'2026-02-15 21:06:22','2026-02-15 21:06:22','<!-- wp:paragraph -->\n<p>11/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Како една од најстарите уметнички форми, бајката e потреба низ сон, мечтаење, имагинација да се наткрили животот. Таа со својот јасен и цврст етички кодекс (борба за добро, правда, еднаквост, љубов) ни открива и подвлекува некои суштински животни вредности. Бајката на сцена не толкува, објаснува, ниту докажува, туку повеќе потшепнува и предизвикува, запрашува и провоцира и, оддалечувајќи нè од животот, ни зборува за животот. Таква е и нашата „Трнорушка“.<br>Актерската екипа која учествува во претставата се: Сања Русеска<br>(премиерна подела ) Александра Михајловска, Владанка Димковска, Марко Трајковиќ, Нина Максимова, Жарко Јовановиќ и Давид Илиќ.<br>Режија: Бојана Краљевска<br>Сценографија: Крсто Богојевски<br>Костими: Дарко Илиевски<br>Драматургија: Зоран Зафировски<br>Музичка илистрација: Зоран Зафировски<br>17 мај ( среда) од 18:00 часот<br>Билети на билетара во Центар за култура од понеделник 8 мај.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":5708} -->\n<figure class=\"wp-block-image\"><img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-2-1024x682.jpg\" alt=\"\" class=\"wp-image-5708\"/></figure>\n<!-- /wp:image -->','Театарска претстава „Трнорушка“','','publish','open','open','','%d1%82%d0%b5%d0%b0%d1%82%d0%b0%d1%80%d1%81%d0%ba%d0%b0-%d0%bf%d1%80%d0%b5%d1%82%d1%81%d1%82%d0%b0%d0%b2%d0%b0-%d1%82%d1%80%d0%bd%d0%be%d1%80%d1%83%d1%88%d0%ba%d0%b0','','','2026-02-15 21:06:22','2026-02-15 21:06:22','',0,'https://user17.delovna.finki.ukim.mk/?p=1820',0,'post','',0);
