INSERT INTO `wp_posts` VALUES (1828,1,'2026-02-15 21:08:23','2026-02-15 21:08:23','<!-- wp:paragraph -->\n<p>11/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-2.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>“I just want it to be quiet.<br>I want to sleep.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A performance no one dreamed of. And a dream everyone woke up from, yet no one told.<br>2001.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>May 22 (Monday)<br>Small Stage (Kumanovo Theater)<br>Free entry<br>Starts at 20:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><img width=\"640\" height=\"905\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-2-724x1024.jpg 724w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-2-212x300.jpg 212w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-2-768x1086.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-2.jpg 842w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/3-2-724x1024.jpg\" alt=\"\"> <img width=\"640\" height=\"905\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-2-724x1024.jpg 724w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-2-212x300.jpg 212w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-2-768x1086.jpg 768w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-2.jpg 842w\" src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/4-2-724x1024.jpg\" alt=\"\"></p>\n<!-- /wp:paragraph -->','Theater Performance “Departures”','','publish','open','open','','theater-performance-departures','','','2026-02-15 21:08:23','2026-02-15 21:08:23','',0,'https://user17.delovna.finki.ukim.mk/?p=1828',0,'post','',0);
