INSERT INTO `wp_posts` VALUES (1830,1,'2026-02-15 21:08:56','2026-02-15 21:08:56','<!-- wp:paragraph -->\n<p>26/05/2023</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-3.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>На 27 мај (сабота)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>20:00 часот</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Хуманитарен настан.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Продажбата од билетите ќе биде донирана на Теодосија и Ана.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ве очекуваме.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Билетите се во продажба од денес 19 мај од 12:00 часот на билетара во Центар за култура.<img src=\"http://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-3.jpg\" alt=\"\" width=\"509\" height=\"720\" srcset=\"https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-3.jpg 509w, https://nucktrajkoprokopiev.mk/wp-content/uploads/2023/05/1-3-212x300.jpg 212w\"></p>\n<!-- /wp:paragraph -->','Хуманитарен настан','','publish','open','open','','%d1%85%d1%83%d0%bc%d0%b0%d0%bd%d0%b8%d1%82%d0%b0%d1%80%d0%b5%d0%bd-%d0%bd%d0%b0%d1%81%d1%82%d0%b0%d0%bd','','','2026-02-15 21:08:56','2026-02-15 21:08:56','',0,'https://user17.delovna.finki.ukim.mk/?p=1830',0,'post','',0);
