INSERT INTO `wp_posts` VALUES (1918,1,'2026-02-15 23:18:55','2026-02-15 23:18:55','/* Event cards */\n.blog-layout-1 .ast-article-post {\n    background: #ffffff;\n    border-radius: 12px;\n    overflow: hidden;\n    box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n    transition: transform 0.25s ease, box-shadow 0.25s ease;\n}\n\n.blog-layout-1 .ast-article-post:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 14px 35px rgba(0,0,0,0.12);\n}\n\n/* Image */\n.blog-layout-1 .post-thumb img {\n    border-radius: 12px 12px 0 0;\n}\n\n/* Title */\n.blog-layout-1 .entry-title a {\n    color: #111;\n    text-decoration: none;\n}\n\n.blog-layout-1 .entry-title a:hover {\n    color: #b40000; /* можеш да ја смениш во боја од логото */\n}\n\n\n/* Pagination */\n.ast-pagination a,\n.ast-pagination span {\n    padding: 10px 14px;\n    margin: 0 4px;\n    border-radius: 8px;\n    background: #f2f2f2;\n    color: #111;\n}\n\n.ast-pagination .current {\n    background: #b40000;\n    color: #fff;\n}\n\n\n/* Card wrapper */\n.cards-equal .wp-block-post{\n  background: #fff;\n  border: 1px solid rgba(0,0,0,.08);\n  border-radius: 6px;\n  overflow: hidden;\n  height: 100%;\n  display: flex;\n}\n\n/* Make inner layout vertical */\n.cards-equal .wp-block-post > div{\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Image on top with fixed height */\n.cards-equal .wp-block-post-featured-image img{\n  width: 100%;\n  height: 100%;      /* менувај ако сакаш */\n  object-fit: cover;\n  display: block;\n}\n\n/* Content fills remaining height */\n.cards-equal .wp-block-post-content{\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  padding: 14px 16px;\n}\n\n/* Push \"read more\" to bottom */\n.cards-equal .wp-block-post-excerpt{\n  margin-top: auto;\n}\n\n/* Optional: make title spacing nicer */\n.cards-equal .wp-block-post-title{\n  margin: 0 0 10px 0;\n}\n\n','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-15 23:18:55','2026-02-15