area .widget,\naside .widget {\n  background: #ffffff;\n  border: 1px solid rgba(0,0,0,0.10);\n/*   border-radius: 16px; */\n  padding: 16px;\n  margin-bottom: 22px;\n  box-shadow: 0 8px 22px rgba(0,0,0,0.06);\n}\n\n/* Sidebar menu list reset */\n.sidebar-main .widget ul,\n.ast-sidebar .widget ul,\n.widget-area .widget ul,\naside .widget ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* Sidebar links */\n.sidebar-main .widget ul li a,\n.ast-sidebar .widget ul li a,\n.widget-area .widget ul li a,\naside .widget ul li a {\n  display: block;\n  padding: 10px 12px;\n  border-radius: 10px;\n  text-decoration: none;\n  font-weight: 600;\n  color: #1a1a1a;\n  transition: all .2s ease;\n}\n\n/* Hover */\n.sidebar-main .widget ul li a:hover,\n.ast-sidebar .widget ul li a:hover,\n.widget-area .widget ul li a:hover,\naside .widget ul li a:hover {\n  background: #f3f4f6;\n  transform: translateX(4px);\n}\n\n/* Active item */\n.sidebar-main .current-menu-item > a,\n.ast-sidebar .current-menu-item > a,\n.widget-area .current-menu-item > a,\naside .current-menu-item > a {\n  background: #e9eef5;\n  border-left: 4px solid #c62828; /* црвено да ти match-ира со логото */\n  padding-left: 8px;\n}\n\n\n\n\n\n','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-16 15:10:54','2026-02-16 15:10:54','',309,'https://user17.delovna.finki.ukim.mk/?p=1976',0,'revision','',0);
