INSERT INTO `wp_posts` VALUES (2085,1,'2026-02-17 21:23:47','2026-02-17 21:23:47','<!-- wp:query {\"queryId\":6,\"query\":{\"perPage\":10,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"exclude\",\"inherit\":false,\"taxQuery\":{\"category\":[337]}},\"metadata\":{\"categories\":[\"posts\"],\"patternName\":\"core/query-grid-posts\",\"name\":\"Grid\"}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template {\"className\":\"cards-equal\",\"layout\":{\"type\":\"grid\",\"columnCount\":2}} -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"30px\",\"right\":\"30px\",\"bottom\":\"30px\",\"left\":\"30px\"}},\"border\":{\"width\":\"10px\"}},\"borderColor\":\"cyan-bluish-gray\",\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group has-border-color has-cyan-bluish-gray-border-color\" style=\"border-width:10px;padding-top:30px;padding-right:30px;padding-bottom:30px;padding-left:30px\"><!-- wp:post-featured-image {\"isLink\":true} /-->\n\n<!-- wp:post-title {\"isLink\":true,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}},\"fontSize\":\"medium\"} /-->\n\n<!-- wp:post-excerpt /-->\n\n<!-- wp:post-date {\"metadata\":{\"bindings\":{\"datetime\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"date\"}}}}} /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template --></div>\n<!-- /wp:query -->','Матични форми','','inherit','closed','closed','','208-revision-v1','','','2026-02-17 21:23:47','2026-02-17 21:23:47','',208,'https://user17.delovna.finki.ukim.mk/?p=2085',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2087,1,'2026-02-17 21:24:04','2026-02-17 21:24:04','/* =========================================================\n   1) Astra archive cards (ако некогаш користиш blog layout)\n   ========================================================= */\n\n.blog-layout-1 .ast-article-post {\n  background: #ffffff;\n  border: 3px solid transparent; /* за да нема скок на hover */\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n.blog-layout-1 .ast-article-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828; /* црвен акцент */\n  box-shadow: 0 14px 35px rgba(0,0,0,0.12);\n}\n\n.blog-layout-1 .post-thumb img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n.blog-layout-1 .entry-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.blog-layout-1 .entry-title a:hover {\n  color: #c62828;\n}\n\n/* Pagination */\n.ast-pagination a,\n.ast-pagination span {\n  padding: 10px 14px;\n  margin: 0 4px;\n  border-radius: 8px;\n  background: #f2f2f2;\n  color: #111;\n}\n\n.ast-pagination .current {\n  background: #c62828;\n  color: #fff;\n}\n\n\n/* =========================================================\n   2) Query Loop cards (ГЛАВНО — cards-equal wrapper)\n   ========================================================= */\n\n.cards-equal .wp-block-post {\n  background: #fff;\n  border: 3px solid transparent;   /* фиксна дебелина → нема layout shift */\n  border-radius: 12px;\n  overflow: hidden;\n  height: 100%;\n  display: flex;\n  box-shadow: 0 8px 24px rgba(0,0,0,0.06);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n/* Hover = приближување + црвен border */\n.cards-equal .wp-block-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828;\n  box-shadow: 0 14px 36px rgba(0,0,0,0.10);\n}\n\n/* Vertical layout inside card */\n.cards-equal .wp-block-post > div {\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Featured image — фиксна висина */\n.cards-equal .wp-block-post-featured-image img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n/* Content area */\n.cards-equal .wp-block-post-content {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  padding: 14px 16px;\n}\n\n/* Title */\n.cards-equal .wp-block-post-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.cards-equal .wp-block-post-title a:hover {\n  color: #c62828;\n}\n\n/* Excerpt долу */\n.cards-equal .wp-block-post-excerpt {\n  margin-top: auto;\n}\n\n\n/* =========================================================\n   3) Minimal sidebar (white/black + subtle red)\n   ========================================================= */\n\n.sidebar-main .widget,\n.ast-sidebar .widget,\n.widget-area .widget,\naside .widget {\n  background: #fff;\n  border: 1px solid rgba(0,0,0,0.08);\n  padding: 14px 14px;\n  margin-bottom: 18px;\n  box-shadow: none;\n}\n\n/* Lists reset */\n.sidebar-main .widget ul,\n.ast-sidebar .widget ul,\n.widget-area .widget ul,\naside .widget ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* Links */\n.sidebar-main .widget ul li a,\n.ast-sidebar .widget ul li a,\n.widget-area .widget ul li a,\naside .widget ul li a {\n  display: block;\n  padding: 10px 12px;\n  border-radius: 8px;\n  text-decoration: none;\n  font-weight: 600;\n  color: #111;\n  background: transparent;\n  transition: background .15s ease, color .15s ease;\n}\n\n/* Hover */\n.sidebar-main .widget ul li a:hover,\n.ast-sidebar .widget ul li a:hover,\n.widget-area .widget ul li a:hover,\naside .widget ul li a:hover {\n  background: rgba(0,0,0,0.035);\n}\n\n/* Active item — црвен accent bar */\n.sidebar-main .current-menu-item > a,\n.ast-sidebar .current-menu-item > a,\n.widget-area .current-menu-item > a,\naside .current-menu-item > a {\n  background: rgba(198,40,40,0.08);\n  color: #111;\n  border-left: 3px solid #c62828;\n  padding-left: 10px;\n}\n\n/* Rhythm */\n.sidebar-main .widget ul li,\n.ast-sidebar .widget ul li,\n.widget-area .widget ul li,\naside .widget ul li {\n  margin: 4px 0;\n}\n\n\n\n.map-btn {\n  text-decoration: none;\n  padding: 10px 16px;\n  border-radius: 6px;\n  background: #f2f2f2;\n  color: #222;\n  display: inline-block;\n  transition: 0.2s ease;\n}\n\n.map-btn:hover {\n	text-decoration: none;\n  color: #c62828;\n  background: #ffe5e5;\n}\n\n/* =========================================================\n   Query Loop Pagination (button style like screenshot)\n   ========================================================= */\n\n/* Wrapper */\n.wp-block-query-pagination{\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: nowrap; /* да не се крши во нов ред */\n  margin: 28px 0;\n}\n\n/* Make all items look like buttons */\n.wp-block-query-pagination a,\n.wp-block-query-pagination span{\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 36px;\n  height: 36px;\n  padding: 0 10px;\n  border-radius: 0;              /* квадратчиња */\n  background: #4a4a4a;           /* темно сиво */\n  color: #fff !important;\n  text-decoration: none !important;\n  font-weight: 700;\n  line-height: 1;\n  border: 1px solid rgba(0,0,0,0.18);\n  transition: transform .15s ease, filter .15s ease, background .15s ease;\n}\n\n/* Hover */\n.wp-block-query-pagination a:hover{\n  transform: translateY(-2px);\n  filter: brightness(1.08);\n}\n\n/* Current page */\n.wp-block-query-pagination .current{\n  background: #c62828;\n  border-color: #c62828;\n}\n\n/* Dots \"...\" */\n.wp-block-query-pagination .dots{\n  background: transparent;\n  border: 0;\n  color: #4a4a4a !important;\n  min-width: auto;\n  padding: 0 6px;\n}\n\n/* Prev / Next buttons */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  background: #4a4a4a;\n  color: #fff !important;\n  text-decoration: none !important;\n  white-space: nowrap; /* PREVIOUS PAGE да не се крши */\n}\n\n/* Ако сакаш PREV/NEXT да бидат малку пошироки */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  padding: 0 14px;\n}\n\n','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-17 21:24:04','2026-02-17 21:24:04','',309,'https://user17.delovna.finki.ukim.mk/?p=2087',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2089,1,'2026-02-17 21:26:20','2026-02-17 21:26:20','<!-- wp:query {\"queryId\":13,\"query\":{\"perPage\":6,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"exclude\",\"inherit\":false,\"taxQuery\":{\"category\":[91,23,95]}},\"metadata\":{\"categories\":[\"posts\"],\"patternName\":\"core/query-grid-posts\",\"name\":\"Grid\"},\"className\":\"cards-equal\"} -->\n<div class=\"wp-block-query cards-equal\"><!-- wp:post-template {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|50\"}},\"fontSize\":\"medium\",\"layout\":{\"type\":\"grid\",\"columnCount\":2,\"minimumColumnWidth\":null}} -->\n<!-- wp:group {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-8\"}}},\"position\":{\"type\":\"\"},\"dimensions\":{\"minHeight\":\"\"},\"spacing\":{\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"right\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}},\"border\":{\"color\":\"#a2aeb9\",\"width\":\"10px\"}},\"textColor\":\"ast-global-color-8\",\"fontSize\":\"small\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-border-color has-ast-global-color-8-color has-text-color has-link-color has-small-font-size\" style=\"border-color:#a2aeb9;border-width:10px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"auto\",\"width\":\"\",\"height\":\"\"} /-->\n\n<!-- wp:post-title {\"level\":3,\"isLink\":true,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-2\"}}},\"border\":{\"radius\":{\"topLeft\":\"0px\",\"topRight\":\"0px\",\"bottomLeft\":\"0px\",\"bottomRight\":\"0px\"}},\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}},\"fontSize\":\"medium\"} /-->\n\n<!-- wp:post-excerpt {\"textAlign\":\"left\",\"showMoreOnNewLine\":false,\"excerptLength\":10,\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"fontSize\":\"small\"} /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:query-pagination {\"style\":{\"typography\":{\"letterSpacing\":\"4px\",\"textTransform\":\"uppercase\",\"fontStyle\":\"normal\",\"fontWeight\":\"300\"},\"color\":{\"background\":\"#ece8e8\"}},\"fontSize\":\"medium\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"orientation\":\"horizontal\",\"flexWrap\":\"nowrap\"}} -->\n<!-- wp:query-pagination-previous {\"style\":{\"typography\":{\"textDecoration\":\"none\"}}} /-->\n\n<!-- wp:query-pagination-numbers {\"midSize\":1} /-->\n\n<!-- wp:query-pagination-next {\"style\":{\"typography\":{\"textDecoration\":\"none\"}}} /-->\n<!-- /wp:query-pagination --></div>\n<!-- /wp:query -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Почетна','','inherit','closed','closed','','80-revision-v1','','','2026-02-17 21:26:20','2026-02-17 21:26:20','',80,'https://user17.delovna.finki.ukim.mk/?p=2089',0,'revision','',0);
