 > a {\n  color: #fff !important;\n  padding: 12px 14px !important;\n  border-radius: 6px !important;\n  font-weight: 600 !important;\n}\n\n/* Dropdown hover */\n.main-header-menu .sub-menu .menu-item > a:hover,\n.main-header-menu .sub-menu .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n}\n\n\n/* =========================================================\n   ASTRA category/archive grid -> 2 columns (GLOBAL)\n   ========================================================= */\n\n/* container that holds the posts */\n.ast-blog-layout-4-grid .ast-row{\n  display: grid !important;\n  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n  gap: 28px !important;\n  align-items: stretch !important;\n}\n\n/* kill astra column widths / floats so grid works */\n.ast-blog-layout-4-grid .ast-row > article{\n  width: auto !important;\n  max-width: none !important;\n  margin: 0 !important;\n  float: none !important;\n}\n\n/* sometimes astra uses ast-grid-common-col wrappers */\n.ast-blog-layout-4-grid .ast-row > article.ast-grid-common-col{\n  width: auto !important;\n}\n\n/* mobile */\n@media (max-width: 768px){\n  .ast-blog-layout-4-grid .ast-row{\n    grid-template-columns: 1fr !important;\n    gap: 18px !important;\n  }\n}\n\n\n\n.rank-math-breadcrumb{\n  font-size:14px;\n  margin-bottom:16px;\n  opacity:.85;\n}\n\n.rank-math-breadcrumb a{\n  text-decoration:none;\n  color:#666;\n}\n\n.rank-math-breadcrumb a:hover{\n  color:#c62828;\n}\n\n','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-18 12:36:13','2026-02-18 12:36:13','',309,'https://user17.delovna.finki.ukim.mk/?p=2135',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2136,1,'2026-02-20 15:32:43','2026-02-20 15:32:43','<!-- wp:paragraph -->\n<p>In relation to external collaborators, the Cultural Center and Theater Kumanovo cooperate with graphic designers, costume designers, directors, and other professionals required for specific needs who are currently not employed as staff members at the Cultural Center and Theater Kumanovo.</p>\n<!-- /wp:paragraph -->','External Collaborators','','inherit','closed','closed','','133-revision-v1','','','2026-02-20 15:32:43','2026-02-20 15:32:43','',133,'https://user17.delovna.finki.ukim.mk/?p=2136',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2137,1,'2026-02-20 15:36:27','2026-02-20 15:36:27','<!-- wp:paragraph -->\n<p>At the Cultural Center, twelve stage workers are employed – including a senior stage technician – who provide technical support for events organized by the Cultural Center and Theater Kumanovo, as well as the Macedonian and Albanian drama ensembles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There are four cleaning staff members responsible for maintaining hygiene for all three entities within the Cultural Center, as well as one general maintenance worker.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There is a lighting technician and a sound technician for the Macedonian and Albanian drama ensembles, and a separate lighting technician and sound technician for the Cultural Center Kumanovo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There are also two employees responsible for visitor reception.</p>\n<!-- /wp:paragraph -->','Technical Department','','inherit','closed','closed','','137-revision-v1','','','2026-02-20 15:36:27','2026-02-20 15:36:27','',137,'https://user17.delovna.finki.ukim.mk/?p=2137',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2138,1,'2026-02-20 15:38:38','2026-02-20 15:38:38','<!-- wp:paragraph -->\n<p>All your suggestions, proposals, and feedback can be sent to our email address:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong><a>centarkult@gmail.com</a></strong></p>\n<!-- /wp:paragraph -->','Organizational Structure','','inherit','closed','closed','','141-revision-v1','','','2026-02-20 15:38:38','2026-02-20 15:38:38','',141,'https://user17.delovna.finki.ukim.mk/?p=2138',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2140,1,'2026-02-20 16:46:48','2026-02-20 16:46:48','/* =========================================================\n   1) Astra archive cards (ако некогаш користиш blog layout)\n   ========================================================= */\n\n.blog-layout-1 .ast-article-post {\n  background: #ffffff;\n  border: 3px solid transparent; /* за да нема скок на hover */\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n.blog-layout-1 .ast-article-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828; /* црвен акцент */\n  box-shadow: 0 14px 35px rgba(0,0,0,0.12);\n}\n\n.blog-layout-1 .post-thumb img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n.blog-layout-1 .entry-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.blog-layout-1 .entry-title a:hover {\n  color: #c62828;\n}\n\n/* Pagination */\n.ast-pagination a,\n.ast-pagination span {\n  padding: 10px 14px;\n  margin: 0 4px;\n  border-radius: 8px;\n  background: #f2f2f2;\n  color: #111;\n}\n\n.ast-pagination .current {\n  background: #c62828;\n  color: #fff;\n}\n\n\n/* =========================================================\n   2) Query Loop cards (ГЛАВНО — cards-equal wrapper)\n   ========================================================= */\n\n.cards-equal .wp-block-post {\n  background: #fff;\n  border: 3px solid transparent;   /* фиксна дебелина → нема layout shift */\n  border-radius: 12px;\n  overflow: hidden;\n  height: 100%;\n  display: flex;\n  box-shadow: 0 8px 24px rgba(0,0,0,0.06);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n/* Hover = приближување + црвен border */\n.cards-equal .wp-block-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828;\n  box-shadow: 0 14px 36px rgba(0,0,0,0.10);\n}\n\n/* Vertical layout inside card */\n.cards-equal .wp-block-post > div {\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Featured image — фиксна висина */\n.cards-equal .wp-block-post-featured-image img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n/* Content area */\n.cards-equal .wp-block-post-content {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  padding: 14px 16px;\n}\n\n/* Title */\n.cards-equal .wp-block-post-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.cards-equal .wp-block-post-title a:hover {\n  color: #c62828;\n}\n\n/* Excerpt долу */\n.cards-equal .wp-block-post-excerpt {\n  margin-top: auto;\n}\n\n\n/* =========================================================\n   3) Minimal sidebar (white/black + subtle red)\n   ========================================================= */\n\n.sidebar-main .widget,\n.ast-sidebar .widget,\n.widget-area .widget,\naside .widget {\n  background: #fff;\n  border: 1px solid rgba(0,0,0,0.08);\n  padding: 14px 14px;\n  margin-bottom: 18px;\n  box-shadow: none;\n}\n\n/* Lists reset */\n.sidebar-main .widget ul,\n.ast-sidebar .widget ul,\n.widget-area .widget ul,\naside .widget ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* Links */\n.sidebar-main .widget ul li a,\n.ast-sidebar .widget ul li a,\n.widget-area .widget ul li a,\naside .widget ul li a {\n  display: block;\n  padding: 10px 12px;\n  border-radius: 8px;\n  text-decoration: none;\n  font-weight: 600;\n  color: #111;\n  background: transparent;\n  transition: background .15s ease, color .15s ease;\n}\n\n/* Hover */\n.sidebar-main .widget ul li a:hover,\n.ast-sidebar .widget ul li a:hover,\n.widget-area .widget ul li a:hover,\naside .widget ul li a:hover {\n  background: rgba(0,0,0,0.035);\n}\n\n/* Active item — црвен accent bar */\n.sidebar-main .current-menu-item > a,\n.ast-sidebar .current-menu-item > a,\n.widget-area .current-menu-item > a,\naside .current-menu-item > a {\n  background: rgba(198,40,40,0.08);\n  color: #111;\n  border-left: 3px solid #c62828;\n  padding-left: 10px;\n}\n\n/* Rhythm */\n.sidebar-main .widget ul li,\n.ast-sidebar .widget ul li,\n.widget-area .widget ul li,\naside .widget ul li {\n  margin: 4px 0;\n}\n\n\n\n.map-btn {\n  text-decoration: none;\n  padding: 10px 16px;\n  border-radius: 6px;\n  background: #f2f2f2;\n  color: #222;\n  display: inline-block;\n  transition: 0.2s ease;\n}\n\n.map-btn:hover {\n	text-decoration: none;\n  color: #c62828;\n  background: #ffe5e5;\n}\n\n/* =========================================================\n   Query Loop Pagination (button style like screenshot)\n   ========================================================= */\n\n/* Wrapper */\n.wp-block-query-pagination{\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: nowrap; /* да не се крши во нов ред */\n  margin: 28px 0;\n}\n\n/* Make all items look like buttons */\n.wp-block-query-pagination a,\n.wp-block-query-pagination span{\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 36px;\n  height: 36px;\n  padding: 0 10px;\n  border-radius: 0;              /* квадратчиња */\n  background: #4a4a4a;           /* темно сиво */\n  color: #fff !important;\n  text-decoration: none !important;\n  font-weight: 700;\n  line-height: 1;\n  border: 1px solid rgba(0,0,0,0.18);\n  transition: transform .15s ease, filter .15s ease, background .15s ease;\n}\n\n/* Hover */\n.wp-block-query-pagination a:hover{\n  transform: translateY(-2px);\n  filter: brightness(1.08);\n}\n\n/* Current page */\n.wp-block-query-pagination .current{\n  background: #c62828;\n  border-color: #c62828;\n}\n\n/* Dots \"...\" */\n.wp-block-query-pagination .dots{\n  background: transparent;\n  border: 0;\n  color: #4a4a4a !important;\n  min-width: auto;\n  padding: 0 6px;\n}\n\n/* Prev / Next buttons */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  background: #4a4a4a;\n  color: #fff !important;\n  text-decoration: none !important;\n  white-space: nowrap; /* PREVIOUS PAGE да не се крши */\n}\n\n/* Ако сакаш PREV/NEXT да бидат малку пошироки */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  padding: 0 14px;\n}\n\n\n\n/* =========================================================\n   4) MAIN MENU / HEADER (black + red accent like screenshot)\n   ========================================================= */\n\n/* Background for header + nav area */\n#masthead,\n.site-header,\n.main-header-bar,\n.ast-primary-header-bar,\n.main-header-bar-wrap {\n  background: #0f0f0f !important;\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Remove Astra divider line under header */\n.ast-primary-header-bar,\n.main-header-bar {\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Menu item links */\n.main-header-menu > .menu-item > a {\n  color: #fff !important;\n  font-weight: 700;\n  text-decoration: none !important;\n  padding-top: 12px !important;     /* намали/зголеми по желба */\n  padding-bottom: 12px !important;\n  line-height: 1.2 !important;\n}\n\n/* Hover */\n.main-header-menu > .menu-item > a:hover,\n.main-header-menu > .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n  color: #fff !important;\n}\n\n/* Active/current item */\n.main-header-menu > .current-menu-item > a,\n.main-header-menu > .current-menu-ancestor > a {\n  background: #c62828 !important;\n  color: #fff !important;\n}\n\n/* Dropdown container */\n.main-header-menu .sub-menu {\n  background: #111 !important;\n  border: 0 !important;\n  border-radius: 8px !important;\n  padding: 8px !important;\n  box-shadow: 0 16px 40px rgba(0,0,0,0.35) !important;\n}\n\n/* Dropdown links */\n.main-header-menu .sub-menu .menu-item > a {\n  color: #fff !important;\n  padding: 12px 14px !important;\n  border-radius: 6px !important;\n  font-weight: 600 !important;\n}\n\n/* Dropdown hover */\n.main-header-menu .sub-menu .menu-item > a:hover,\n.main-header-menu .sub-menu .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n}\n\n\n/* =========================================================\n   ASTRA category/archive grid -> 2 columns (GLOBAL)\n   ========================================================= */\n\n/* container that holds the posts */\n.ast-blog-layout-4-grid .ast-row{\n  display: grid !important;\n  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n  gap: 28px !important;\n  align-items: stretch !important;\n}\n\n/* kill astra column widths / floats so grid works */\n.ast-blog-layout-4-grid .ast-row > article{\n  width: auto !important;\n  max-width: none !important;\n  margin: 0 !important;\n  float: none !important;\n}\n\n/* sometimes astra uses ast-grid-common-col wrappers */\n.ast-blog-layout-4-grid .ast-row > article.ast-grid-common-col{\n  width: auto !important;\n}\n\n/* mobile */\n@media (max-width: 768px){\n  .ast-blog-layout-4-grid .ast-row{\n    grid-template-columns: 1fr !important;\n    gap: 18px !important;\n  }\n}\n\n\n\n.rank-math-breadcrumb{\n  font-size:14px;\n  margin-bottom:16px;\n  opacity:.85;\n}\n\n.rank-math-breadcrumb a{\n  text-decoration:none;\n  color:#666;\n}\n\n.rank-math-breadcrumb a:hover{\n  color:#c62828;\n}\n\n\n/* Cards entrance animation (Astra archive grid) */\n.ast-archive-post,\n.ast-article-post {\n  opacity: 0;\n  transform: translateY(14px);\n  animation: cardIn .55s ease forwards;\n}\n\n/* Stagger (да не влегуваат сите одеднаш) */\n.ast-row article:nth-child(1) { animation-delay: .05s; }\n.ast-row article:nth-child(2) { animation-delay: .10s; }\n.ast-row article:nth-child(3) { animation-delay: .15s; }\n.ast-row article:nth-child(4) { animation-delay: .20s; }\n.ast-row article:nth-child(5) { animation-delay: .25s; }\n.ast-row article:nth-child(6) { animation-delay: .30s; }\n.ast-row article:nth-child(7) { animation-delay: .35s; }\n.ast-row article:nth-child(8) { animation-delay: .40s; }\n.ast-row article:nth-child(9) { animation-delay: .45s; }\n.ast-row article:nth-child(10){ animation-delay: .50s; }\n\n@keyframes cardIn {\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* Respect reduced motion */\n@media (prefers-reduced-motion: reduce){\n  .ast-archive-post,\n  .ast-article-post {\n    animation: none;\n    opacity: 1;\n    transform: none;\n  }\n}\n','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-20 16:46:48','2026-02-20 16:46:48','',309,'https://user17.delovna.finki.ukim.mk/?p=2140',0,'revision','',0);
