p-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  background: #4a4a4a;\n  color: #fff !important;\n  text-decoration: none !important;\n  white-space: nowrap; /* PREVIOUS PAGE да не се крши */\n}\n\n/* Ако сакаш PREV/NEXT да бидат малку пошироки */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  padding: 0 14px;\n}\n\n\n\n/* =========================================================\n   4) MAIN MENU / HEADER (black + red accent like screenshot)\n   ========================================================= */\n\n/* Background for header + nav area */\n#masthead,\n.site-header,\n.main-header-bar,\n.ast-primary-header-bar,\n.main-header-bar-wrap {\n  background: #0f0f0f !important;\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Remove Astra divider line under header */\n.ast-primary-header-bar,\n.main-header-bar {\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Menu item links */\n.main-header-menu > .menu-item > a {\n  color: #fff !important;\n  font-weight: 700;\n  text-decoration: none !important;\n  padding-top: 12px !important;     /* намали/зголеми по желба */\n  padding-bottom: 12px !important;\n  line-height: 1.2 !important;\n}\n\n/* Hover */\n.main-header-menu > .menu-item > a:hover,\n.main-header-menu > .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n  color: #fff !important;\n}\n\n/* Active/current item */\n.main-header-menu > .current-menu-item > a,\n.main-header-menu > .current-menu-ancestor > a {\n  background: #c62828 !important;\n  color: #fff !important;\n}\n\n/* Dropdown container */\n.main-header-menu .sub-menu {\n  background: #111 !important;\n  border: 0 !important;\n  border-radius: 8px !important;\n  padding: 8px !important;\n  box-shadow: 0 16px 40px rgba(0,0,0,0.35) !important;\n}\n\n/* Dropdown links */\n.main-header-menu .sub-menu .menu-item > a {\n  color: #fff !important;\n  padding: 12px 14px !important;\n  border-radius: 6px !important;\n  font-weight: 600 !important;\n}\n\n/* Dropdown hover */\n.main-header-menu .sub-menu .menu-item > a:hover,\n.main-header-menu .sub-menu .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n}\n\n\n/* =========================================================\n   ASTRA category/archive grid -> 2 columns (GLOBAL)\n   ========================================================= */\n\n/* container that holds the posts */\n.ast-blog-layout-4-grid .ast-row{\n  display: grid !important;\n  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n  gap: 28px !important;\n  align-items: stretch !important;\n}\n\n/* kill astra column widths / floats so grid works */\n.ast-blog-layout-4-grid .ast-row > article{\n  width: auto !important;\n  max-width: none !important;\n  margin: 0 !important;\n  float: none !important;\n}\n\n/* sometimes astra uses ast-grid-common-col wrappers */\n.ast-blog-layout-4-grid .ast-row > article.ast-grid-common-col{\n  width: auto !important;\n}\n\n/* mobile */\n@media (max-width: 768px){\n  .ast-blog-layout-4-grid .ast-row{\n    grid-template-columns: 1fr !important;\n    gap: 18px !important;\n  }\n}\n\n\n/* =====================================\n   FIRST LOAD HEADER ANIMATION\n===================================== */\n\n/* Header container */\nbody.first-load .ast-header-wrap{\n  opacity:0;\n  transform:translateY(-15px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.15s;\n}\n\n/* Logo */\nbody.first-load .site-branding{\n  opacity:0;\n  transform:translateY(-10px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.45s;\n}\n\n/* Header text */\nbody.first-load .ast-header-html{\n  opacity:0;\n  transform:translateY(-12px);\n  animation:headerTextFade .6s ease forwards;\n  animation-delay:.35s;\n}\n\n/* Menu items */\nbody.first-load .main-header-menu > li{\n  opacity:0;\n  transform:translateY(-8px);\n  animation:menuFadeIn .5s ease forwards;\n}\n\n/* stagger */\nbody.first-load .main-header-menu > li:nth-child(1){animation-delay:.65s;}\nbody.first-load .main-header-menu > li:nth-child(2){animation-delay:.75s;}\nbody.first-load .main-header-menu > li:nth-child(3){animation-delay:.85s;}\nbody.first-load .main-header-menu > li:nth-child(4){animation-delay:.95s;}\nbody.first-load .main-header-menu > li:nth-child(5){animation-delay:1.05s;}\nbody.first-load .main-header-menu > li:nth-child(6){animation-delay:1.15s;}\nbody.first-load .main-header-menu > li:nth-child(7){animation-delay:1.25s;}\nbody.first-load .main-header-menu > li:nth-child(8){animation-delay:1.35s;}\n\n/* =====================================\n   CARDS REVEAL (ALWAYS)\n===================================== */\n\n.cards-equal .wp-block-post{\n  opacity:0;\n  transform:translateY(25px);\n  animation:cardsEqualIn 1.05s cubic-bezier(.22,1,.36,1) forwards;\n}\n\n/* stagger reveal */\n.cards-equal .wp-block-post:nth-child(1){ animation-delay:.15s; }\n.cards-equal .wp-block-post:nth-child(2){ animation-delay:.30s; }\n.cards-equal .wp-block-post:nth-child(3){ animation-delay:.45s; }\n.cards-equal .wp-block-post:nth-child(4){ animation-delay:.60s; }\n.cards-equal .wp-block-post:nth-child(5){ animation-delay:.75s; }\n.cards-equal .wp-block-post:nth-child(6){ animation-delay:.90s; }\n.cards-equal .wp-block-post:nth-child(7){ animation-delay:1.05s; }\n.cards-equal .wp-block-post:nth-child(8){ animation-delay:1.20s; }\n.cards-equal .wp-block-post:nth-child(9){ animation-delay:1.35s; }\n\n/* =====================================\n   KEYFRAMES\n===================================== */\n\n@keyframes headerFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes headerTextFade{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes menuFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes cardsEqualIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n\n\n\n/* =====================================\n   SINGLE POST / PAGE SMOOTH REVEAL\n===================================== */\n\n/* За single post + pages */\nbody.single .site-content,\nbody.page .site-content{\n  opacity: 0;\n  transform: translateY(18px);\n  animation: contentIn .6s ease forwards;\n  animation-delay: .08s;\n}\n\n/* Малку побавно за насловот */\nbody.single .entry-header,\nbody.page .entry-header{\n  opacity: 0;\n  transform: translateY(12px);\n  animation: contentIn .55s ease forwards;\n  animation-delay: .18s;\n}\n\n/* Слика (ако има) */\nbody.single .post-thumb img,\nbody.page .post-thumb img{\n  opacity: 0;\n  transform: scale(0.98);\n  animation: imgIn .65s ease forwards;\n  animation-delay: .12s;\n}\n\n/* Keyframes */\n@keyframes contentIn{\n  to{\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@keyframes imgIn{\n  to{\n    opacity: 1;\n    transform: scale(1);\n  }\n}','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-20 17:18:35','2026-02-20 17:18:35','',309,'https://user17.delovna.finki.ukim.mk/?p=2158',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2161,1,'2026-02-20 19:43:49','2026-02-20 19:43:49','/* =========================================================\n   1) Astra archive cards (ако некогаш користиш blog layout)\n   ========================================================= */\n\n.blog-layout-1 .ast-article-post {\n  background: #ffffff;\n  border: 3px solid transparent; /* за да нема скок на hover */\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n.blog-layout-1 .ast-article-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828; /* црвен акцент */\n  box-shadow: 0 14px 35px rgba(0,0,0,0.12);\n}\n\n.blog-layout-1 .post-thumb img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n.blog-layout-1 .entry-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.blog-layout-1 .entry-title a:hover {\n  color: #c62828;\n}\n\n/* Pagination */\n.ast-pagination a,\n.ast-pagination span {\n  padding: 10px 14px;\n  margin: 0 4px;\n  border-radius: 8px;\n  background: #f2f2f2;\n  color: #111;\n}\n\n.ast-pagination .current {\n  background: #c62828;\n  color: #fff;\n}\n\n\n/* =========================================================\n   2) Query Loop cards (ГЛАВНО — cards-equal wrapper)\n   ========================================================= */\n\n.cards-equal .wp-block-post {\n  background: #fff;\n  border: 3px solid transparent;   /* фиксна дебелина → нема layout shift */\n  border-radius: 12px;\n  overflow: hidden;\n  height: 100%;\n  display: flex;\n  box-shadow: 0 8px 24px rgba(0,0,0,0.06);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n/* Hover = приближување + црвен border */\n.cards-equal .wp-block-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828;\n  box-shadow: 0 14px 36px rgba(0,0,0,0.10);\n}\n\n/* Vertical layout inside card */\n.cards-equal .wp-block-post > div {\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Featured image — фиксна висина */\n.cards-equal .wp-block-post-featured-image img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n/* Content area */\n.cards-equal .wp-block-post-content {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  padding: 14px 16px;\n}\n\n/* Title */\n.cards-equal .wp-block-post-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.cards-equal .wp-block-post-title a:hover {\n  color: #c62828;\n}\n\n/* Excerpt долу */\n.cards-equal .wp-block-post-excerpt {\n  margin-top: auto;\n}\n\n\n/* =========================================================\n   3) Minimal sidebar (white/black + subtle red)\n   ========================================================= */\n\n.sidebar-main .widget,\n.ast-sidebar .widget,\n.widget-area .widget,\naside .widget {\n  background: #fff;\n  border: 1px solid rgba(0,0,0,0.08);\n  padding: 14px 14px;\n  margin-bottom: 18px;\n  box-shadow: none;\n}\n\n/* Lists reset */\n.sidebar-main .widget ul,\n.ast-sidebar .widget ul,\n.widget-area .widget ul,\naside .widget ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* Links */\n.sidebar-main .widget ul li a,\n.ast-sidebar .widget ul li a,\n.widget-area .widget ul li a,\naside .widget ul li a {\n  display: block;\n  padding: 10px 12px;\n  border-radius: 8px;\n  text-decoration: none;\n  font-weight: 600;\n  color: #111;\n  background: transparent;\n  transition: background .15s ease, color .15s ease;\n}\n\n/* Hover */\n.sidebar-main .widget ul li a:hover,\n.ast-sidebar .widget ul li a:hover,\n.widget-area .widget ul li a:hover,\naside .widget ul li a:hover {\n  background: rgba(0,0,0,0.035);\n}\n\n/* Active item — црвен accent bar */\n.sidebar-main .current-menu-item > a,\n.ast-sidebar .current-menu-item > a,\n.widget-area .current-menu-item > a,\naside .current-menu-item > a {\n  background: rgba(198,40,40,0.08);\n  color: #111;\n  border-left: 3px solid #c62828;\n  padding-left: 10px;\n}\n\n/* Rhythm */\n.sidebar-main .widget ul li,\n.ast-sidebar .widget ul li,\n.widget-area .widget ul li,\naside .widget ul li {\n  margin: 4px 0;\n}\n\n\n\n.map-btn {\n  text-decoration: none;\n  padding: 10px 16px;\n  border-radius: 6px;\n  background: #f2f2f2;\n  color: #222;\n  display: inline-block;\n  transition: 0.2s ease;\n}\n\n.map-btn:hover {\n	text-decoration: none;\n  color: #c62828;\n  background: #ffe5e5;\n}\n\n/* =========================================================\n   Query Loop Pagination (button style like screenshot)\n   ========================================================= */\n\n/* Wrapper */\n.wp-block-query-pagination{\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: nowrap; /* да не се крши во нов ред */\n  margin: 28px 0;\n}\n\n/* Make all items look like buttons */\n.wp-block-query-pagination a,\n.wp-block-query-pagination span{\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 36px;\n  height: 36px;\n  padding: 0 10px;\n  border-radius: 0;              /* квадратчиња */\n  background: #4a4a4a;           /* темно сиво */\n  color: #fff !important;\n  text-decoration: none !important;\n  font-weight: 700;\n  line-height: 1;\n  border: 1px solid rgba(0,0,0,0.18);\n  transition: transform .15s ease, filter .15s ease, background .15s ease;\n}\n\n/* Hover */\n.wp-block-query-pagination a:hover{\n  transform: translateY(-2px);\n  filter: brightness(1.08);\n}\n\n/* Current page */\n.wp-block-query-pagination .current{\n  background: #c62828;\n  border-color: #c62828;\n}\n\n/* Dots \"...\" */\n.wp-block-query-pagination .dots{\n  background: transparent;\n  border: 0;\n  color: #4a4a4a !important;\n  min-width: auto;\n  padding: 0 6px;\n}\n\n/* Prev / Next buttons */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  background: #4a4a4a;\n  color: #fff !important;\n  text-decoration: none !important;\n  white-space: nowrap; /* PREVIOUS PAGE да не се крши */\n}\n\n/* Ако сакаш PREV/NEXT да бидат малку пошироки */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  padding: 0 14px;\n}\n\n\n\n/* =========================================================\n   4) MAIN MENU / HEADER (black + red accent like screenshot)\n   ========================================================= */\n\n/* Background for header + nav area */\n#masthead,\n.site-header,\n.main-header-bar,\n.ast-primary-header-bar,\n.main-header-bar-wrap {\n  background: #0f0f0f !important;\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Remove Astra divider line under header */\n.ast-primary-header-bar,\n.main-header-bar {\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Menu item links */\n.main-header-menu > .menu-item > a {\n  color: #fff !important;\n  font-weight: 700;\n  text-decoration: none !important;\n  padding-top: 12px !important;     /* намали/зголеми по желба */\n  padding-bottom: 12px !important;\n  line-height: 1.2 !important;\n}\n\n/* Hover */\n.main-header-menu > .menu-item > a:hover,\n.main-header-menu > .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n  color: #fff !important;\n}\n\n/* Active/current item */\n.main-header-menu > .current-menu-item > a,\n.main-header-menu > .current-menu-ancestor > a {\n  background: #c62828 !important;\n  color: #fff !important;\n}\n\n/* Dropdown container */\n.main-header-menu .sub-menu {\n  background: #111 !important;\n  border: 0 !important;\n  border-radius: 8px !important;\n  padding: 8px !important;\n  box-shadow: 0 16px 40px rgba(0,0,0,0.35) !important;\n}\n\n/* Dropdown links */\n.main-header-menu .sub-menu .menu-item > a {\n  color: #fff !important;\n  padding: 12px 14px !important;\n  border-radius: 6px !important;\n  font-weight: 600 !important;\n}\n\n/* Dropdown hover */\n.main-header-menu .sub-menu .menu-item > a:hover,\n.main-header-menu .sub-menu .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n}\n\n\n/* =========================================================\n   ASTRA category/archive grid -> 2 columns (GLOBAL)\n   ========================================================= */\n\n/* container that holds the posts */\n.ast-blog-layout-4-grid .ast-row{\n  display: grid !important;\n  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n  gap: 28px !important;\n  align-items: stretch !important;\n}\n\n/* kill astra column widths / floats so grid works */\n.ast-blog-layout-4-grid .ast-row > article{\n  width: auto !important;\n  max-width: none !important;\n  margin: 0 !important;\n  float: none !important;\n}\n\n/* sometimes astra uses ast-grid-common-col wrappers */\n.ast-blog-layout-4-grid .ast-row > article.ast-grid-common-col{\n  width: auto !important;\n}\n\n/* mobile */\n@media (max-width: 768px){\n  .ast-blog-layout-4-grid .ast-row{\n    grid-template-columns: 1fr !important;\n    gap: 18px !important;\n  }\n}\n\n\n/* =====================================\n   FIRST LOAD HEADER ANIMATION\n===================================== */\n\n/* Header container */\nbody.first-load .ast-header-wrap{\n  opacity:0;\n  transform:translateY(-15px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.15s;\n}\n\n/* Logo */\nbody.first-load .site-branding{\n  opacity:0;\n  transform:translateY(-10px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.45s;\n}\n\n/* Header text */\nbody.first-load .ast-header-html{\n  opacity:0;\n  transform:translateY(-12px);\n  animation:headerTextFade .6s ease forwards;\n  animation-delay:.35s;\n}\n\n/* Menu items */\nbody.first-load .main-header-menu > li{\n  opacity:0;\n  transform:translateY(-8px);\n  animation:menuFadeIn .5s ease forwards;\n}\n\n/* stagger */\nbody.first-load .main-header-menu > li:nth-child(1){animation-delay:.65s;}\nbody.first-load .main-header-menu > li:nth-child(2){animation-delay:.75s;}\nbody.first-load .main-header-menu > li:nth-child(3){animation-delay:.85s;}\nbody.first-load .main-header-menu > li:nth-child(4){animation-delay:.95s;}\nbody.first-load .main-header-menu > li:nth-child(5){animation-delay:1.05s;}\nbody.first-load .main-header-menu > li:nth-child(6){animation-delay:1.15s;}\nbody.first-load .main-header-menu > li:nth-child(7){animation-delay:1.25s;}\nbody.first-load .main-header-menu > li:nth-child(8){animation-delay:1.35s;}\n\n/* =====================================\n   CARDS REVEAL (ALWAYS)\n===================================== */\n\n.cards-equal .wp-block-post{\n  opacity:0;\n  transform:translateY(25px);\n  animation:cardsEqualIn 1.05s cubic-bezier(.22,1,.36,1) forwards;\n}\n\n/* stagger reveal */\n.cards-equal .wp-block-post:nth-child(1){ animation-delay:.15s; }\n.cards-equal .wp-block-post:nth-child(2){ animation-delay:.30s; }\n.cards-equal .wp-block-post:nth-child(3){ animation-delay:.45s; }\n.cards-equal .wp-block-post:nth-child(4){ animation-delay:.60s; }\n.cards-equal .wp-block-post:nth-child(5){ animation-delay:.75s; }\n.cards-equal .wp-block-post:nth-child(6){ animation-delay:.90s; }\n.cards-equal .wp-block-post:nth-child(7){ animation-delay:1.05s; }\n.cards-equal .wp-block-post:nth-child(8){ animation-delay:1.20s; }\n.cards-equal .wp-block-post:nth-child(9){ animation-delay:1.35s; }\n\n/* =====================================\n   KEYFRAMES\n===================================== */\n\n@keyframes headerFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes headerTextFade{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes menuFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes cardsEqualIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n\n\n\n/* =====================================\n   SINGLE POST / PAGE SMOOTH REVEAL\n===================================== */\n\n/* За single post + pages */\nbody.single .site-content,\nbody.page .site-content{\n  opacity: 0;\n  transform: translateY(18px);\n  animation: contentIn .6s ease forwards;\n  animation-delay: .08s;\n}\n\n/* Малку побавно за насловот */\nbody.single .entry-header,\nbody.page .entry-header{\n  opacity: 0;\n  transform: translateY(12px);\n  animation: contentIn .55s ease forwards;\n  animation-delay: .18s;\n}\n\n/* Слика (ако има) */\nbody.single .post-thumb img,\nbody.page .post-thumb img{\n  opacity: 0;\n  transform: scale(0.98);\n  animation: imgIn .65s ease forwards;\n  animation-delay: .12s;\n}\n\n/* Keyframes */\n@keyframes contentIn{\n  to{\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@keyframes imgIn{\n  to{\n    opacity: 1;\n    transform: scale(1);\n  }\n}\n\n\n\n\n/* =========================\n   FOOTER MINIMAL STYLE\n========================= */\n\n.site-footer{\n    background:#111;\n    color:#fff;\n    border-top:3px solid #c62828;\n}\n\n.site-footer a{\n    color:#fff;\n    text-decoration:none;\n    transition:.2s ease;\n}\n\n.site-footer a:hover{\n    color:#c62828;\n}\n\n/* footer columns spacing */\n.footer-widget-area{\n    padding:40px 0;\n}\n\n/* titles */\n.site-footer strong{\n    font-size:16px;\n    letter-spacing:.5px;\n}\n\n/* social icons */\n.footer-social-inner-wrap a{\n    background:#222;\n    border-radius:6px;\n    padding:8px;\n}\n\n.footer-social-inner-wrap a:hover{\n    background:#c62828;\n}\n\n/* copyright line */\n.ast-footer-copyright{\n    border-top:1px solid rgba(255,255,255,.1);\n    padding-top:12px;\n    margin-top:20px;\n    font-size:13px;\n}','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-20 19:43:49','2026-02-20 19:43:49','',309,'https://user17.delovna.finki.ukim.mk/?p=2161',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2165,1,'2026-02-20 19:49:45','2026-02-20 19:49:45','/* =========================================================\n   1) Astra archive cards (ако некогаш користиш blog layout)\n   ========================================================= */\n\n.blog-layout-1 .ast-article-post {\n  background: #ffffff;\n  border: 3px solid transparent; /* за да нема скок на hover */\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n.blog-layout-1 .ast-article-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828; /* црвен акцент */\n  box-shadow: 0 14px 35px rgba(0,0,0,0.12);\n}\n\n.blog-layout-1 .post-thumb img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n.blog-layout-1 .entry-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.blog-layout-1 .entry-title a:hover {\n  color: #c62828;\n}\n\n/* Pagination */\n.ast-pagination a,\n.ast-pagination span {\n  padding: 10px 14px;\n  margin: 0 4px;\n  border-radius: 8px;\n  background: #f2f2f2;\n  color: #111;\n}\n\n.ast-pagination .current {\n  background: #c62828;\n  color: #fff;\n}\n\n\n/* =========================================================\n   2) Query Loop cards (ГЛАВНО — cards-equal wrapper)\n   ========================================================= */\n\n.cards-equal .wp-block-post {\n  background: #fff;\n  border: 3px solid transparent;   /* фиксна дебелина → нема layout shift */\n  border-radius: 12px;\n  overflow: hidden;\n  height: 100%;\n  display: flex;\n  box-shadow: 0 8px 24px rgba(0,0,0,0.06);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n/* Hover = приближување + црвен border */\n.cards-equal .wp-block-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828;\n  box-shadow: 0 14px 36px rgba(0,0,0,0.10);\n}\n\n/* Vertical layout inside card */\n.cards-equal .wp-block-post > div {\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Featured image — фиксна висина */\n.cards-equal .wp-block-post-featured-image img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n/* Content area */\n.cards-equal .wp-block-post-content {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  padding: 14px 16px;\n}\n\n/* Title */\n.cards-equal .wp-block-post-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.cards-equal .wp-block-post-title a:hover {\n  color: #c62828;\n}\n\n/* Excerpt долу */\n.cards-equal .wp-block-post-excerpt {\n  margin-top: auto;\n}\n\n\n/* =========================================================\n   3) Minimal sidebar (white/black + subtle red)\n   ========================================================= */\n\n.sidebar-main .widget,\n.ast-sidebar .widget,\n.widget-area .widget,\naside .widget {\n  background: #fff;\n  border: 1px solid rgba(0,0,0,0.08);\n  padding: 14px 14px;\n  margin-bottom: 18px;\n  box-shadow: none;\n}\n\n/* Lists reset */\n.sidebar-main .widget ul,\n.ast-sidebar .widget ul,\n.widget-area .widget ul,\naside .widget ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* Links */\n.sidebar-main .widget ul li a,\n.ast-sidebar .widget ul li a,\n.widget-area .widget ul li a,\naside .widget ul li a {\n  display: block;\n  padding: 10px 12px;\n  border-radius: 8px;\n  text-decoration: none;\n  font-weight: 600;\n  color: #111;\n  background: transparent;\n  transition: background .15s ease, color .15s ease;\n}\n\n/* Hover */\n.sidebar-main .widget ul li a:hover,\n.ast-sidebar .widget ul li a:hover,\n.widget-area .widget ul li a:hover,\naside .widget ul li a:hover {\n  background: rgba(0,0,0,0.035);\n}\n\n/* Active item — црвен accent bar */\n.sidebar-main .current-menu-item > a,\n.ast-sidebar .current-menu-item > a,\n.widget-area .current-menu-item > a,\naside .current-menu-item > a {\n  background: rgba(198,40,40,0.08);\n  color: #111;\n  border-left: 3px solid #c62828;\n  padding-left: 10px;\n}\n\n/* Rhythm */\n.sidebar-main .widget ul li,\n.ast-sidebar .widget ul li,\n.widget-area .widget ul li,\naside .widget ul li {\n  margin: 4px 0;\n}\n\n\n\n.map-btn {\n  text-decoration: none;\n  padding: 10px 16px;\n  border-radius: 6px;\n  background: #f2f2f2;\n  color: #222;\n  display: inline-block;\n  transition: 0.2s ease;\n}\n\n.map-btn:hover {\n	text-decoration: none;\n  color: #c62828;\n  background: #ffe5e5;\n}\n\n/* =========================================================\n   Query Loop Pagination (button style like screenshot)\n   ========================================================= */\n\n/* Wrapper */\n.wp-block-query-pagination{\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: nowrap; /* да не се крши во нов ред */\n  margin: 28px 0;\n}\n\n/* Make all items look like buttons */\n.wp-block-query-pagination a,\n.wp-block-query-pagination span{\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 36px;\n  height: 36px;\n  padding: 0 10px;\n  border-radius: 0;              /* квадратчиња */\n  background: #4a4a4a;           /* темно сиво */\n  color: #fff !important;\n  text-decoration: none !important;\n  font-weight: 700;\n  line-height: 1;\n  border: 1px solid rgba(0,0,0,0.18);\n  transition: transform .15s ease, filter .15s ease, background .15s ease;\n}\n\n/* Hover */\n.wp-block-query-pagination a:hover{\n  transform: translateY(-2px);\n  filter: brightness(1.08);\n}\n\n/* Current page */\n.wp-block-query-pagination .current{\n  background: #c62828;\n  border-color: #c62828;\n}\n\n/* Dots \"...\" */\n.wp-block-query-pagination .dots{\n  background: transparent;\n  border: 0;\n  color: #4a4a4a !important;\n  min-width: auto;\n  padding: 0 6px;\n}\n\n/* Prev / Next buttons */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  background: #4a4a4a;\n  color: #fff !important;\n  text-decoration: none !important;\n  white-space: nowrap; /* PREVIOUS PAGE да не се крши */\n}\n\n/* Ако сакаш PREV/NEXT да бидат малку пошироки */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  padding: 0 14px;\n}\n\n\n\n/* =========================================================\n   4) MAIN MENU / HEADER (black + red accent like screenshot)\n   ========================================================= */\n\n/* Background for header + nav area */\n#masthead,\n.site-header,\n.main-header-bar,\n.ast-primary-header-bar,\n.main-header-bar-wrap {\n  background: #0f0f0f !important;\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Remove Astra divider line under header */\n.ast-primary-header-bar,\n.main-header-bar {\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Menu item links */\n.main-header-menu > .menu-item > a {\n  color: #fff !important;\n  font-weight: 700;\n  text-decoration: none !important;\n  padding-top: 12px !important;     /* намали/зголеми по желба */\n  padding-bottom: 12px !important;\n  line-height: 1.2 !important;\n}\n\n/* Hover */\n.main-header-menu > .menu-item > a:hover,\n.main-header-menu > .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n  color: #fff !important;\n}\n\n/* Active/current item */\n.main-header-menu > .current-menu-item > a,\n.main-header-menu > .current-menu-ancestor > a {\n  background: #c62828 !important;\n  color: #fff !important;\n}\n\n/* Dropdown container */\n.main-header-menu .sub-menu {\n  background: #111 !important;\n  border: 0 !important;\n  border-radius: 8px !important;\n  padding: 8px !important;\n  box-shadow: 0 16px 40px rgba(0,0,0,0.35) !important;\n}\n\n/* Dropdown links */\n.main-header-menu .sub-menu .menu-item > a {\n  color: #fff !important;\n  padding: 12px 14px !important;\n  border-radius: 6px !important;\n  font-weight: 600 !important;\n}\n\n/* Dropdown hover */\n.main-header-menu .sub-menu .menu-item > a:hover,\n.main-header-menu .sub-menu .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n}\n\n\n/* =========================================================\n   ASTRA category/archive grid -> 2 columns (GLOBAL)\n   ========================================================= */\n\n/* container that holds the posts */\n.ast-blog-layout-4-grid .ast-row{\n  display: grid !important;\n  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n  gap: 28px !important;\n  align-items: stretch !important;\n}\n\n/* kill astra column widths / floats so grid works */\n.ast-blog-layout-4-grid .ast-row > article{\n  width: auto !important;\n  max-width: none !important;\n  margin: 0 !important;\n  float: none !important;\n}\n\n/* sometimes astra uses ast-grid-common-col wrappers */\n.ast-blog-layout-4-grid .ast-row > article.ast-grid-common-col{\n  width: auto !important;\n}\n\n/* mobile */\n@media (max-width: 768px){\n  .ast-blog-layout-4-grid .ast-row{\n    grid-template-columns: 1fr !important;\n    gap: 18px !important;\n  }\n}\n\n\n/* =====================================\n   FIRST LOAD HEADER ANIMATION\n===================================== */\n\n/* Header container */\nbody.first-load .ast-header-wrap{\n  opacity:0;\n  transform:translateY(-15px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.15s;\n}\n\n/* Logo */\nbody.first-load .site-branding{\n  opacity:0;\n  transform:translateY(-10px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.45s;\n}\n\n/* Header text */\nbody.first-load .ast-header-html{\n  opacity:0;\n  transform:translateY(-12px);\n  animation:headerTextFade .6s ease forwards;\n  animation-delay:.35s;\n}\n\n/* Menu items */\nbody.first-load .main-header-menu > li{\n  opacity:0;\n  transform:translateY(-8px);\n  animation:menuFadeIn .5s ease forwards;\n}\n\n/* stagger */\nbody.first-load .main-header-menu > li:nth-child(1){animation-delay:.65s;}\nbody.first-load .main-header-menu > li:nth-child(2){animation-delay:.75s;}\nbody.first-load .main-header-menu > li:nth-child(3){animation-delay:.85s;}\nbody.first-load .main-header-menu > li:nth-child(4){animation-delay:.95s;}\nbody.first-load .main-header-menu > li:nth-child(5){animation-delay:1.05s;}\nbody.first-load .main-header-menu > li:nth-child(6){animation-delay:1.15s;}\nbody.first-load .main-header-menu > li:nth-child(7){animation-delay:1.25s;}\nbody.first-load .main-header-menu > li:nth-child(8){animation-delay:1.35s;}\n\n/* =====================================\n   CARDS REVEAL (ALWAYS)\n===================================== */\n\n.cards-equal .wp-block-post{\n  opacity:0;\n  transform:translateY(25px);\n  animation:cardsEqualIn 1.05s cubic-bezier(.22,1,.36,1) forwards;\n}\n\n/* stagger reveal */\n.cards-equal .wp-block-post:nth-child(1){ animation-delay:.15s; }\n.cards-equal .wp-block-post:nth-child(2){ animation-delay:.30s; }\n.cards-equal .wp-block-post:nth-child(3){ animation-delay:.45s; }\n.cards-equal .wp-block-post:nth-child(4){ animation-delay:.60s; }\n.cards-equal .wp-block-post:nth-child(5){ animation-delay:.75s; }\n.cards-equal .wp-block-post:nth-child(6){ animation-delay:.90s; }\n.cards-equal .wp-block-post:nth-child(7){ animation-delay:1.05s; }\n.cards-equal .wp-block-post:nth-child(8){ animation-delay:1.20s; }\n.cards-equal .wp-block-post:nth-child(9){ animation-delay:1.35s; }\n\n/* =====================================\n   KEYFRAMES\n===================================== */\n\n@keyframes headerFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes headerTextFade{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes menuFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes cardsEqualIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n\n\n\n/* =====================================\n   SINGLE POST / PAGE SMOOTH REVEAL\n===================================== */\n\n/* За single post + pages */\nbody.single .site-content,\nbody.page .site-content{\n  opacity: 0;\n  transform: translateY(18px);\n  animation: contentIn .6s ease forwards;\n  animation-delay: .08s;\n}\n\n/* Малку побавно за насловот */\nbody.single .entry-header,\nbody.page .entry-header{\n  opacity: 0;\n  transform: translateY(12px);\n  animation: contentIn .55s ease forwards;\n  animation-delay: .18s;\n}\n\n/* Слика (ако има) */\nbody.single .post-thumb img,\nbody.page .post-thumb img{\n  opacity: 0;\n  transform: scale(0.98);\n  animation: imgIn .65s ease forwards;\n  animation-delay: .12s;\n}\n\n/* Keyframes */\n@keyframes contentIn{\n  to{\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@keyframes imgIn{\n  to{\n    opacity: 1;\n    transform: scale(1);\n  }\n}\n\n\n\n\n/* =========================\n   FOOTER MINIMAL STYLE\n========================= */\n\n.site-footer{\n    background:#111;\n    color:#fff;\n    border-top:3px solid #c62828;\n}\n\n.site-footer a{\n    color:#fff;\n    text-decoration:none;\n    transition:.2s ease;\n}\n\n.site-footer a:hover{\n    color:#c62828;\n}\n\n/* footer columns spacing */\n.footer-widget-area{\n    padding:40px 0;\n}\n\n/* titles */\n.site-footer strong{\n    font-size:16px;\n    letter-spacing:.5px;\n}\n\n/* social icons */\n.footer-social-inner-wrap a{\n    background:#222;\n    border-radius:6px;\n    padding:8px;\n}\n\n.footer-social-inner-wrap a:hover{\n    background:#c62828;\n}\n\n/* copyright line */\n.ast-footer-copyright{\n    border-top:1px solid rgba(255,255,255,.1);\n    padding-top:12px;\n    margin-top:20px;\n    font-size:13px;\n}\n\n\n\n/* ======================\n   CENTER FOOTER SOCIAL\n====================== */\n\n/* footer social container */\n.footer-social-inner,\n.ast-footer-social-wrap,\n.ast-footer-social{\n    width:100%;\n    display:flex;\n    justify-content:center !important;\n    align-items:center;\n}\n\n/* buttons spacing */\n.ast-footer-social-wrap a{\n    margin:0 8px;\n}\n\n/* optional smooth hover */\n.ast-footer-social-wrap a:hover{\n    transform:translateY(-2px);\n    transition:0.2s ease;\n}','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-20 19:49:45','2026-02-20 19:49:45','',309,'https://user17.delovna.finki.ukim.mk/?p=2165',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2167,1,'2026-02-20 19:53:25','2026-02-20 19:53:25','/* =========================================================\n   1) Astra archive cards (ако некогаш користиш blog layout)\n   ========================================================= */\n\n.blog-layout-1 .ast-article-post {\n  background: #ffffff;\n  border: 3px solid transparent; /* за да нема скок на hover */\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 8px 25px rgba(0,0,0,0.08);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n.blog-layout-1 .ast-article-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828; /* црвен акцент */\n  box-shadow: 0 14px 35px rgba(0,0,0,0.12);\n}\n\n.blog-layout-1 .post-thumb img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n.blog-layout-1 .entry-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.blog-layout-1 .entry-title a:hover {\n  color: #c62828;\n}\n\n/* Pagination */\n.ast-pagination a,\n.ast-pagination span {\n  padding: 10px 14px;\n  margin: 0 4px;\n  border-radius: 8px;\n  background: #f2f2f2;\n  color: #111;\n}\n\n.ast-pagination .current {\n  background: #c62828;\n  color: #fff;\n}\n\n\n/* =========================================================\n   2) Query Loop cards (ГЛАВНО — cards-equal wrapper)\n   ========================================================= */\n\n.cards-equal .wp-block-post {\n  background: #fff;\n  border: 3px solid transparent;   /* фиксна дебелина → нема layout shift */\n  border-radius: 12px;\n  overflow: hidden;\n  height: 100%;\n  display: flex;\n  box-shadow: 0 8px 24px rgba(0,0,0,0.06);\n  transition: transform 0.20s ease, box-shadow 0.20s ease, border-color 0.20s ease;\n  will-change: transform;\n}\n\n/* Hover = приближување + црвен border */\n.cards-equal .wp-block-post:hover {\n  transform: translateY(-6px) scale(1.01);\n  border-color: #c62828;\n  box-shadow: 0 14px 36px rgba(0,0,0,0.10);\n}\n\n/* Vertical layout inside card */\n.cards-equal .wp-block-post > div {\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Featured image — фиксна висина */\n.cards-equal .wp-block-post-featured-image img {\n  width: 100%;\n  height: 260px;\n  object-fit: cover;\n  display: block;\n}\n\n/* Content area */\n.cards-equal .wp-block-post-content {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  padding: 14px 16px;\n}\n\n/* Title */\n.cards-equal .wp-block-post-title a {\n  color: #111;\n  text-decoration: none;\n}\n\n.cards-equal .wp-block-post-title a:hover {\n  color: #c62828;\n}\n\n/* Excerpt долу */\n.cards-equal .wp-block-post-excerpt {\n  margin-top: auto;\n}\n\n\n/* =========================================================\n   3) Minimal sidebar (white/black + subtle red)\n   ========================================================= */\n\n.sidebar-main .widget,\n.ast-sidebar .widget,\n.widget-area .widget,\naside .widget {\n  background: #fff;\n  border: 1px solid rgba(0,0,0,0.08);\n  padding: 14px 14px;\n  margin-bottom: 18px;\n  box-shadow: none;\n}\n\n/* Lists reset */\n.sidebar-main .widget ul,\n.ast-sidebar .widget ul,\n.widget-area .widget ul,\naside .widget ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* Links */\n.sidebar-main .widget ul li a,\n.ast-sidebar .widget ul li a,\n.widget-area .widget ul li a,\naside .widget ul li a {\n  display: block;\n  padding: 10px 12px;\n  border-radius: 8px;\n  text-decoration: none;\n  font-weight: 600;\n  color: #111;\n  background: transparent;\n  transition: background .15s ease, color .15s ease;\n}\n\n/* Hover */\n.sidebar-main .widget ul li a:hover,\n.ast-sidebar .widget ul li a:hover,\n.widget-area .widget ul li a:hover,\naside .widget ul li a:hover {\n  background: rgba(0,0,0,0.035);\n}\n\n/* Active item — црвен accent bar */\n.sidebar-main .current-menu-item > a,\n.ast-sidebar .current-menu-item > a,\n.widget-area .current-menu-item > a,\naside .current-menu-item > a {\n  background: rgba(198,40,40,0.08);\n  color: #111;\n  border-left: 3px solid #c62828;\n  padding-left: 10px;\n}\n\n/* Rhythm */\n.sidebar-main .widget ul li,\n.ast-sidebar .widget ul li,\n.widget-area .widget ul li,\naside .widget ul li {\n  margin: 4px 0;\n}\n\n\n\n.map-btn {\n  text-decoration: none;\n  padding: 10px 16px;\n  border-radius: 6px;\n  background: #f2f2f2;\n  color: #222;\n  display: inline-block;\n  transition: 0.2s ease;\n}\n\n.map-btn:hover {\n	text-decoration: none;\n  color: #c62828;\n  background: #ffe5e5;\n}\n\n/* =========================================================\n   Query Loop Pagination (button style like screenshot)\n   ========================================================= */\n\n/* Wrapper */\n.wp-block-query-pagination{\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: nowrap; /* да не се крши во нов ред */\n  margin: 28px 0;\n}\n\n/* Make all items look like buttons */\n.wp-block-query-pagination a,\n.wp-block-query-pagination span{\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 36px;\n  height: 36px;\n  padding: 0 10px;\n  border-radius: 0;              /* квадратчиња */\n  background: #4a4a4a;           /* темно сиво */\n  color: #fff !important;\n  text-decoration: none !important;\n  font-weight: 700;\n  line-height: 1;\n  border: 1px solid rgba(0,0,0,0.18);\n  transition: transform .15s ease, filter .15s ease, background .15s ease;\n}\n\n/* Hover */\n.wp-block-query-pagination a:hover{\n  transform: translateY(-2px);\n  filter: brightness(1.08);\n}\n\n/* Current page */\n.wp-block-query-pagination .current{\n  background: #c62828;\n  border-color: #c62828;\n}\n\n/* Dots \"...\" */\n.wp-block-query-pagination .dots{\n  background: transparent;\n  border: 0;\n  color: #4a4a4a !important;\n  min-width: auto;\n  padding: 0 6px;\n}\n\n/* Prev / Next buttons */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  background: #4a4a4a;\n  color: #fff !important;\n  text-decoration: none !important;\n  white-space: nowrap; /* PREVIOUS PAGE да не се крши */\n}\n\n/* Ако сакаш PREV/NEXT да бидат малку пошироки */\n.wp-block-query-pagination .wp-block-query-pagination-previous,\n.wp-block-query-pagination .wp-block-query-pagination-next{\n  padding: 0 14px;\n}\n\n\n\n/* =========================================================\n   4) MAIN MENU / HEADER (black + red accent like screenshot)\n   ========================================================= */\n\n/* Background for header + nav area */\n#masthead,\n.site-header,\n.main-header-bar,\n.ast-primary-header-bar,\n.main-header-bar-wrap {\n  background: #0f0f0f !important;\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Remove Astra divider line under header */\n.ast-primary-header-bar,\n.main-header-bar {\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n}\n\n/* Menu item links */\n.main-header-menu > .menu-item > a {\n  color: #fff !important;\n  font-weight: 700;\n  text-decoration: none !important;\n  padding-top: 12px !important;     /* намали/зголеми по желба */\n  padding-bottom: 12px !important;\n  line-height: 1.2 !important;\n}\n\n/* Hover */\n.main-header-menu > .menu-item > a:hover,\n.main-header-menu > .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n  color: #fff !important;\n}\n\n/* Active/current item */\n.main-header-menu > .current-menu-item > a,\n.main-header-menu > .current-menu-ancestor > a {\n  background: #c62828 !important;\n  color: #fff !important;\n}\n\n/* Dropdown container */\n.main-header-menu .sub-menu {\n  background: #111 !important;\n  border: 0 !important;\n  border-radius: 8px !important;\n  padding: 8px !important;\n  box-shadow: 0 16px 40px rgba(0,0,0,0.35) !important;\n}\n\n/* Dropdown links */\n.main-header-menu .sub-menu .menu-item > a {\n  color: #fff !important;\n  padding: 12px 14px !important;\n  border-radius: 6px !important;\n  font-weight: 600 !important;\n}\n\n/* Dropdown hover */\n.main-header-menu .sub-menu .menu-item > a:hover,\n.main-header-menu .sub-menu .menu-item > a:focus {\n  background: rgba(198,40,40,0.22) !important;\n}\n\n\n/* =========================================================\n   ASTRA category/archive grid -> 2 columns (GLOBAL)\n   ========================================================= */\n\n/* container that holds the posts */\n.ast-blog-layout-4-grid .ast-row{\n  display: grid !important;\n  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n  gap: 28px !important;\n  align-items: stretch !important;\n}\n\n/* kill astra column widths / floats so grid works */\n.ast-blog-layout-4-grid .ast-row > article{\n  width: auto !important;\n  max-width: none !important;\n  margin: 0 !important;\n  float: none !important;\n}\n\n/* sometimes astra uses ast-grid-common-col wrappers */\n.ast-blog-layout-4-grid .ast-row > article.ast-grid-common-col{\n  width: auto !important;\n}\n\n/* mobile */\n@media (max-width: 768px){\n  .ast-blog-layout-4-grid .ast-row{\n    grid-template-columns: 1fr !important;\n    gap: 18px !important;\n  }\n}\n\n\n/* =====================================\n   FIRST LOAD HEADER ANIMATION\n===================================== */\n\n/* Header container */\nbody.first-load .ast-header-wrap{\n  opacity:0;\n  transform:translateY(-15px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.15s;\n}\n\n/* Logo */\nbody.first-load .site-branding{\n  opacity:0;\n  transform:translateY(-10px);\n  animation:headerFadeIn .6s ease forwards;\n  animation-delay:.45s;\n}\n\n/* Header text */\nbody.first-load .ast-header-html{\n  opacity:0;\n  transform:translateY(-12px);\n  animation:headerTextFade .6s ease forwards;\n  animation-delay:.35s;\n}\n\n/* Menu items */\nbody.first-load .main-header-menu > li{\n  opacity:0;\n  transform:translateY(-8px);\n  animation:menuFadeIn .5s ease forwards;\n}\n\n/* stagger */\nbody.first-load .main-header-menu > li:nth-child(1){animation-delay:.65s;}\nbody.first-load .main-header-menu > li:nth-child(2){animation-delay:.75s;}\nbody.first-load .main-header-menu > li:nth-child(3){animation-delay:.85s;}\nbody.first-load .main-header-menu > li:nth-child(4){animation-delay:.95s;}\nbody.first-load .main-header-menu > li:nth-child(5){animation-delay:1.05s;}\nbody.first-load .main-header-menu > li:nth-child(6){animation-delay:1.15s;}\nbody.first-load .main-header-menu > li:nth-child(7){animation-delay:1.25s;}\nbody.first-load .main-header-menu > li:nth-child(8){animation-delay:1.35s;}\n\n/* =====================================\n   CARDS REVEAL (ALWAYS)\n===================================== */\n\n.cards-equal .wp-block-post{\n  opacity:0;\n  transform:translateY(25px);\n  animation:cardsEqualIn 1.05s cubic-bezier(.22,1,.36,1) forwards;\n}\n\n/* stagger reveal */\n.cards-equal .wp-block-post:nth-child(1){ animation-delay:.15s; }\n.cards-equal .wp-block-post:nth-child(2){ animation-delay:.30s; }\n.cards-equal .wp-block-post:nth-child(3){ animation-delay:.45s; }\n.cards-equal .wp-block-post:nth-child(4){ animation-delay:.60s; }\n.cards-equal .wp-block-post:nth-child(5){ animation-delay:.75s; }\n.cards-equal .wp-block-post:nth-child(6){ animation-delay:.90s; }\n.cards-equal .wp-block-post:nth-child(7){ animation-delay:1.05s; }\n.cards-equal .wp-block-post:nth-child(8){ animation-delay:1.20s; }\n.cards-equal .wp-block-post:nth-child(9){ animation-delay:1.35s; }\n\n/* =====================================\n   KEYFRAMES\n===================================== */\n\n@keyframes headerFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes headerTextFade{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes menuFadeIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n@keyframes cardsEqualIn{\n  to{\n    opacity:1;\n    transform:translateY(0);\n  }\n}\n\n\n\n\n/* =====================================\n   SINGLE POST / PAGE SMOOTH REVEAL\n===================================== */\n\n/* За single post + pages */\nbody.single .site-content,\nbody.page .site-content{\n  opacity: 0;\n  transform: translateY(18px);\n  animation: contentIn .6s ease forwards;\n  animation-delay: .08s;\n}\n\n/* Малку побавно за насловот */\nbody.single .entry-header,\nbody.page .entry-header{\n  opacity: 0;\n  transform: translateY(12px);\n  animation: contentIn .55s ease forwards;\n  animation-delay: .18s;\n}\n\n/* Слика (ако има) */\nbody.single .post-thumb img,\nbody.page .post-thumb img{\n  opacity: 0;\n  transform: scale(0.98);\n  animation: imgIn .65s ease forwards;\n  animation-delay: .12s;\n}\n\n/* Keyframes */\n@keyframes contentIn{\n  to{\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@keyframes imgIn{\n  to{\n    opacity: 1;\n    transform: scale(1);\n  }\n}\n\n\n\n\n/* =========================\n   FOOTER MINIMAL STYLE\n========================= */\n\n.site-footer{\n    background:#111;\n    color:#fff;\n    border-top:3px solid #c62828;\n}\n\n.site-footer a{\n    color:#fff;\n    text-decoration:none;\n    transition:.2s ease;\n}\n\n.site-footer a:hover{\n    color:#c62828;\n}\n\n/* footer columns spacing */\n.footer-widget-area{\n    padding:40px 0;\n}\n\n/* titles */\n.site-footer strong{\n    font-size:16px;\n    letter-spacing:.5px;\n}\n\n/* social icons */\n.footer-social-inner-wrap a{\n    background:#222;\n    border-radius:6px;\n    padding:8px;\n}\n\n.footer-social-inner-wrap a:hover{\n    background:#c62828;\n}\n\n/* copyright line */\n.ast-footer-copyright{\n    border-top:1px solid rgba(255,255,255,.1);\n    padding-top:12px;\n    margin-top:20px;\n    font-size:13px;\n}\n\n\n\n','astra','','inherit','closed','closed','','309-revision-v1','','','2026-02-20 19:53:25','2026-02-20 19:53:25','',309,'https://user17.delovna.finki.ukim.mk/?p=2167',0,'revision','',0);
